/* ===================== JALUR TAMBAHAN =====================
   Dibuat oleh tools/gen/rute.py. Jangan diedit langsung. */
const UI_MODULES=[{"t": "Fondasi desain antarmuka", "lvl": "Pemula", "d": "Hierarki visual, prinsip Gestalt, grid 8 poin, perataan dan keseimbangan, serta jarak untuk kepadatan dan keterbacaan.", "nodes": ["Visual hierarchy", "Gestalt", "8-point grid", "Alignment", "Spacing"], "lessons": [{"k": "w", "t": "Hierarki visual", "nodes": [], "b": ["<b>Hierarki visual</b> adalah urutan mata pengguna membaca layar: apa yang dilihat pertama, kedua, dan terakhir. Desainer mengatur urutan itu dengan <b>ukuran</b>, <b>ketebalan</b>, <b>warna dan kontras</b>, <b>posisi</b>, serta <b>ruang kosong</b> di sekitar elemen.", "Aturan praktis: setiap layar punya <b>satu</b> hal terpenting (judul, angka utama, atau tombol aksi utama). Jika semua elemen sama besar dan sama tebal, mata tidak tahu harus mulai dari mana, dan pengguna merasa layar itu \"ramai\" walau isinya sedikit.", "Uji cepat: <b>squint test</b>. Sipitkan mata sampai layar buram. Elemen yang masih terlihat jelas adalah puncak hierarkimu. Jika yang menonjol justru label kecil atau ikon dekoratif, hierarkinya terbalik.", "Kartu produk di pratinjau dibuat rata semua: judul, harga, dan deskripsi sama ukuran. Perbaiki hierarkinya."], "html": "<article class=\"kartu\">\n  <p class=\"kategori\">Kopi susu</p>\n  <h2 class=\"judul\">Es Kopi Gula Aren</h2>\n  <p class=\"harga\">Rp18.000</p>\n  <p class=\"desk\">Espresso, susu segar, dan gula aren asli dari Banten.</p>\n  <button class=\"aksi\">Tambah ke keranjang</button>\n</article>", "css": "body { font-family: system-ui, sans-serif; background: #F4F1EC; margin: 0; padding: 24px; color: #2B2724; }\n.kartu { max-width: 320px; background: #fff; border-radius: 16px; padding: 24px; }\n.kartu p, .kartu h2 { font-size: 16px; font-weight: 400; margin: 0 0 8px; }\n.kategori { color: #7A716A; }\n.aksi { margin-top: 16px; width: 100%; padding: 12px; border: 0; border-radius: 10px; background: #8A4B2A; color: #fff; font-size: 16px; }", "task": {"q": "Jadikan judul puncak hierarki: <code>.judul</code> minimal 24px dan tebal minimal 700. Buat <code>.harga</code> tebal minimal 600.", "test": "parseFloat(getComputedStyle(document.querySelector('.judul')).fontSize)>=24&&getComputedStyle(document.querySelector('.judul')).fontWeight>=700&&getComputedStyle(document.querySelector('.harga')).fontWeight>=600", "hint": ".kartu .judul { font-size: 24px; font-weight: 700 } dan .kartu .harga { font-weight: 600 }. Pakai selector .kartu .judul agar lebih kuat dari .kartu h2."}, "pts": ["Hierarki diatur dengan ukuran, tebal, kontras, posisi, dan ruang kosong.", "Satu layar, satu hal terpenting.", "Squint test untuk memeriksa hierarki."], "q": [["Apa tanda hierarki visual yang buruk?", ["Semua elemen sama besar dan sama tebal", "Judul lebih besar dari deskripsi", "Ada satu tombol utama"], 0, "Mata tidak tahu harus mulai dari mana."], ["Squint test dipakai untuk?", ["Mengukur kontras warna secara pasti", "Melihat elemen mana yang paling menonjol", "Menguji kecepatan muat"], 1, "Yang tetap terlihat saat buram adalah puncak hierarki."]], "so": [{"q": "Lakukan squint test pada halaman beranda aplikasi bank atau e-commerce di ponselmu. Tulis tiga elemen yang paling menonjol, lalu nilai: apakah itu memang yang terpenting?", "h": "Sipitkan mata atau buramkan tangkapan layar. Bandingkan dengan tujuan utama halaman.", "a": "Contoh jawaban (aplikasi e-commerce):\n1. Banner promo besar  → menonjol, tapi bukan tujuan utama pengguna\n2. Kolom pencarian      → seharusnya paling menonjol\n3. Ikon keranjang       → cukup\nRekomendasi: perbesar kolom pencarian, kecilkan banner.", "lang": "text"}, {"q": "Tulis CSS untuk kartu notifikasi dengan hierarki: judul 18px tebal 700, isi 14px abu-abu tua, waktu 12px abu-abu.", "h": "Bedakan dengan ukuran, tebal, dan warna sekaligus.", "a": ".notif-judul { font-size: 18px; font-weight: 700; color: #111827; }\n.notif-isi   { font-size: 14px; color: #374151; }\n.notif-waktu { font-size: 12px; color: #6B7280; }", "lang": "css"}]}, {"k": "w", "t": "Prinsip Gestalt", "nodes": [], "b": ["<b>Gestalt</b> adalah prinsip psikologi tentang cara otak mengelompokkan apa yang dilihat. Lima yang paling sering dipakai di UI: <b>proximity</b> (yang berdekatan dianggap satu kelompok), <b>similarity</b> (yang mirip dianggap sejenis), <b>common region</b> (yang berada di satu bingkai dianggap satu kelompok), <b>closure</b> (otak melengkapi bentuk yang terputus), dan <b>figure-ground</b> (memisahkan objek dari latar).", "Proximity paling sering salah di form. Jika jarak label ke input-nya <b>sama</b> dengan jarak label ke input di atasnya, pengguna ragu label itu milik input yang mana. Aturannya: jarak <b>di dalam</b> kelompok harus jelas lebih kecil daripada jarak <b>antar</b> kelompok.", "Similarity dipakai untuk link dan tombol: semua yang bisa diklik memakai warna yang sama, dan warna itu tidak dipakai untuk teks biasa. Common region dipakai untuk kartu: satu kartu, satu produk.", "Form di pratinjau punya jarak yang sama di mana-mana. Perbaiki dengan proximity."], "html": "<form class=\"form\">\n  <div class=\"grup\"><label class=\"lbl\" for=\"n\">Nama lengkap</label><input id=\"n\"></div>\n  <div class=\"grup\"><label class=\"lbl\" for=\"e\">Email</label><input id=\"e\" type=\"email\"></div>\n  <div class=\"grup\"><label class=\"lbl\" for=\"p\">Nomor HP</label><input id=\"p\" type=\"tel\"></div>\n</form>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; color: #1F2933; }\n.form { max-width: 320px; }\n.grup { margin-bottom: 12px; }\n.lbl { display: block; font-size: 14px; font-weight: 600; margin-bottom: 12px; }\ninput { width: 100%; box-sizing: border-box; padding: 10px 12px; border: 1px solid #9AA5B1; border-radius: 8px; font-size: 16px; }", "task": {"q": "Terapkan proximity: jarak label ke input (<code>.lbl</code> margin-bottom) maksimal 8px, dan jarak antar <code>.grup</code> minimal 24px.", "test": "parseFloat(getComputedStyle(document.querySelector('.lbl')).marginBottom)<=8&&parseFloat(getComputedStyle(document.querySelector('.grup')).marginBottom)>=24", "hint": ".lbl { margin-bottom: 4px } .grup { margin-bottom: 24px }"}, "pts": ["Proximity: jarak di dalam kelompok lebih kecil dari jarak antar kelompok.", "Similarity: yang bisa diklik punya satu gaya yang konsisten.", "Common region: satu bingkai, satu kelompok."], "q": [["Label berjarak 12px ke input-nya dan 12px ke input di atasnya. Prinsip apa yang dilanggar?", ["Similarity", "Proximity", "Closure"], 1, "Jarak yang sama membuat kelompok tidak jelas."], ["Semua link berwarna biru dan bergaris bawah. Ini memakai prinsip?", ["Similarity", "Figure-ground", "Closure"], 0, "Elemen yang mirip dianggap sejenis."]], "so": [{"q": "Sebutkan prinsip Gestalt yang dipakai pada: (a) kartu produk berbingkai, (b) semua tautan berwarna sama, (c) ikon lingkaran putus-putus yang tetap terbaca sebagai lingkaran.", "h": "Common region, similarity, closure.", "a": "(a) Common region\n(b) Similarity\n(c) Closure", "lang": "text"}, {"q": "Tulis CSS jarak untuk daftar pengaturan: jarak judul grup ke item pertama 8px, antar item 4px, antar grup 32px.", "h": "Jarak di dalam kelompok lebih kecil dari jarak antar kelompok.", "a": ".grup { margin-bottom: 32px; }\n.grup h3 { margin: 0 0 8px; }\n.grup .item + .item { margin-top: 4px; }", "lang": "css"}]}, {"k": "w", "t": "Grid 8 poin", "nodes": [], "b": ["<b>Grid 8 poin</b> berarti semua ukuran dan jarak memakai kelipatan 8: 8, 16, 24, 32, 40, 48, 64. Untuk penyesuaian halus (ikon, jarak teks kecil) boleh setengahnya, 4. Material Design, Apple, dan hampir semua design system memakai sistem ini.", "Kenapa 8? Layar umum (360, 768, 1280, 1440 px) habis dibagi 8, dan kelipatan 8 tetap utuh saat diskalakan 1,5× atau 2× di layar beresolusi tinggi. Yang lebih penting: tim tidak perlu berdebat apakah jarak itu 13 atau 14 piksel. Pilihannya terbatas, keputusan lebih cepat, dan hasilnya konsisten.", "Di Figma, atur <b>nudge amount</b> (Shift + panah) menjadi 8, aktifkan layout grid 8 px, dan pakai nilai spacing auto layout dari skala yang sama. Di kode, simpan skalanya sebagai token: <code>--space-1: 8px; --space-2: 16px; ...</code>.", "Kartu di pratinjau memakai angka acak (13px, 7px, 10px). Rapikan ke grid 8."], "html": "<section class=\"kartu\">\n  <h3>Kelas Flutter Dasar</h3>\n  <p>12 pelajaran · 4 jam</p>\n  <ul class=\"daftar\"><li>Widget dan layout</li><li>State dan form</li><li>Navigasi</li></ul>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\n.kartu { max-width: 320px; padding: 13px 7px; border: 1px solid #D5D9E0; border-radius: 10px; }\n.kartu h3 { margin: 0 0 5px; }\n.daftar { display: grid; gap: 10px; padding-left: 20px; }", "task": {"q": "Ubah padding <code>.kartu</code> dan <code>gap</code> pada <code>.daftar</code> menjadi kelipatan 8 (misalnya padding 24px, gap 8px).", "test": "(s=>['paddingTop','paddingRight','paddingBottom','paddingLeft'].every(k=>parseFloat(s[k])%8===0))(getComputedStyle(document.querySelector('.kartu')))&&parseFloat(getComputedStyle(document.querySelector('.daftar')).rowGap)%8===0", "hint": ".kartu { padding: 24px } .daftar { gap: 8px }"}, "pts": ["Semua jarak dan ukuran kelipatan 8, setengahnya 4 untuk detail.", "Pilihan terbatas mempercepat keputusan dan menjaga konsistensi.", "Simpan skala sebagai token spacing."], "q": [["Mana yang TIDAK mengikuti grid 8 poin?", ["24px", "40px", "18px"], 2, "18 bukan kelipatan 8 (atau 4)."], ["Keuntungan utama grid 8 poin bagi tim?", ["Warna lebih cerah", "Pilihan jarak terbatas sehingga konsisten", "Ukuran file lebih kecil"], 1, "Tidak ada lagi perdebatan 13 atau 14 piksel."]], "so": [{"q": "Rapikan nilai berikut ke grid 8 (atau 4 untuk detail): 13, 18, 22, 30, 45, 6.", "h": "Bulatkan ke kelipatan 8 terdekat; nilai kecil boleh 4.", "a": "13 → 12 atau 16\n18 → 16\n22 → 24\n30 → 32\n45 → 48\n6  → 4 atau 8", "lang": "text"}, {"q": "Buat token spacing skala 8 dari 4 sampai 64 sebagai CSS variables.", "h": "Satu variabel per langkah.", "a": ":root {\n  --space-0-5: 4px;\n  --space-1: 8px;\n  --space-2: 16px;\n  --space-3: 24px;\n  --space-4: 32px;\n  --space-5: 40px;\n  --space-6: 48px;\n  --space-8: 64px;\n}", "lang": "css"}]}, {"k": "w", "t": "Perataan dan keseimbangan", "nodes": [], "b": ["<b>Perataan</b> (alignment) membuat elemen terasa terhubung walau berjauhan. Setiap elemen sebaiknya sejajar dengan sesuatu: tepi kiri judul sejajar dengan tepi kiri paragraf, tombol sejajar dengan input di atasnya. Di Figma, perhatikan garis merah petunjuk saat menggeser elemen.", "Untuk teks lebih dari dua baris, <b>rata kiri</b> paling mudah dibaca, karena mata selalu kembali ke titik awal yang sama. Rata tengah cocok untuk judul pendek atau empty state, tetapi melelahkan untuk paragraf. Jangan mencampur rata kiri dan rata tengah dalam satu kartu.", "<b>Keseimbangan</b> adalah sebaran \"berat visual\" di layar. <b>Simetris</b> terasa formal dan stabil (halaman login). <b>Asimetris</b> terasa dinamis (hero dengan teks di kiri dan gambar besar di kanan), tetapi tetap butuh grid agar tidak terlihat berantakan.", "Kartu di pratinjau mencampur rata tengah dan rata kiri. Samakan perataannya."], "html": "<article class=\"isi\">\n  <h3 class=\"tengah\">Promo Akhir Bulan</h3>\n  <p>Diskon 20% untuk semua kelas mobile sampai 30 November.</p>\n  <p class=\"tengah\">Gunakan kode RUANG20 saat pembayaran.</p>\n  <a href=\"#\">Lihat syarat</a>\n</article>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.isi { max-width: 340px; padding: 24px; background: #FFF7E6; border-radius: 12px; }\n.isi > * { margin: 0 0 8px; }\n.tengah { text-align: center; }", "task": {"q": "Buat semua isi kartu rata kiri, sejajar satu garis.", "test": "[...document.querySelectorAll('.isi > *')].every(e=>['left','start'].includes(getComputedStyle(e).textAlign))", "hint": "Ubah .tengah { text-align: left } atau hapus kelas tengah dari elemen."}, "pts": ["Setiap elemen sejajar dengan sesuatu.", "Paragraf: rata kiri. Rata tengah hanya untuk teks pendek.", "Simetris terasa stabil, asimetris terasa dinamis."], "q": [["Perataan paling mudah dibaca untuk paragraf panjang?", ["Rata tengah", "Rata kiri", "Rata kanan"], 1, "Mata kembali ke titik awal yang sama setiap baris."], ["Hero dengan teks di kiri dan foto besar di kanan adalah keseimbangan?", ["Simetris", "Asimetris"], 1, "Berat visual tidak dicerminkan."]], "so": [{"q": "Halaman login: logo, judul, dua input, tombol, dan link \"Lupa sandi\". Usulkan perataan dan keseimbangannya, beri alasan.", "h": "Login sederhana cocok simetris; input dan tombol sejajar satu kolom.", "a": "Keseimbangan simetris: satu kolom di tengah, lebar maks 400px.\nLogo dan judul rata tengah (teks pendek).\nLabel, input, tombol rata kiri dalam kolom yang sama, lebar penuh.\nLink \"Lupa sandi\" rata kanan di bawah field sandi, sejajar tepi kanan input.", "lang": "text"}]}, {"k": "w", "t": "Jarak untuk kepadatan dan keterbacaan", "nodes": [], "b": ["<b>Kepadatan</b> (density) adalah seberapa banyak informasi di satu layar. Aplikasi kasir, dashboard, dan tabel data butuh kepadatan <b>tinggi</b> agar pengguna ahli melihat banyak data sekaligus. Aplikasi belajar, onboarding, dan halaman marketing butuh kepadatan <b>rendah</b> agar nyaman dibaca.", "Tiga alat pengatur kepadatan: <b>padding</b> di dalam komponen (sel tabel, tombol), <b>gap</b> antar elemen, dan <b>line-height</b> teks. Untuk paragraf, line-height 1,4 sampai 1,6 kali ukuran huruf. Untuk sel tabel, padding vertikal 8 px (padat) sampai 16 px (lega).", "Banyak design system menyediakan <b>mode kepadatan</b>: comfortable dan compact. Material 3 menyebutnya density scale (0, -1, -2, -3), setiap tingkat mengurangi tinggi komponen 4 dp. Jangan memadatkan target sentuh di bawah 44 sampai 48 px di ponsel.", "Tabel di pratinjau terlalu sesak untuk dibaca santai. Longgarkan."], "html": "<table class=\"tabel\">\n  <thead><tr><th>Kelas</th><th>Siswa</th><th>Selesai</th></tr></thead>\n  <tbody>\n    <tr><td>Flutter Dasar</td><td>1.240</td><td>68%</td></tr>\n    <tr><td>Kotlin Pemula</td><td>980</td><td>72%</td></tr>\n    <tr><td>UI Design</td><td>1.530</td><td>81%</td></tr>\n  </tbody>\n</table>\n<p class=\"teks\">Persentase selesai dihitung dari siswa yang menuntaskan semua pelajaran dan kuis dalam 60 hari sejak mendaftar.</p>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; color: #1F2933; }\n.tabel { border-collapse: collapse; width: 100%; max-width: 420px; font-size: 14px; }\n.tabel th, .tabel td { padding: 2px 4px; border-bottom: 1px solid #E4E7EB; text-align: left; }\n.teks { max-width: 420px; font-size: 14px; line-height: 1.1; }", "task": {"q": "Beri sel tabel padding vertikal minimal 12px, dan paragraf <code>.teks</code> line-height minimal 1.5.", "test": "parseFloat(getComputedStyle(document.querySelector('.tabel td')).paddingTop)>=12&&parseFloat(getComputedStyle(document.querySelector('.teks')).lineHeight)/parseFloat(getComputedStyle(document.querySelector('.teks')).fontSize)>=1.5", "hint": ".tabel th, .tabel td { padding: 12px 16px } .teks { line-height: 1.6 }"}, "pts": ["Kepadatan tinggi untuk pengguna ahli, rendah untuk bacaan santai.", "Atur dengan padding, gap, dan line-height.", "Target sentuh tetap 44 sampai 48 px."], "q": [["Dashboard gudang untuk staf yang memantau ratusan barang paling cocok dengan kepadatan?", ["Tinggi", "Rendah"], 0, "Pengguna ahli butuh melihat banyak data sekaligus."], ["Line-height yang nyaman untuk paragraf?", ["1.0", "1.4 sampai 1.6", "3.0"], 1, "Cukup lega tanpa terlihat terpisah-pisah."]], "so": [{"q": "Buat dua mode kepadatan tabel dengan atribut data: comfortable (padding sel 16px) dan compact (padding sel 8px).", "h": "Pakai selector atribut pada tabel.", "a": "table[data-density=\"comfortable\"] td { padding: 16px; }\ntable[data-density=\"compact\"] td { padding: 8px 12px; }", "lang": "css"}]}]}, {"t": "Sistem tipografi digital", "lvl": "Pemula", "d": "Memilih typeface, skala tipe modular, line height, tracking, panjang baris, peran tipografi semantik, dan tipografi responsif.", "nodes": ["Typeface", "Type scale", "Line height", "Text styles", "Responsive type"], "lessons": [{"k": "w", "t": "Memilih typeface", "nodes": [], "b": ["<b>Typeface</b> (keluarga huruf) membawa kepribadian. <b>Sans-serif</b> (Inter, Plus Jakarta Sans, Roboto) netral dan jelas di layar, pilihan aman untuk UI. <b>Serif</b> (Lora, Merriweather) terasa editorial dan tepercaya, cocok untuk judul atau bacaan panjang. <b>Monospace</b> (JetBrains Mono) untuk kode dan angka yang harus sejajar.", "Kriteria memilih font UI: (1) tinggi huruf kecil (<b>x-height</b>) cukup besar agar terbaca di ukuran 12 sampai 14 px, (2) bentuk <b>I l 1</b> dan <b>O 0</b> mudah dibedakan, (3) punya cukup <b>ketebalan</b> (400, 500, 600, 700), (4) mendukung karakter bahasa target, dan (5) lisensinya jelas. Google Fonts aman untuk proyek komersial.", "Batasi <b>maksimal dua keluarga</b>: satu untuk judul, satu untuk isi, atau satu keluarga saja dengan beberapa ketebalan. Font sistem (<code>system-ui</code>) memuat instan dan terasa \"asli\" di setiap perangkat, sehingga banyak aplikasi besar memakainya.", "Halaman di pratinjau memakai font dekoratif untuk teks UI. Ganti dengan font sistem."], "html": "<main class=\"hal\">\n  <h1>Pengaturan akun</h1>\n  <p>Ubah nama, email, dan kata sandi. Perubahan email perlu dikonfirmasi lewat tautan yang kami kirim.</p>\n  <p class=\"kecil\">Kode verifikasi: Il1O0 · terakhir diubah 12/11/2026</p>\n</main>", "css": "body { margin: 0; padding: 24px; font-family: \"Brush Script MT\", \"Comic Sans MS\", cursive; color: #1F2933; }\n.hal { max-width: 420px; }\n.kecil { font-size: 13px; color: #52606D; }", "task": {"q": "Ganti <code>font-family</code> body menjadi tumpukan font sistem yang diawali <code>system-ui</code>.", "test": "getComputedStyle(document.body).fontFamily.startsWith('system-ui')", "hint": "body { font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif }"}, "pts": ["Sans-serif untuk UI, serif untuk editorial, mono untuk kode.", "Periksa x-height, I l 1 dan O 0, ketebalan, dan lisensi.", "Maksimal dua keluarga huruf."], "q": [["Kenapa bentuk I, l, dan 1 harus mudah dibedakan?", ["Agar estetis", "Agar kode, password, dan angka tidak salah baca", "Agar file lebih kecil"], 1, "Salah baca karakter bisa membuat pengguna gagal login."], ["Berapa keluarga huruf maksimal yang disarankan dalam satu produk?", ["Dua", "Empat", "Tidak ada batas"], 0, "Lebih dari itu terasa tidak konsisten."]], "so": [{"q": "Pilih pasangan font untuk aplikasi belajar anak SD dan untuk aplikasi laporan keuangan perusahaan. Jelaskan alasannya.", "h": "Pertimbangkan kepribadian, keterbacaan angka, dan x-height.", "a": "Aplikasi anak: Nunito atau Baloo 2 (bulat, ramah, x-height besar) + font sistem untuk teks panjang.\nLaporan keuangan: Inter atau IBM Plex Sans (netral, angka tabular sejajar) + IBM Plex Mono untuk kode akun.", "lang": "text"}, {"q": "Tulis tag link Google Fonts untuk Plus Jakarta Sans ketebalan 400, 600, 700 dan CSS pemakaiannya dengan fallback.", "h": "Pakai display=swap dan tumpukan fallback sistem.", "a": "<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n\n<style>\n  body { font-family: \"Plus Jakarta Sans\", system-ui, sans-serif; }\n</style>", "lang": "html"}]}, {"k": "w", "t": "Skala tipe modular", "nodes": [], "b": ["<b>Skala tipe modular</b> adalah daftar ukuran huruf yang dihitung dari <b>ukuran dasar</b> dikali <b>rasio</b> berulang. Dasar 16 px dengan rasio 1,25 (major third): 16 → 20 → 25 → 31,25 → 39. Dengan rasio 1,2 (minor third): 16 → 19,2 → 23 → 27,6.", "Rasio kecil (1,125 sampai 1,2) cocok untuk aplikasi padat dan layar kecil, karena beda antar tingkat halus. Rasio besar (1,333 sampai 1,5) cocok untuk halaman marketing dengan judul besar. Hasil hitungan biasanya dibulatkan ke angka genap atau kelipatan 4.", "Keuntungannya: ukuran huruf tidak dipilih asal-asalan, sehingga semua judul terasa satu keluarga. Di CSS, rasio bisa disimpan sebagai variabel dan dihitung dengan <code>calc()</code>, sehingga mengubah satu angka mengubah seluruh skala.", "Pratinjau memakai rasio 1,5, terlalu dramatis untuk halaman aplikasi. Ubah rasionya."], "html": "<div class=\"contoh\">\n  <h1>Judul halaman (fs-3)</h1>\n  <h2>Subjudul (fs-2)</h2>\n  <h3>Judul kartu (fs-1)</h3>\n  <p>Teks isi memakai ukuran dasar 16 px.</p>\n</div>", "css": ":root {\n  --r: 1.5;\n  --fs-0: 1rem;\n  --fs-1: calc(var(--fs-0) * var(--r));\n  --fs-2: calc(var(--fs-1) * var(--r));\n  --fs-3: calc(var(--fs-2) * var(--r));\n}\nbody { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\nh1 { font-size: var(--fs-3); margin: 0 0 8px; }\nh2 { font-size: var(--fs-2); margin: 0 0 8px; }\nh3 { font-size: var(--fs-1); margin: 0 0 8px; }\np { font-size: var(--fs-0); }", "task": {"q": "Ubah <code>--r</code> menjadi <b>1.25</b> (major third). h1 akan menjadi sekitar 31,25px.", "test": "Math.abs(parseFloat(getComputedStyle(document.querySelector('h1')).fontSize)-31.25)<0.6", "hint": ":root { --r: 1.25 }"}, "pts": ["Skala = ukuran dasar × rasio berulang.", "Rasio kecil untuk aplikasi, besar untuk marketing.", "Simpan rasio di variabel agar mudah diubah."], "q": [["Dasar 16 dan rasio 1,25. Berapa tingkat kedua (16 × 1,25 × 1,25)?", ["20", "25", "32"], 1, "16 × 1,5625 = 25."], ["Aplikasi kasir yang padat cocok dengan rasio?", ["1.125 sampai 1.2", "1.5 sampai 1.618"], 0, "Beda antar tingkat halus, hemat ruang."]], "so": [{"q": "Hitung skala tipe dasar 16 dengan rasio 1,2 untuk 4 tingkat ke atas, lalu bulatkan ke bilangan bulat.", "h": "16 × 1,2 berulang.", "a": "16\n16 × 1,2 = 19,2  → 19 (atau 20)\n19,2 × 1,2 = 23,04 → 23 (atau 24)\n23,04 × 1,2 = 27,65 → 28\n27,65 × 1,2 = 33,18 → 33 (atau 32)", "lang": "text"}]}, {"k": "w", "t": "Line height, tracking, dan panjang baris", "nodes": [], "b": ["<b>Line height</b> (leading) adalah jarak antar baris. Paragraf butuh 1,4 sampai 1,6; judul besar cukup 1,1 sampai 1,25, karena jarak yang terlalu lega membuat baris judul terlihat terpisah.", "<b>Tracking</b> (letter-spacing) adalah jarak antar huruf. Teks kecil berhuruf kapital (label, overline) butuh tracking positif sekitar 0,04 sampai 0,1 em agar terbaca. Judul sangat besar justru sedikit dirapatkan (-0,01 sampai -0,02 em).", "<b>Panjang baris</b> (measure) yang nyaman adalah <b>45 sampai 75 karakter</b>, ideal sekitar 65. Baris terlalu panjang membuat mata kehilangan awal baris berikutnya. Di CSS, satuan <code>ch</code> (lebar karakter 0) pas untuk ini: <code>max-width: 65ch</code>.", "Artikel di pratinjau terlalu rapat dan terlalu lebar di layar besar. Perbaiki."], "html": "<article class=\"artikel\">\n  <p class=\"overline\">Tips belajar</p>\n  <h2>Belajar 30 menit sehari lebih efektif daripada 5 jam sekali seminggu</h2>\n  <p class=\"isi\">Otak memperkuat ingatan saat kita mengulang materi dengan jeda. Teknik ini disebut spaced repetition. Mulailah dengan satu pelajaran pendek, kerjakan kuisnya, lalu ulangi pelajaran yang sama dua hari kemudian sebelum lanjut ke materi baru.</p>\n</article>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; color: #1F2933; }\n.overline { font-size: 12px; text-transform: uppercase; color: #8A4B2A; margin: 0; }\nh2 { font-size: 28px; line-height: 1.6; margin: 8px 0 16px; }\n.isi { font-size: 17px; line-height: 1.15; }", "task": {"q": "Atur: <code>.artikel</code> max-width 65ch, <code>.isi</code> line-height 1.6, dan <code>.overline</code> letter-spacing positif.", "test": "getComputedStyle(document.querySelector('.artikel')).maxWidth!=='none'&&parseFloat(getComputedStyle(document.querySelector('.isi')).lineHeight)/17>=1.5&&parseFloat(getComputedStyle(document.querySelector('.overline')).letterSpacing)>0", "hint": ".artikel { max-width: 65ch } .isi { line-height: 1.6 } .overline { letter-spacing: 0.08em }"}, "pts": ["Paragraf 1,4–1,6; judul besar 1,1–1,25.", "Label kapital kecil: tracking positif.", "Panjang baris 45–75 karakter, max-width: 65ch."], "q": [["Panjang baris ideal untuk paragraf?", ["20 karakter", "Sekitar 65 karakter", "150 karakter"], 1, "Antara 45 dan 75."], ["Label kecil huruf kapital sebaiknya diberi tracking?", ["Positif", "Negatif", "Nol"], 0, "Huruf kapital kecil terlihat terlalu rapat tanpa tracking."]], "so": [{"q": "Tulis CSS untuk: overline 12px kapital tracking 0.08em, judul 32px line-height 1.2 tracking -0.01em, paragraf 17px line-height 1.6 max 65ch.", "h": "Tiga aturan terpisah.", "a": ".overline { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; }\nh1 { font-size: 32px; line-height: 1.2; letter-spacing: -0.01em; }\np { font-size: 17px; line-height: 1.6; max-width: 65ch; }", "lang": "css"}]}, {"k": "w", "t": "Peran tipografi semantik", "nodes": [], "b": ["Daripada menamai gaya teks dengan ukurannya (\"Inter 24 Bold\"), design system modern menamainya dengan <b>peran</b>: <b>display</b> (angka atau judul sangat besar), <b>headline</b> (judul halaman), <b>title</b> (judul kartu dan dialog), <b>body</b> (isi), dan <b>label</b> (tombol, tab, chip, keterangan kecil). Material 3 memakai lima peran ini, masing-masing dalam ukuran large, medium, dan small.", "Kenapa peran? Karena ukuran bisa berubah (misalnya di tablet semua sedikit lebih besar), tetapi peran tidak. Developer cukup menulis <code>title-medium</code>, dan jika desainer mengubah ukurannya, seluruh aplikasi ikut berubah.", "Setiap peran adalah paket: ukuran, line-height, ketebalan, tracking, dan kadang huruf kapital. Di Figma, simpan sebagai <b>Text Style</b> dengan nama bertingkat seperti <code>Title/Medium</code>. Di kode, simpan sebagai kelas atau token.", "Pratinjau sudah punya kelas peran, tetapi <code>.label</code> belum lengkap."], "html": "<section class=\"kartu\">\n  <p class=\"label\">Progres minggu ini</p>\n  <p class=\"display\">86%</p>\n  <h3 class=\"title\">Kelas UI Design</h3>\n  <p class=\"body\">Kamu sudah menyelesaikan 26 dari 30 pelajaran. Tinggal modul handoff.</p>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; color: #1D1B20; }\n.kartu { max-width: 340px; padding: 24px; border-radius: 16px; background: #F3EDF7; }\n.kartu > * { margin: 0 0 8px; }\n.display { font-size: 45px; line-height: 52px; font-weight: 400; letter-spacing: 0; }\n.title { font-size: 16px; line-height: 24px; font-weight: 500; letter-spacing: 0.15px; }\n.body { font-size: 14px; line-height: 20px; font-weight: 400; letter-spacing: 0.25px; }\n.label { font-size: 12px; line-height: 16px; }", "task": {"q": "Lengkapi peran <code>.label</code>: tebal 500, huruf kapital (<code>uppercase</code>), dan letter-spacing positif.", "test": "(s=>s.fontWeight>=500&&s.textTransform==='uppercase'&&parseFloat(s.letterSpacing)>0)(getComputedStyle(document.querySelector('.label')))", "hint": ".label { font-weight: 500; text-transform: uppercase; letter-spacing: 0.5px }"}, "pts": ["Namai gaya teks dengan peran, bukan ukuran.", "Peran: display, headline, title, body, label.", "Satu peran = paket ukuran, line-height, tebal, tracking."], "q": [["Nama gaya teks mana yang paling tahan perubahan?", ["Inter-24-Bold", "title-large", "Besar-Hitam"], 1, "Peran tidak berubah walau ukurannya diubah."], ["Teks pada tombol dan tab memakai peran?", ["display", "label", "body"], 1, "Label untuk teks kontrol yang pendek."]], "so": [{"q": "Buat token peran tipografi headline-small, title-medium, body-large, dan label-large sebagai CSS variables shorthand <code>font</code>.", "h": "Shorthand font: tebal ukuran/line-height keluarga.", "a": ":root {\n  --font-family: system-ui, sans-serif;\n  --headline-small: 400 24px/32px var(--font-family);\n  --title-medium: 500 16px/24px var(--font-family);\n  --body-large: 400 16px/24px var(--font-family);\n  --label-large: 500 14px/20px var(--font-family);\n}\nh2 { font: var(--headline-small); }", "lang": "css"}]}, {"k": "w", "t": "Tipografi responsif", "nodes": [], "b": ["Ukuran judul yang pas di laptop (48 px) terlalu besar di ponsel 360 px, dan sebaliknya. Cara lama memakai <b>media query</b>: 28 px di ponsel, lalu 40 px mulai lebar 768 px. Hasilnya melompat di titik tertentu.", "Cara modern memakai <b>tipografi fluid</b> dengan <code>clamp(minimum, ideal, maksimum)</code>: <code>font-size: clamp(1.75rem, 1rem + 3vw, 3rem)</code>. Ukuran tumbuh halus mengikuti lebar layar, tetapi tidak pernah di bawah 28 px atau di atas 48 px. Bagian ideal selalu campuran <code>rem</code> dan <code>vw</code>, agar teks tetap ikut membesar saat pengguna memperbesar ukuran huruf di pengaturan browser.", "Teks isi biasanya cukup 16 px sampai 18 px tanpa fluid. Jangan pernah membuat teks isi di bawah 16 px di ponsel, karena iOS akan otomatis memperbesar halaman saat input bertulisan lebih kecil dari 16 px difokuskan.", "Ubah judul hero di pratinjau menjadi fluid. Lalu ubah lebar jendela pratinjau untuk melihatnya tumbuh."], "html": "<header class=\"hero\">\n  <h1>Belajar coding dari nol, dalam Bahasa Indonesia</h1>\n  <p>Gratis, interaktif, dan bisa dipakai offline.</p>\n</header>", "css": "body { font-family: system-ui, sans-serif; margin: 0; }\n.hero { padding: 32px 16px; background: #0F172A; color: #F8FAFC; }\n.hero h1 { font-size: 48px; line-height: 1.15; margin: 0 0 12px; }\n.hero p { font-size: 18px; margin: 0; color: #CBD5E1; }", "task": {"q": "Ganti <code>font-size</code> judul <code>.hero h1</code> dengan <code>clamp()</code>, misalnya <code>clamp(1.75rem, 1rem + 3vw, 3rem)</code>.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.style&&/clamp\\(/.test(r.style.fontSize))", "hint": ".hero h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem) }"}, "pts": ["clamp(min, ideal, max) untuk ukuran fluid.", "Bagian ideal campur rem dan vw agar zoom tetap bekerja.", "Teks isi minimal 16 px di ponsel."], "q": [["Kenapa bagian ideal clamp sebaiknya memakai rem + vw, bukan vw saja?", ["Agar teks tetap membesar saat pengguna menambah ukuran huruf", "Agar lebih cepat", "Wajib di CSS"], 0, "vw saja mengabaikan pengaturan ukuran huruf pengguna."], ["clamp(1.75rem, 1rem + 3vw, 3rem) di layar sangat lebar menghasilkan?", ["1.75rem", "3rem", "Tak terbatas"], 1, "Dibatasi nilai maksimum."]], "so": [{"q": "Buat judul fluid dari 24px (layar 360px) sampai 40px, dan subjudul dari 18px sampai 24px.", "h": "clamp(min, rem + vw, max).", "a": "h1 { font-size: clamp(1.5rem, 1rem + 2.5vw, 2.5rem); }\nh2 { font-size: clamp(1.125rem, 1rem + 1vw, 1.5rem); }", "lang": "css"}]}]}, {"t": "Teori warna dan aksesibilitas", "lvl": "Menengah", "d": "Properti warna dan model warna layar, kontras WCAG, palet tint dan shade, warna semantik untuk state, dan dark mode.", "nodes": ["Color models", "WCAG contrast", "Palette", "Semantic color", "Dark mode"], "lessons": [{"k": "w", "t": "Properti warna dan model warna layar", "nodes": [], "b": ["Setiap warna punya tiga properti: <b>hue</b> (rona: merah, biru, hijau, diukur 0 sampai 360 derajat di roda warna), <b>saturation</b> (kepekatan: abu-abu sampai menyala), dan <b>lightness</b> atau value (gelap sampai terang).", "Layar membuat warna dari cahaya merah, hijau, dan biru: model <b>RGB</b>, ditulis heksadesimal (<code>#8A4B2A</code>) atau <code>rgb(138 75 42)</code>. Untuk desainer, <b>HSL</b> lebih intuitif: <code>hsl(21 53% 35%)</code>, karena membuat versi lebih terang cukup menaikkan angka lightness. Model <b>OKLCH</b> yang lebih baru membuat perubahan lightness terasa merata di semua hue, sehingga kini dipakai Tailwind v4.", "Cetak memakai <b>CMYK</b> (tinta), bukan RGB. Itulah sebabnya warna yang menyala di layar bisa terlihat kusam saat dicetak. Untuk produk digital, bekerja di ruang warna sRGB (atau Display P3 untuk layar modern) dan selalu cek di perangkat nyata.", "Tombol di pratinjau memakai HSL dengan hue dari variabel. Ubah hue-nya."], "html": "<div class=\"baris\">\n  <button class=\"tombol\">Daftar sekarang</button>\n  <span class=\"kode\">hsl(var(--hue) 70% 40%)</span>\n</div>", "css": ":root { --hue: 21; }\nbody { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.baris { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; }\n.tombol { background: hsl(var(--hue) 70% 40%); color: #fff; border: 0; padding: 12px 24px; border-radius: 10px; font-size: 16px; }\n.kode { font-family: ui-monospace, monospace; color: #52606D; }", "task": {"q": "Ubah <code>--hue</code> menjadi <b>210</b> agar tombol menjadi biru, tanpa menyentuh saturation dan lightness.", "test": "getComputedStyle(document.documentElement).getPropertyValue('--hue').trim()==='210'", "hint": ":root { --hue: 210 }"}, "pts": ["Hue, saturation, lightness.", "Layar memakai RGB; HSL dan OKLCH lebih mudah diatur desainer.", "Cetak memakai CMYK, warna bisa berbeda."], "q": [["Untuk membuat versi warna lebih terang di HSL, ubah?", ["Hue", "Saturation", "Lightness"], 2, "Lightness mengatur gelap-terang."], ["Hue 120 kira-kira berwarna?", ["Merah", "Hijau", "Biru"], 1, "0 merah, 120 hijau, 240 biru."]], "so": [{"q": "Ubah warna hsl(210 70% 40%) menjadi versi lebih terang untuk latar, versi lebih gelap untuk teks, dan versi abu-abu.", "h": "Ubah lightness untuk terang-gelap, saturation untuk abu-abu.", "a": "Latar terang : hsl(210 70% 94%)\nTeks gelap   : hsl(210 70% 22%)\nAbu-abu      : hsl(210 8% 40%)", "lang": "text"}]}, {"k": "w", "t": "Kontras WCAG", "nodes": [], "b": ["<b>WCAG</b> (Web Content Accessibility Guidelines) mengukur kontras sebagai rasio luminansi dua warna, dari 1:1 (sama) sampai 21:1 (hitam di atas putih). Standar <b>AA</b> yang dipakai hampir semua regulasi: teks normal minimal <b>4,5:1</b>, teks besar (24 px, atau 18,66 px tebal) minimal <b>3:1</b>, dan komponen UI seperti border input dan ikon minimal <b>3:1</b>. Level AAA: 7:1.", "Pelanggaran paling umum: teks abu-abu muda di atas putih. <code>#9CA3AF</code> di atas putih hanya 2,5:1, terlihat \"elegan\" di monitor desainer, tetapi tidak terbaca di bawah sinar matahari atau oleh pengguna lansia. <code>#6B7280</code> sudah 4,8:1.", "Alat cek: plugin Figma (Stark, Contrast), panel Accessibility di Chrome DevTools, atau webaim.org/resources/contrastchecker. Tes otomatis di bawah menghitung rasio dengan rumus WCAG yang sama.", "Teks keterangan di pratinjau gagal AA. Gelapkan warnanya."], "html": "<div class=\"kartu\">\n  <h3>Ujian akhir modul</h3>\n  <p class=\"ket\">Dibuka Senin, 10 November 2026 pukul 08.00 WIB. Durasi 45 menit.</p>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #fff; }\n.kartu { max-width: 340px; padding: 24px; border: 1px solid #E5E7EB; border-radius: 12px; background: #FFFFFF; }\nh3 { margin: 0 0 8px; color: #111827; }\n.ket { margin: 0; font-size: 15px; color: #9CA3AF; }", "task": {"q": "Ubah warna <code>.ket</code> agar kontrasnya dengan latar putih minimal <b>4.5:1</b> (misalnya <code>#4B5563</code>).", "test": "(()=>{const L=(c=>{const v=c.match(/[\\d.]+/g).slice(0,3).map(x=>{x/=255;return x<=0.03928?x/12.92:((x+0.055)/1.055)**2.4});return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2]}),a=L(getComputedStyle(document.querySelector('.ket')).color);return (1.05)/(a+0.05)>=4.5})()", "hint": ".ket { color: #4B5563 } memberi rasio sekitar 7,6:1."}, "pts": ["AA: teks normal 4,5:1, teks besar dan komponen UI 3:1.", "Abu-abu muda di atas putih adalah pelanggaran paling umum.", "Cek dengan plugin Figma atau DevTools."], "q": [["Kontras minimal teks normal untuk WCAG AA?", ["3:1", "4.5:1", "7:1"], 1, "7:1 untuk AAA."], ["Border input harus berkontras minimal berapa terhadap latarnya?", ["1.5:1", "3:1", "4.5:1"], 1, "Komponen UI non-teks: 3:1."]], "so": [{"q": "Nilai pasangan ini terhadap WCAG AA: (a) teks #FFFFFF di atas #1D5FA8, (b) teks #9CA3AF di atas #FFFFFF, (c) border input #D1D5DB di atas #FFFFFF.", "h": "Teks normal 4,5:1, komponen UI 3:1.", "a": "(a) sekitar 6,4:1 → lulus AA untuk teks\n(b) sekitar 2,5:1 → gagal (butuh 4,5:1)\n(c) sekitar 1,5:1 → gagal untuk komponen UI (butuh 3:1); pakai #6B7280 atau lebih gelap", "lang": "text"}, {"q": "Tulis gaya placeholder yang tetap lulus kontras 4,5:1 di atas putih.", "h": "Gelapkan abu-abunya.", "a": "input::placeholder { color: #6B7280; opacity: 1; }", "lang": "css"}]}, {"k": "w", "t": "Palet tint dan shade", "nodes": [], "b": ["Satu warna merek tidak cukup. UI butuh <b>skala</b>: versi sangat terang untuk latar (50, 100), menengah untuk border (200, 300), warna utama (500, 600), dan gelap untuk teks dan hover (700, 800, 900). <b>Tint</b> = dicampur putih (lebih terang), <b>shade</b> = dicampur hitam (lebih gelap).", "Cara membuat skala: tentukan warna utama di tingkat 500 atau 600, lalu ubah <b>lightness</b> bertahap dengan hue tetap. Sedikit menggeser hue dan menaikkan saturasi di tingkat gelap membuat warna terlihat lebih hidup. Alat bantu: uicolors.app, Tailwind palette generator, atau <code>color-mix(in oklch, warna 60%, black)</code> di CSS modern.", "Skala ini juga kunci aksesibilitas: pasangan yang aman biasanya berjarak minimal 4 sampai 5 tingkat, misalnya teks 800 di atas latar 100, atau teks putih di atas tombol 600.", "Palet di pratinjau baru sampai 700. Tambahkan tingkat 900."], "html": "<div class=\"palet\">\n  <div class=\"chip c100\">100</div><div class=\"chip c300\">300</div><div class=\"chip c500\">500</div><div class=\"chip c700\">700</div>\n</div>\n<p class=\"contoh\">Lencana: <span class=\"lencana\">Terverifikasi</span></p>", "css": ":root { --h: 152; }\nbody { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\n.palet { display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 8px; }\n.chip { height: 64px; border-radius: 10px; display: grid; place-items: end start; padding: 6px; font-size: 12px; }\n.c100 { background: hsl(var(--h) 60% 92%); }\n.c300 { background: hsl(var(--h) 55% 72%); }\n.c500 { background: hsl(var(--h) 60% 42%); color: #fff; }\n.c700 { background: hsl(var(--h) 65% 28%); color: #fff; }\n.lencana { background: hsl(var(--h) 60% 92%); color: hsl(var(--h) 65% 28%); padding: 2px 10px; border-radius: 99px; }", "task": {"q": "Tambahkan chip <code>&lt;div class=\"chip c900\"&gt;900&lt;/div&gt;</code> dan beri <code>.c900</code> latar yang lebih gelap dari 700 (misalnya lightness 16%) dengan teks putih.", "test": "(()=>{const L=(c=>{const v=c.match(/[\\d.]+/g).slice(0,3).map(x=>{x/=255;return x<=0.03928?x/12.92:((x+0.055)/1.055)**2.4});return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2]}),a=document.querySelector('.c900'),b=document.querySelector('.c700');return !!a&&L(getComputedStyle(a).backgroundColor)<L(getComputedStyle(b).backgroundColor)})()", "hint": "HTML: <div class=\"chip c900\">900</div>. CSS: .c900 { background: hsl(var(--h) 70% 16%); color: #fff }"}, "pts": ["Skala 50–900: terang untuk latar, gelap untuk teks.", "Tint dicampur putih, shade dicampur hitam.", "Pasangan aman berjarak 4–5 tingkat."], "q": [["Tingkat mana yang cocok untuk latar lencana yang lembut?", ["100", "600", "900"], 0, "Tingkat terang untuk latar."], ["Shade dibuat dengan mencampur warna dengan?", ["Putih", "Hitam", "Abu-abu"], 1, "Tint dengan putih, shade dengan hitam."]], "so": [{"q": "Buat skala 100 sampai 900 (5 tingkat) untuk hue 352 (merah merek) memakai hsl.", "h": "Hue tetap, lightness turun.", "a": ":root {\n  --red-100: hsl(352 85% 94%);\n  --red-300: hsl(352 75% 76%);\n  --red-500: hsl(352 70% 50%);\n  --red-700: hsl(352 75% 34%);\n  --red-900: hsl(352 80% 18%);\n}", "lang": "css"}]}, {"k": "w", "t": "Warna semantik untuk state", "nodes": [], "b": ["<b>Warna semantik</b> diberi nama berdasarkan <b>makna</b>, bukan rupanya: <code>success</code> (hijau), <code>warning</code> (kuning atau oranye), <code>error</code> atau <code>danger</code> (merah), dan <code>info</code> (biru). Setiap makna punya pasangan latar lembut, border, dan teks gelap dari skala yang sama.", "Aturan WCAG 1.4.1: <b>warna tidak boleh menjadi satu-satunya penanda</b>. Sekitar 1 dari 12 laki-laki buta warna merah-hijau. Jadi field error diberi warna merah <b>dan</b> ikon <b>dan</b> pesan teks yang menjelaskan. Status pesanan diberi warna <b>dan</b> label \"Lunas\" atau \"Batal\".", "Jangan memakai merah untuk hal yang bukan bahaya atau error (misalnya warna merek), karena pengguna akan mengira ada masalah. Di Indonesia, merah juga dipakai untuk harga diskon; itu boleh, selama konsisten dan tidak dicampur dengan pesan error di layar yang sama.", "Alert ketiga di pratinjau seharusnya error, tetapi tampil seperti info biasa."], "html": "<div class=\"alert success\"><b>✓</b> Pembayaran berhasil diterima.</div>\n<div class=\"alert warning\"><b>!</b> Kuota tersisa 2 kursi.</div>\n<div class=\"alert info\"><b>i</b> Kartu kredit ditolak oleh bank.</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; display: grid; gap: 8px; max-width: 420px; }\n.alert { padding: 12px 16px; border-radius: 10px; border-left: 4px solid; display: flex; gap: 10px; }\n.success { background: #E7F6EC; border-color: #1E7B45; color: #14532D; }\n.warning { background: #FFF4E0; border-color: #B45309; color: #7C2D12; }\n.info { background: #E8F1FB; border-color: #1D5FA8; color: #173B66; }\n.error { background: #FDECEC; border-color: #B42318; color: #7A1A12; }", "task": {"q": "Ubah alert ketiga menjadi state error: ganti kelas <code>info</code> menjadi <code>error</code>, ganti ikonnya menjadi <b>✕</b>, dan awali pesannya dengan kata <b>Gagal:</b> agar tidak bergantung pada warna saja.", "test": "(a=>!!a&&a.textContent.includes('Gagal')&&a.textContent.includes('✕'))(document.querySelector('.alert.error'))", "hint": "<div class=\"alert error\"><b>✕</b> Gagal: kartu kredit ditolak oleh bank.</div>"}, "pts": ["Namai warna berdasarkan makna: success, warning, error, info.", "Warna tidak boleh satu-satunya penanda: tambahkan ikon dan teks.", "Merah hanya untuk bahaya dan error."], "q": [["Field error hanya diberi border merah. Apa masalahnya?", ["Tidak ada", "Pengguna buta warna tidak tahu ada error", "Merah terlalu terang"], 1, "WCAG 1.4.1: jangan mengandalkan warna saja."], ["Nama token mana yang semantik?", ["--red-600", "--color-error", "--merah-tua"], 1, "Menyebut makna, bukan rupa."]], "so": [{"q": "Tulis markup field error yang tidak bergantung pada warna saja: label, input dengan aria-invalid, ikon, dan pesan yang terhubung.", "h": "aria-invalid dan aria-describedby.", "a": "<label for=\"hp\">Nomor HP</label>\n<input id=\"hp\" type=\"tel\" aria-invalid=\"true\" aria-describedby=\"hp-err\">\n<p id=\"hp-err\" class=\"error\"><span aria-hidden=\"true\">⚠</span> Nomor HP minimal 10 digit, contoh: 081234567890</p>", "lang": "html"}]}, {"k": "w", "t": "Dark mode", "nodes": [], "b": ["Dark mode bukan sekadar membalik warna. Prinsipnya: (1) latar <b>abu-abu sangat gelap</b> (#121212 sampai #1C1B1F), bukan hitam murni, agar bayangan dan lapisan tetap terlihat; (2) teks <b>putih yang sedikit diredam</b> (sekitar 87% opasitas) agar tidak menyilaukan; (3) <b>elevasi</b> ditunjukkan dengan latar yang sedikit lebih terang, bukan bayangan; (4) warna aksen <b>dikurangi saturasinya</b> dan dinaikkan lightness-nya (tingkat 200 sampai 300), karena warna pekat bergetar di atas latar gelap.", "Implementasi yang rapi memakai <b>token</b>: komponen hanya memakai <code>var(--bg)</code>, <code>var(--fg)</code>, <code>var(--surface)</code>. Lalu tema gelap cukup mendefinisikan ulang nilai token di <code>@media (prefers-color-scheme: dark)</code> atau di <code>[data-theme=\"dark\"]</code>.", "Kontras tetap wajib diuji di kedua tema. Gambar dan ilustrasi juga perlu dicek: logo hitam akan hilang di latar gelap.", "Aplikasi di pratinjau sudah memakai token, tetapi tema gelapnya belum ditulis."], "html": "<div class=\"app\" data-theme=\"dark\">\n  <div class=\"kartu\">\n    <h3>Ringkasan belajar</h3>\n    <p>3 pelajaran selesai hari ini.</p>\n    <button>Lanjutkan</button>\n  </div>\n</div>", "css": ":root, [data-theme=\"light\"] { --bg: #FFFFFF; --surface: #F3F4F6; --fg: #111827; --accent: #1D5FA8; --on-accent: #FFFFFF; }\n/* tulis token tema gelap di sini */\n\nbody { margin: 0; font-family: system-ui, sans-serif; }\n.app { background: var(--bg); color: var(--fg); padding: 24px; min-height: 100vh; box-sizing: border-box; }\n.kartu { background: var(--surface); padding: 24px; border-radius: 16px; max-width: 320px; }\nbutton { background: var(--accent); color: var(--on-accent); border: 0; padding: 10px 20px; border-radius: 10px; }", "task": {"q": "Tulis aturan <code>[data-theme=\"dark\"]</code> yang mengisi token: <code>--bg: #121417</code>, <code>--surface: #1E2227</code>, <code>--fg: #E6E8EB</code>, <code>--accent: #8DB8F2</code>, <code>--on-accent: #0B1B33</code>.", "test": "(()=>{const L=(c=>{const v=c.match(/[\\d.]+/g).slice(0,3).map(x=>{x/=255;return x<=0.03928?x/12.92:((x+0.055)/1.055)**2.4});return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2]});return L(getComputedStyle(document.querySelector('.app')).backgroundColor)<0.05&&L(getComputedStyle(document.querySelector('.app')).color)>0.6})()", "hint": "[data-theme=\"dark\"] { --bg: #121417; --surface: #1E2227; --fg: #E6E8EB; --accent: #8DB8F2; --on-accent: #0B1B33 }"}, "pts": ["Latar abu-abu sangat gelap, bukan hitam murni.", "Elevasi dengan latar lebih terang, aksen lebih lembut.", "Komponen memakai token, tema hanya mengganti nilainya."], "q": [["Kenapa latar dark mode tidak hitam murni #000?", ["Agar bayangan dan lapisan tetap terlihat dan tidak terlalu kontras", "Hitam tidak didukung browser", "Agar hemat baterai"], 0, "Abu-abu gelap memberi ruang untuk elevasi."], ["Di dark mode, kartu yang \"lebih tinggi\" ditunjukkan dengan?", ["Bayangan lebih tebal", "Latar sedikit lebih terang", "Border merah"], 1, "Bayangan hampir tidak terlihat di latar gelap."]], "so": [{"q": "Tulis token warna untuk tema terang dan gelap yang mengikuti pengaturan sistem, dengan penimpa manual lewat data-theme.", "h": "Bare :root, media query dengan :not, dan [data-theme].", "a": ":root { --bg: #FFFFFF; --fg: #111827; --surface: #F3F4F6; }\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) { --bg: #121417; --fg: #E6E8EB; --surface: #1E2227; }\n}\n:root[data-theme=\"dark\"] { --bg: #121417; --fg: #E6E8EB; --surface: #1E2227; }\nbody { background: var(--bg); color: var(--fg); }", "lang": "css"}]}]}, {"t": "Arsitektur komponen", "lvl": "Menengah", "d": "Anatomi input form, state dan hierarki tombol, kartu, modal, sheet, dan popover, serta auto layout dan batasan tata letak dinamis.", "nodes": ["Form input", "Button states", "Cards", "Overlays", "Auto layout"], "lessons": [{"k": "w", "t": "Anatomi input form", "nodes": [], "b": ["Input form yang lengkap terdiri dari: <b>label</b> (selalu terlihat, di atas input), <b>field</b> (kotak isian), <b>placeholder</b> opsional (contoh format, bukan pengganti label), <b>helper text</b> (petunjuk di bawah), <b>pesan error</b> (menggantikan helper saat salah), serta penanda <b>wajib</b> atau <b>opsional</b>.", "Kesalahan paling umum: memakai placeholder sebagai label. Saat pengguna mulai mengetik, placeholder hilang dan pengguna lupa field itu untuk apa. Placeholder juga biasanya abu-abu muda dan gagal kontras.", "Di kode, label harus terhubung ke input dengan <code>&lt;label for=\"id\"&gt;</code>, agar pembaca layar menyebutkan labelnya dan mengklik label ikut memfokuskan input. Pesan error dihubungkan dengan <code>aria-describedby</code>, dan field yang salah diberi <code>aria-invalid=\"true\"</code>.", "Field email di pratinjau hanya punya placeholder. Tambahkan label yang terhubung."], "html": "<form class=\"form\">\n  <div class=\"field\">\n    <input id=\"email\" type=\"email\" placeholder=\"Email\" aria-describedby=\"email-help\">\n    <p id=\"email-help\" class=\"help\">Kami kirim kode verifikasi ke alamat ini.</p>\n  </div>\n</form>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; color: #1F2933; }\n.form { max-width: 320px; }\nlabel { display: block; font-size: 14px; font-weight: 600; margin-bottom: 4px; }\ninput { width: 100%; box-sizing: border-box; padding: 12px; font-size: 16px; border: 1px solid #7B8794; border-radius: 8px; }\ninput:focus { outline: 2px solid #1D5FA8; outline-offset: 2px; }\n.help { font-size: 13px; color: #52606D; margin: 4px 0 0; }", "task": {"q": "Tambahkan <code>&lt;label for=\"email\"&gt;Email&lt;/label&gt;</code> di atas input, lalu ubah placeholder menjadi contoh format seperti <code>nama@contoh.com</code>.", "test": "!!document.querySelector('label[for=\"email\"]')&&document.getElementById('email').placeholder.includes('@')", "hint": "<label for=\"email\">Email</label> sebelum <input ... placeholder=\"nama@contoh.com\">"}, "pts": ["Label selalu terlihat, placeholder hanya contoh format.", "label for menghubungkan label ke input.", "Error: aria-invalid dan aria-describedby."], "q": [["Kenapa placeholder tidak boleh menggantikan label?", ["Hilang saat mengetik dan biasanya kontrasnya rendah", "Tidak didukung browser", "Membuat form lebih lambat"], 0, "Pengguna lupa field itu untuk apa."], ["Atribut apa yang menghubungkan pesan error ke input?", ["aria-describedby", "title", "name"], 0, "Pembaca layar membacakan pesan itu saat input difokuskan."]], "so": [{"q": "Buat field kata sandi lengkap: label, input, helper \"Minimal 8 karakter\", dan tombol tampilkan sandi dengan aria-label.", "h": "Helper dihubungkan dengan aria-describedby.", "a": "<label for=\"sandi\">Kata sandi</label>\n<div class=\"sandi\">\n  <input id=\"sandi\" type=\"password\" aria-describedby=\"sandi-help\" autocomplete=\"new-password\">\n  <button type=\"button\" aria-label=\"Tampilkan kata sandi\">👁</button>\n</div>\n<p id=\"sandi-help\">Minimal 8 karakter.</p>", "lang": "html"}]}, {"k": "w", "t": "State dan hierarki tombol", "nodes": [], "b": ["<b>Hierarki tombol</b>: <b>primary</b> (latar penuh, satu per layar untuk aksi utama), <b>secondary</b> (garis tepi atau latar lembut), <b>tertiary</b> atau text button (hanya teks, untuk aksi ringan seperti \"Batal\"). Aksi berbahaya (hapus) memakai warna danger, dan sebaiknya bukan tombol yang paling menonjol.", "Setiap tombol butuh tujuh <b>state</b>: default, <b>hover</b> (desktop), <b>focus-visible</b> (navigasi keyboard), <b>pressed</b> atau active, <b>disabled</b>, <b>loading</b>, dan kadang <b>selected</b>. State yang paling sering terlupa adalah focus: tanpa garis fokus yang jelas, pengguna keyboard tidak tahu sedang berada di mana.", "Gunakan <code>:focus-visible</code>, bukan <code>:focus</code>, agar garis fokus muncul saat navigasi keyboard tetapi tidak saat tombol diklik dengan mouse. WCAG 2.2 meminta indikator fokus yang jelas: garis minimal 2 px dengan kontras 3:1.", "Tombol di pratinjau sudah punya hover dan disabled, tetapi belum punya fokus. Tekan Tab di pratinjau untuk melihat masalahnya."], "html": "<div class=\"aksi\">\n  <button class=\"btn primary\">Simpan</button>\n  <button class=\"btn secondary\">Pratinjau</button>\n  <button class=\"btn tertiary\">Batal</button>\n  <button class=\"btn primary\" disabled>Kirim</button>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.aksi { display: flex; gap: 8px; flex-wrap: wrap; }\n.btn { font: inherit; font-weight: 600; padding: 10px 20px; border-radius: 10px; border: 1px solid transparent; cursor: pointer; outline: none; min-height: 44px; }\n.primary { background: #1D5FA8; color: #fff; }\n.primary:hover { background: #174C86; }\n.secondary { background: #fff; color: #1D5FA8; border-color: #1D5FA8; }\n.secondary:hover { background: #E8F1FB; }\n.tertiary { background: transparent; color: #1D5FA8; }\n.btn:disabled { background: #E4E7EB; color: #7B8794; border-color: transparent; cursor: not-allowed; }", "task": {"q": "Tambahkan aturan <code>.btn:focus-visible</code> dengan <code>outline</code> minimal 2px dan <code>outline-offset</code> 2px.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText&&r.selectorText.includes(':focus-visible')&&parseFloat(r.style.outlineWidth)>=2)", "hint": ".btn:focus-visible { outline: 3px solid #F59E0B; outline-offset: 2px }"}, "pts": ["Primary satu per layar, secondary, tertiary.", "State: default, hover, focus-visible, pressed, disabled, loading.", "Focus-visible minimal 2 px, kontras 3:1."], "q": [["Berapa tombol primary yang disarankan dalam satu layar?", ["Satu", "Tiga", "Sebanyak mungkin"], 0, "Satu aksi utama yang jelas."], ["Kenapa memakai :focus-visible, bukan :focus?", ["Garis fokus muncul untuk keyboard, tidak saat diklik mouse", "Lebih cepat", ":focus sudah usang"], 0, "Tetap aksesibel tanpa mengganggu pengguna mouse."]], "so": [{"q": "Tulis state loading untuk tombol: teks disembunyikan, muncul spinner, dan tombol tidak bisa diklik.", "h": "Pakai atribut aria-busy dan pointer-events.", "a": ".btn[aria-busy=\"true\"] { color: transparent; pointer-events: none; position: relative; }\n.btn[aria-busy=\"true\"]::after {\n  content: \"\"; position: absolute; inset: 0; margin: auto; width: 18px; height: 18px;\n  border: 2px solid #fff; border-right-color: transparent; border-radius: 50%;\n  animation: putar .7s linear infinite;\n}\n@keyframes putar { to { transform: rotate(360deg); } }", "lang": "css"}]}, {"k": "w", "t": "Kartu", "nodes": [], "b": ["<b>Kartu</b> mengelompokkan informasi tentang <b>satu hal</b>: satu produk, satu artikel, satu kelas. Anatominya: <b>media</b> (gambar), <b>header</b> (judul, subjudul), <b>isi</b> singkat, dan <b>aksi</b>. Tidak semua bagian wajib, tetapi urutannya sebaiknya konsisten di seluruh produk.", "Gambar di kartu harus punya <b>rasio tetap</b> (16:9, 4:3, atau 1:1), agar grid kartu rapi walau foto aslinya berbeda ukuran. Di CSS: <code>aspect-ratio: 16 / 9</code> dengan <code>object-fit: cover</code>. Di Figma: frame dengan rasio tetap dan gambar mode Fill.", "Jika seluruh kartu bisa diklik, jangan taruh terlalu banyak tombol di dalamnya, karena target klik bertumpuk membingungkan. Pilih: kartu yang bisa diklik dengan satu tujuan, atau kartu statis dengan tombol aksi yang jelas.", "Area media di kartu pratinjau belum punya rasio, sehingga tingginya nol."], "html": "<article class=\"kartu\">\n  <div class=\"media\" role=\"img\" aria-label=\"Ilustrasi kelas Flutter\"></div>\n  <div class=\"isi\">\n    <p class=\"label\">Mobile · Pemula</p>\n    <h3>Flutter dari Nol</h3>\n    <p>Bangun aplikasi Android dan iOS pertamamu dalam 4 minggu.</p>\n    <a href=\"#\" class=\"aksi\">Lihat kelas</a>\n  </div>\n</article>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; background: #F4F5F7; }\n.kartu { max-width: 320px; background: #fff; border-radius: 16px; overflow: hidden; box-shadow: 0 1px 3px rgb(0 0 0 / .12); }\n.media { width: 100%; background: linear-gradient(135deg, #0D5DB8, #63D9B5); }\n.isi { padding: 16px 24px 24px; }\n.isi > * { margin: 0 0 8px; }\n.label { font-size: 12px; color: #52606D; text-transform: uppercase; letter-spacing: .06em; }\n.aksi { color: #0D5DB8; font-weight: 600; }", "task": {"q": "Beri <code>.media</code> rasio <code>aspect-ratio: 16 / 9</code>.", "test": "getComputedStyle(document.querySelector('.media')).aspectRatio.replace(/\\s/g,'')==='16/9'", "hint": ".media { aspect-ratio: 16 / 9 }"}, "pts": ["Satu kartu, satu hal.", "Media dengan rasio tetap dan object-fit: cover.", "Pilih: seluruh kartu bisa diklik, atau tombol aksi yang jelas."], "q": [["Kenapa gambar kartu diberi aspect-ratio tetap?", ["Agar grid rapi walau ukuran foto asli berbeda", "Agar gambar lebih tajam", "Agar file kecil"], 0, "Tinggi kartu menjadi seragam."], ["Kartu yang seluruhnya bisa diklik berisi 4 tombol berbeda. Masalahnya?", ["Target klik bertumpuk dan membingungkan", "Tidak ada", "Kartu terlalu kecil"], 0, "Pilih satu pola interaksi."]], "so": [{"q": "Buat grid kartu 1 sampai 4 kolom otomatis dengan gambar 4:3 yang tidak gepeng.", "h": "auto-fill minmax dan object-fit.", "a": ".grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 16px; }\n.kartu img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; display: block; }", "lang": "css"}]}, {"k": "w", "t": "Modal, sheet, dan popover", "nodes": [], "b": ["Ketiganya adalah <b>lapisan</b> di atas konten. <b>Modal dialog</b> menghentikan alur dan meminta keputusan (konfirmasi hapus, form singkat); latar di belakangnya digelapkan (scrim) dan tidak bisa diklik. <b>Bottom sheet</b> muncul dari bawah layar ponsel, mudah dijangkau jempol, cocok untuk pilihan dan filter. <b>Popover</b> atau menu kecil menempel pada elemen pemicunya, tanpa menghentikan alur.", "Aturan pakai: modal hanya untuk hal yang <b>benar-benar butuh perhatian</b>, karena setiap modal memotong pekerjaan pengguna. Selalu sediakan cara keluar yang jelas (tombol tutup, tombol Batal, tombol Esc, tap di scrim). Di dalam modal, fokus keyboard harus terkunci (focus trap) dan kembali ke pemicu saat ditutup.", "Di HTML modern, pakai <code>&lt;dialog&gt;</code> dengan <code>showModal()</code> untuk modal, dan atribut <code>popover</code> untuk popover. Keduanya sudah menangani lapisan, Esc, dan aksesibilitas dasar.", "Sheet di pratinjau masih mengalir di dalam halaman. Tempelkan ke bawah layar."], "html": "<main class=\"hal\"><h2>Daftar kelas</h2><p>Ketuk Filter untuk menyaring kelas.</p></main>\n<div class=\"scrim\"></div>\n<section class=\"sheet\" aria-label=\"Filter\">\n  <div class=\"pegangan\"></div>\n  <h3>Filter kelas</h3>\n  <label><input type=\"checkbox\" checked> Gratis</label>\n  <label><input type=\"checkbox\"> Bersertifikat</label>\n  <button>Terapkan</button>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; min-height: 100vh; }\n.hal { padding: 16px; }\n.scrim { position: fixed; inset: 0; background: rgb(0 0 0 / .4); }\n.sheet { background: #fff; border-radius: 20px 20px 0 0; padding: 12px 24px 24px; display: grid; gap: 12px; z-index: 1; }\n.pegangan { width: 32px; height: 4px; border-radius: 2px; background: #9AA5B1; margin: 0 auto 8px; }\n.sheet h3 { margin: 0; }\n.sheet button { padding: 12px; border: 0; border-radius: 12px; background: #1D5FA8; color: #fff; font: inherit; font-weight: 600; }", "task": {"q": "Jadikan <code>.sheet</code> bottom sheet: <code>position: fixed</code>, menempel di bawah (<code>left: 0; right: 0; bottom: 0</code>).", "test": "(s=>s.position==='fixed'&&s.bottom==='0px'&&s.left==='0px')(getComputedStyle(document.querySelector('.sheet')))", "hint": ".sheet { position: fixed; left: 0; right: 0; bottom: 0 }"}, "pts": ["Modal menghentikan alur, sheet dari bawah, popover menempel pada pemicu.", "Selalu ada cara keluar: tutup, Batal, Esc, tap scrim.", "Pakai dialog dan atribut popover."], "q": [["Memilih urutan dan filter di ponsel paling nyaman dengan?", ["Modal di tengah", "Bottom sheet", "Halaman baru"], 1, "Mudah dijangkau jempol."], ["Apa itu scrim?", ["Lapisan gelap di belakang modal", "Animasi tombol", "Jenis font"], 0, "Menandakan konten di belakang tidak aktif."]], "so": [{"q": "Tulis modal konfirmasi hapus memakai elemen dialog, dengan tombol Batal dan Hapus.", "h": "dialog + form method=\"dialog\" menutup otomatis.", "a": "<button onclick=\"konfirmasi.showModal()\">Hapus kelas</button>\n<dialog id=\"konfirmasi\" aria-labelledby=\"judul-hapus\">\n  <h2 id=\"judul-hapus\">Hapus kelas ini?</h2>\n  <p>Progres belajar di kelas ini akan hilang.</p>\n  <form method=\"dialog\">\n    <button value=\"batal\">Batal</button>\n    <button value=\"hapus\" class=\"danger\">Hapus</button>\n  </form>\n</dialog>", "lang": "html"}]}, {"k": "w", "t": "Auto layout dan batasan tata letak dinamis", "nodes": [], "b": ["<b>Auto layout</b> di Figma membuat frame menyusun anaknya otomatis, persis seperti flexbox di CSS: arah (horizontal atau vertikal), <b>gap</b> (jarak antar anak), <b>padding</b>, dan perataan. Saat teks tombol berubah dari \"Simpan\" menjadi \"Simpan perubahan\", tombol ikut melebar sendiri.", "Setiap anak punya aturan ukuran: <b>Hug contents</b> (selebar isinya, sama dengan <code>width: auto</code>), <b>Fill container</b> (mengisi sisa ruang, sama dengan <code>flex: 1</code>), atau <b>Fixed</b> (ukuran tetap). Ditambah <b>min dan max width</b> agar tidak terlalu sempit atau lebar.", "<b>Constraints</b> (batasan) mengatur perilaku elemen saat frame induk diubah ukurannya: menempel kiri, kanan, kiri-dan-kanan (melar), tengah, atau skala. Desain yang memakai auto layout dan constraints dengan benar sudah \"responsif\" sejak di Figma, dan developer tinggal menerjemahkannya ke flex dan grid.", "Baris notifikasi di pratinjau: teks harus Fill, tombol harus Hug di kanan."], "html": "<div class=\"notif\">\n  <span class=\"ikon\">🔔</span>\n  <p class=\"isi\">Kelas Kotlin dimulai besok pukul 19.00 WIB.</p>\n  <button class=\"tutup\">Tutup</button>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; }\n.notif { display: flex; align-items: center; gap: 12px; padding: 12px 16px; background: #FFF7E6; border-radius: 12px; max-width: 520px; }\n.isi { margin: 0; }\n.tutup { font: inherit; border: 0; background: none; color: #8A4B2A; font-weight: 600; padding: 8px; }", "task": {"q": "Jadikan <code>.isi</code> Fill container (<code>flex: 1</code>) agar tombol Tutup terdorong ke kanan.", "test": "getComputedStyle(document.querySelector('.isi')).flexGrow==='1'", "hint": ".isi { flex: 1 }"}, "pts": ["Auto layout = flexbox: arah, gap, padding, perataan.", "Hug = auto, Fill = flex: 1, Fixed = ukuran tetap.", "Constraints mengatur perilaku saat induk diubah ukurannya."], "q": [["Fill container di Figma setara dengan CSS?", ["width: auto", "flex: 1", "position: absolute"], 1, "Mengisi sisa ruang."], ["Tombol yang melebar sendiri saat teksnya bertambah memakai?", ["Hug contents", "Fixed", "Constraints scale"], 0, "Selebar isinya."]], "so": [{"q": "Terjemahkan pengaturan Figma ini ke CSS: frame auto layout horizontal, gap 12, padding 16 24, align center; anak 1 Fixed 40×40, anak 2 Fill, anak 3 Hug.", "h": "flex, gap, padding, align-items, flex: none / 1.", "a": ".baris { display: flex; align-items: center; gap: 12px; padding: 16px 24px; }\n.anak1 { width: 40px; height: 40px; flex: none; }\n.anak2 { flex: 1; min-width: 0; }\n.anak3 { flex: none; }", "lang": "text"}]}]}, {"t": "Design system dan token", "lvl": "Menengah", "d": "Fondasi token, penamaan global dan alias, varian dan properti komponen, set ikon dan aset, serta dokumentasi pedoman pola.", "nodes": ["Design tokens", "Naming", "Variants", "Icons", "Documentation"], "lessons": [{"k": "w", "t": "Fondasi design token", "nodes": [], "b": ["<b>Design token</b> adalah keputusan desain yang diberi nama dan disimpan sebagai data: warna, ukuran huruf, jarak, radius, bayangan, durasi animasi. Bukan <code>#1D5FA8</code> yang ditulis di 40 tempat, melainkan <code>color.brand.600</code> yang dirujuk 40 kali. Mengubah satu token mengubah seluruh produk.", "Token ditulis sekali dalam format netral (JSON mengikuti spesifikasi DTCG, Design Tokens Community Group), lalu diubah otomatis menjadi CSS variables, konstanta Dart, Kotlin, atau Swift dengan alat seperti Style Dictionary. Di Figma, token disimpan sebagai <b>Variables</b>.", "Kategori token dasar: <b>color</b>, <b>typography</b> (keluarga, ukuran, tebal, line-height), <b>spacing</b>, <b>radius</b>, <b>shadow</b> atau elevation, <b>motion</b> (durasi, easing), dan <b>breakpoint</b>.", "Tombol di pratinjau masih memakai warna dan angka langsung. Ganti dengan token."], "html": "<button class=\"tombol\">Mulai belajar</button>", "css": ":root {\n  --color-brand-600: #1D5FA8;\n  --color-white: #FFFFFF;\n  --space-2: 16px;\n  --space-3: 24px;\n  --radius-md: 10px;\n}\nbody { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.tombol { background: #1D5FA8; color: #FFFFFF; padding: 16px 24px; border-radius: 10px; border: 0; font: inherit; font-weight: 600; }", "task": {"q": "Ubah <code>.tombol</code> agar semua nilainya memakai token: <code>var(--color-brand-600)</code>, <code>var(--color-white)</code>, <code>var(--space-2)</code>, <code>var(--space-3)</code>, dan <code>var(--radius-md)</code>.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.tombol'&&(r.style.cssText.match(/var\\(--/g)||[]).length>=4)", "hint": ".tombol { background: var(--color-brand-600); color: var(--color-white); padding: var(--space-2) var(--space-3); border-radius: var(--radius-md); ... }"}, "pts": ["Token = keputusan desain bernama, disimpan sebagai data.", "Format DTCG, diubah ke banyak platform dengan Style Dictionary.", "Kategori: color, typography, spacing, radius, shadow, motion."], "q": [["Keuntungan utama token?", ["Mengubah satu nilai mengubah seluruh produk", "File CSS lebih kecil", "Tidak perlu Figma"], 0, "Satu sumber kebenaran."], ["Di Figma, token disimpan sebagai?", ["Variables", "Frames", "Plugins"], 0, "Figma Variables mendukung mode seperti light dan dark."]], "so": [{"q": "Tulis token tombol dalam format JSON DTCG: warna latar, warna teks, dan radius.", "h": "Setiap token punya $value dan $type.", "a": "{\n  \"button\": {\n    \"bg\":     { \"$type\": \"color\",     \"$value\": \"{color.action.primary}\" },\n    \"text\":   { \"$type\": \"color\",     \"$value\": \"{color.white}\" },\n    \"radius\": { \"$type\": \"dimension\", \"$value\": \"10px\" }\n  }\n}", "lang": "text"}]}, {"k": "w", "t": "Penamaan token global dan alias", "nodes": [], "b": ["Token disusun dalam tiga lapis. <b>Global</b> atau primitive: nilai mentah tanpa makna, misalnya <code>blue-600: #1D5FA8</code>, <code>space-4: 16px</code>. <b>Alias</b> atau semantic: peran, merujuk ke global, misalnya <code>color-action-primary: {blue-600}</code>, <code>color-text-danger: {red-700}</code>. <b>Component</b>: khusus satu komponen, merujuk ke alias, misalnya <code>button-primary-bg: {color-action-primary}</code>.", "Komponen hanya boleh memakai token alias atau component, <b>tidak pernah</b> global langsung. Dengan begitu, rebranding dari biru ke hijau cukup mengubah satu baris alias. Dark mode cukup mengubah ke mana alias menunjuk.", "Pola penamaan yang umum: <b>kategori-peran-varian-state</b>, misalnya <code>color-bg-surface</code>, <code>color-text-muted</code>, <code>color-border-input-focus</code>. Pakai kata yang dipahami desainer dan developer, dan konsisten dalam satu bahasa.", "Pratinjau baru punya token global. Buat token alias untuk aksi utama."], "html": "<button class=\"tombol\">Bayar sekarang</button>", "css": ":root {\n  /* global */\n  --blue-600: #1D5FA8;\n  --green-600: #1E7B45;\n  --white: #FFFFFF;\n  /* alias: tulis di sini */\n}\nbody { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.tombol { background: var(--color-action-primary, #999); color: var(--white); border: 0; padding: 16px 24px; border-radius: 10px; font: inherit; font-weight: 600; }", "task": {"q": "Tambahkan token alias <code>--color-action-primary: var(--green-600)</code> di <code>:root</code>. Tombol akan berubah hijau tanpa menyentuh aturan <code>.tombol</code>.", "test": "getComputedStyle(document.documentElement).getPropertyValue('--color-action-primary').trim()!==''&&getComputedStyle(document.querySelector('.tombol')).backgroundColor==='rgb(30, 123, 69)'", "hint": ":root { --color-action-primary: var(--green-600) }"}, "pts": ["Tiga lapis: global, alias (semantic), component.", "Komponen tidak memakai token global langsung.", "Pola nama: kategori-peran-varian-state."], "q": [["Mana token alias?", ["--blue-600", "--color-text-danger", "#1D5FA8"], 1, "Menyebut peran, merujuk ke global."], ["Rebranding biru ke hijau paling mudah jika komponen memakai?", ["Token global", "Token alias", "Kode warna langsung"], 1, "Cukup ubah ke mana alias menunjuk."]], "so": [{"q": "Kelompokkan token ini ke global, alias, atau component: blue-600, color-text-muted, button-primary-bg, space-4, color-border-focus, card-radius.", "h": "Global = nilai mentah; alias = peran; component = khusus komponen.", "a": "Global    : blue-600, space-4\nAlias     : color-text-muted, color-border-focus\nComponent : button-primary-bg, card-radius", "lang": "text"}]}, {"k": "w", "t": "Varian dan properti komponen", "nodes": [], "b": ["Satu komponen punya banyak bentuk. Di Figma, bentuk-bentuk itu disusun sebagai <b>variants</b> dalam satu <b>component set</b>, dengan <b>properties</b>: <code>Size = sm | md | lg</code>, <code>Variant = primary | secondary | danger</code>, <code>State = default | hover | disabled</code>, <code>Icon = true | false</code>. Pengguna komponen tinggal memilih dari panel kanan.", "Selain variant property, Figma punya <b>boolean property</b> (tampilkan atau sembunyikan ikon), <b>text property</b> (ubah label tanpa membongkar komponen), dan <b>instance swap</b> (ganti ikon dengan ikon lain). Desain yang baik membatasi jumlah kombinasi agar tidak meledak: 3 ukuran × 3 varian × 4 state = 36 varian sudah banyak.", "Properti di Figma sebaiknya bernama sama dengan prop di kode: <code>&lt;Button size=\"lg\" variant=\"danger\"&gt;</code> di React, <code>Button(size = Size.Large)</code> di Compose. Di CSS, varian bisa memakai kelas modifier (<code>.btn--lg</code>) atau atribut data (<code>[data-size=\"lg\"]</code>).", "Tombol di pratinjau sudah punya ukuran sm dan md. Lengkapi ukuran lg."], "html": "<div class=\"baris\">\n  <button class=\"btn\" data-size=\"sm\">Kecil</button>\n  <button class=\"btn\" data-size=\"md\">Sedang</button>\n  <button class=\"btn\" data-size=\"lg\">Besar</button>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.baris { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.btn { font: inherit; font-weight: 600; border: 0; border-radius: 10px; background: #1D5FA8; color: #fff; box-sizing: border-box; }\n.btn[data-size=\"sm\"] { height: 32px; padding: 0 12px; font-size: 14px; }\n.btn[data-size=\"md\"] { height: 40px; padding: 0 16px; font-size: 15px; }", "task": {"q": "Tambahkan aturan <code>.btn[data-size=\"lg\"]</code> dengan tinggi <b>48px</b>, padding kiri-kanan 24px, dan font-size 16px.", "test": "Math.round(document.querySelector('[data-size=\"lg\"]').getBoundingClientRect().height)===48", "hint": ".btn[data-size=\"lg\"] { height: 48px; padding: 0 24px; font-size: 16px }"}, "pts": ["Variants dalam satu component set, diatur lewat properties.", "Boolean, text, dan instance swap property.", "Nama properti Figma = nama prop di kode."], "q": [["Menyembunyikan ikon di tombol Figma paling tepat memakai?", ["Variant baru", "Boolean property", "Detach instance"], 1, "Satu saklar tampil atau sembunyi."], ["Kenapa nama properti Figma sebaiknya sama dengan prop di kode?", ["Agar handoff jelas dan tidak perlu menerjemahkan", "Aturan Figma", "Agar file kecil"], 0, "Desainer dan developer memakai bahasa yang sama."]], "so": [{"q": "Rancang properti komponen Badge: ukuran, warna semantik, ikon. Hitung jumlah varian jika semua dibuat sebagai variant.", "h": "Kalikan jumlah nilai setiap properti; ikon sebaiknya boolean property.", "a": "Size    : sm, md                     (2)\nTone    : neutral, success, warning, error, info (5)\nIcon    : boolean property (bukan variant)\nJumlah variant = 2 × 5 = 10 (ikon tidak menggandakan karena boolean)", "lang": "text"}]}, {"k": "w", "t": "Set ikon dan aset", "nodes": [], "b": ["Ikon dalam satu produk harus berasal dari <b>satu set</b> dengan gaya seragam: grid yang sama (biasanya 24 × 24 dengan area aman 2 px), ketebalan garis sama (1,5 atau 2 px), sudut sama, dan gaya sama (outline atau filled). Set populer: Material Symbols, Lucide, Phosphor, Heroicons. Mencampur set membuat UI terasa \"tambal sulam\".", "Format: <b>SVG</b> untuk ikon dan ilustrasi sederhana (tajam di semua ukuran, bisa diwarnai dengan <code>currentColor</code>). <b>PNG</b> atau <b>WebP</b> untuk foto dan gambar kompleks, diekspor @1x, @2x, @3x untuk mobile. Di Figma, atur <b>Export settings</b> pada setiap aset dan beri nama dengan pola konsisten: <code>ic_cart_24.svg</code>, <code>img_onboarding_1@2x.png</code>.", "Aksesibilitas ikon: ikon dekoratif diberi <code>aria-hidden=\"true\"</code>. Tombol yang hanya berisi ikon <b>wajib</b> punya nama yang bisa dibaca: <code>aria-label=\"Keranjang\"</code>. Target sentuhnya tetap minimal 44 sampai 48 px walau ikonnya 24 px.", "Tombol keranjang di pratinjau hanya berisi ikon dan tidak punya nama."], "html": "<button class=\"ikon-btn\">\n  <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"9\" cy=\"20\" r=\"1.5\"/><circle cx=\"18\" cy=\"20\" r=\"1.5\"/><path d=\"M2 3h3l2.6 12.4a2 2 0 0 0 2 1.6h8.8a2 2 0 0 0 2-1.6L22 7H6\"/></svg>\n</button>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.ikon-btn { width: 48px; height: 48px; display: grid; place-items: center; border: 0; border-radius: 12px; background: #E8F1FB; color: #1D5FA8; }", "task": {"q": "Beri tombol <code>aria-label=\"Keranjang\"</code>, dan beri SVG di dalamnya <code>aria-hidden=\"true\"</code>.", "test": "(b=>b.getAttribute('aria-label')==='Keranjang'&&b.querySelector('svg').getAttribute('aria-hidden')==='true')(document.querySelector('.ikon-btn'))", "hint": "<button class=\"ikon-btn\" aria-label=\"Keranjang\"><svg aria-hidden=\"true\" ...>"}, "pts": ["Satu set ikon dengan grid, garis, dan gaya seragam.", "SVG untuk ikon, PNG/WebP @1x @2x @3x untuk gambar.", "Tombol ikon wajib punya aria-label, ikon dekoratif aria-hidden."], "q": [["Format terbaik untuk ikon yang perlu berubah warna mengikuti teks?", ["PNG", "SVG dengan currentColor", "JPG"], 1, "SVG tajam dan bisa diwarnai."], ["Tombol hanya berisi ikon tempat sampah. Apa yang wajib ditambahkan?", ["aria-label=\"Hapus\"", "title saja", "Tidak perlu apa-apa"], 0, "Pembaca layar butuh nama tombol."]], "so": [{"q": "Buat aturan penamaan file untuk 3 ikon dan 2 ilustrasi onboarding yang diekspor untuk Android dan iOS.", "h": "Pola: jenis_nama_ukuran, kepadatan @2x @3x.", "a": "ic_home_24.svg\nic_search_24.svg\nic_cart_24.svg\nimg_onboarding_1.png, img_onboarding_1@2x.png, img_onboarding_1@3x.png\nimg_onboarding_2.png, img_onboarding_2@2x.png, img_onboarding_2@3x.png", "lang": "text"}]}, {"k": "w", "t": "Dokumentasi pedoman pola", "nodes": [], "b": ["Komponen tanpa dokumentasi akan dipakai dengan cara yang berbeda-beda oleh setiap orang. Halaman dokumentasi yang baik berisi: <b>deskripsi</b> singkat, <b>kapan dipakai</b> dan <b>kapan tidak</b>, <b>anatomi</b> (bagian-bagian bernomor), <b>varian dan state</b>, <b>contoh Do dan Don't</b>, <b>panduan konten</b> (panjang label, gaya kalimat), <b>aksesibilitas</b>, dan <b>kode</b>.", "Contoh <b>Do dan Don't</b> adalah bagian yang paling sering dibaca, karena langsung menunjukkan kesalahan umum. Taruh berdampingan: kiri hijau \"Lakukan\", kanan merah \"Jangan\", masing-masing dengan alasan satu kalimat.", "Dokumentasi bisa dibuat di Figma (halaman khusus di library), Zeroheight, Supernova, atau Storybook untuk kode. Yang penting: satu tempat yang diketahui semua orang, dan diperbarui setiap kali komponen berubah, lengkap dengan changelog.", "Halaman dokumentasi tombol di pratinjau baru punya contoh Do."], "html": "<section class=\"dok\">\n  <h2>Tombol primary</h2>\n  <p>Untuk satu aksi utama di setiap layar.</p>\n  <div class=\"contoh\">\n    <figure class=\"do\"><div class=\"demo\"><button class=\"p\">Simpan</button><button class=\"s\">Batal</button></div><figcaption><b>Lakukan:</b> satu primary, aksi lain secondary.</figcaption></figure>\n  </div>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; color: #1F2933; }\n.contoh { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }\nfigure { margin: 0; border-radius: 12px; overflow: hidden; border-top: 4px solid; background: #F5F7FA; }\n.do { border-color: #1E7B45; }\n.dont { border-color: #B42318; }\n.demo { padding: 24px; display: flex; gap: 8px; }\nfigcaption { padding: 12px 16px; font-size: 14px; background: #fff; }\n.p, .s { font: inherit; padding: 8px 16px; border-radius: 8px; border: 1px solid #1D5FA8; }\n.p { background: #1D5FA8; color: #fff; }\n.s { background: #fff; color: #1D5FA8; }", "task": {"q": "Tambahkan contoh <code>&lt;figure class=\"dont\"&gt;</code> di dalam <code>.contoh</code>: dua tombol primary berdampingan, dengan keterangan \"<b>Jangan:</b> dua primary di satu layar.\"", "test": "(f=>!!f&&f.querySelectorAll('.p').length>=2&&f.textContent.includes('Jangan'))(document.querySelector('.contoh .dont'))", "hint": "<figure class=\"dont\"><div class=\"demo\"><button class=\"p\">Simpan</button><button class=\"p\">Kirim</button></div><figcaption><b>Jangan:</b> dua primary di satu layar.</figcaption></figure>"}, "pts": ["Isi dokumentasi: kapan dipakai, anatomi, varian, Do/Don't, konten, aksesibilitas, kode.", "Do dan Don't berdampingan dengan alasan.", "Satu tempat, diperbarui bersama changelog."], "q": [["Bagian dokumentasi yang paling cepat mencegah kesalahan umum?", ["Riwayat versi", "Contoh Do dan Don't", "Daftar kontributor"], 1, "Menunjukkan langsung yang benar dan salah."], ["Storybook paling cocok untuk mendokumentasikan?", ["Komponen kode", "Riset pengguna", "Anggaran proyek"], 0, "Menampilkan komponen kode dengan semua state."]], "so": [{"q": "Tulis kerangka dokumentasi komponen Toast (notifikasi singkat).", "h": "Deskripsi, kapan dipakai, anatomi, varian, Do/Don't, konten, aksesibilitas.", "a": "Toast\nDeskripsi : pesan singkat tentang hasil aksi, hilang sendiri.\nKapan     : konfirmasi ringan (Tersimpan, Disalin).\nJangan    : untuk error penting atau yang butuh keputusan (pakai dialog/banner).\nAnatomi   : 1 ikon, 2 pesan, 3 aksi opsional (Urungkan).\nVarian    : neutral, success, error.\nDo        : maksimal 1 baris, kata kerja lampau (\"Kelas disimpan\").\nDon't     : dua toast bertumpuk.\nAksesibilitas: role=\"status\", tampil minimal 4 detik, bisa ditutup.", "lang": "text"}]}]}, {"t": "Layout responsif dan handoff", "lvl": "Menengah", "d": "Breakpoint fluid dan aturan container, pola navigasi mobile, layout dashboard desktop, redlining dan spesifikasi, serta sesi handoff kolaboratif.", "nodes": ["Breakpoints", "Mobile navigation", "Dashboard layout", "Redlines", "Handoff"], "lessons": [{"k": "w", "t": "Breakpoint fluid dan aturan container", "nodes": [], "b": ["<b>Breakpoint</b> adalah lebar layar tempat tata letak berubah. Titik yang umum: <b>&lt; 600</b> (ponsel), <b>600 sampai 839</b> (tablet tegak dan lipat), <b>840 sampai 1199</b> (tablet mendatar, laptop kecil), <b>≥ 1200</b> (desktop). Material 3 menamainya compact, medium, expanded, large, dan extra-large. Tentukan breakpoint dari <b>konten</b> yang mulai rusak, bukan dari merek perangkat.", "Di antara breakpoint, layout harus <b>fluid</b>: kolom melebar mengikuti layar. Grid web yang umum: 4 kolom di ponsel (margin 16 px), 8 kolom di tablet (margin 24 sampai 32 px), 12 kolom di desktop. <b>Container</b> membatasi lebar maksimum isi (misalnya 1200 px) agar baris teks tidak terlalu panjang di monitor lebar.", "Teknik CSS tanpa media query: <code>grid-template-columns: repeat(auto-fit, minmax(240px, 1fr))</code> membuat kartu otomatis 1, 2, 3, atau 4 kolom sesuai ruang. Container query (<code>@container</code>) membuat komponen menyesuaikan lebar <b>induknya</b>, bukan lebar layar.", "Grid kartu di pratinjau terkunci 3 kolom dan sesak di layar kecil."], "html": "<div class=\"container\">\n  <div class=\"grid\">\n    <div class=\"kartu\">Dart</div><div class=\"kartu\">Flutter</div><div class=\"kartu\">Kotlin</div>\n    <div class=\"kartu\">Compose</div><div class=\"kartu\">KMP</div><div class=\"kartu\">UI Design</div>\n  </div>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; }\n.container { max-width: 1200px; margin: 0 auto; padding: 16px clamp(16px, 4vw, 32px); }\n.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.kartu { padding: 24px 16px; border-radius: 12px; background: #E8F1FB; font-weight: 600; }", "task": {"q": "Ubah <code>.grid</code> menjadi fluid: <code>grid-template-columns: repeat(auto-fit, minmax(160px, 1fr))</code>.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.grid'&&/auto-(fit|fill)/.test(r.style.gridTemplateColumns))", "hint": ".grid { grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)) }"}, "pts": ["Breakpoint dari konten: compact, medium, expanded.", "4, 8, 12 kolom; container membatasi lebar maksimum.", "auto-fit + minmax dan container query."], "q": [["Breakpoint sebaiknya ditentukan berdasarkan?", ["Merek ponsel terlaris", "Titik saat konten mulai rusak", "Selera klien"], 1, "Konten yang menentukan."], ["repeat(auto-fit, minmax(240px, 1fr)) di layar 1000 px menghasilkan berapa kolom (abaikan gap)?", ["2", "4", "6"], 1, "1000 / 240 = 4 kolom muat."]], "so": [{"q": "Buat komponen kartu yang berubah menjadi horizontal saat induknya minimal 480px, memakai container query.", "h": "container-type: inline-size, lalu @container.", "a": ".wadah { container-type: inline-size; }\n.kartu { display: grid; gap: 12px; }\n@container (min-width: 480px) {\n  .kartu { grid-template-columns: 160px 1fr; }\n}", "lang": "css"}]}, {"k": "w", "t": "Pola navigasi mobile", "nodes": [], "b": ["Pola navigasi utama di ponsel: <b>bottom navigation bar</b> (3 sampai 5 tujuan utama, selalu terlihat, mudah dijangkau jempol), <b>tab bar atas</b> (berpindah antar tampilan dalam satu bagian), <b>navigation drawer</b> (menu samping untuk banyak tujuan, tapi tersembunyi sehingga jarang ditemukan), dan <b>top app bar</b> dengan tombol kembali.", "Aturan bottom navigation: setiap item punya <b>ikon dan label</b> (label tidak boleh disembunyikan, ikon saja sering disalahpahami), item aktif ditandai dengan lebih dari warna (indikator pill di Material 3, ikon filled di iOS), dan target sentuh minimal 48 dp tinggi.", "Di kode, tandai item aktif dengan <code>aria-current=\"page\"</code>. Hormati area aman (safe area) di bawah layar iPhone dan Android modern dengan <code>padding-bottom: env(safe-area-inset-bottom)</code>.", "Bottom nav di pratinjau belum menandai halaman aktif dan terlalu pendek."], "html": "<nav class=\"bottom-nav\" aria-label=\"Navigasi utama\">\n  <a href=\"#\" class=\"item\"><span aria-hidden=\"true\">🏠</span>Beranda</a>\n  <a href=\"#\" class=\"item aktif\"><span aria-hidden=\"true\">📚</span>Kelas</a>\n  <a href=\"#\" class=\"item\"><span aria-hidden=\"true\">🏆</span>Peringkat</a>\n  <a href=\"#\" class=\"item\"><span aria-hidden=\"true\">👤</span>Profil</a>\n</nav>", "css": "body { font-family: system-ui, sans-serif; margin: 0; min-height: 100vh; background: #F4F5F7; }\n.bottom-nav { position: fixed; left: 0; right: 0; bottom: 0; display: flex; background: #fff; border-top: 1px solid #E4E7EB; padding-bottom: env(safe-area-inset-bottom); }\n.item { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 4px 0; font-size: 12px; color: #52606D; text-decoration: none; }\n.aktif { color: #0D5DB8; font-weight: 600; }", "task": {"q": "Beri item Kelas <code>aria-current=\"page\"</code>, dan buat setiap <code>.item</code> minimal 56px tingginya (misalnya <code>min-height: 56px</code>).", "test": "!!document.querySelector('.bottom-nav [aria-current=\"page\"]')&&[...document.querySelectorAll('.bottom-nav .item')].every(a=>a.getBoundingClientRect().height>=56)", "hint": "<a ... class=\"item aktif\" aria-current=\"page\"> dan .item { min-height: 56px; justify-content: center }"}, "pts": ["Bottom nav: 3–5 tujuan, ikon + label, mudah dijangkau.", "Item aktif ditandai lebih dari warna, aria-current=\"page\".", "Target 48 dp dan safe area bawah."], "q": [["Aplikasi punya 4 tujuan utama yang sering dipakai. Pola terbaik di ponsel?", ["Navigation drawer", "Bottom navigation", "Footer link"], 1, "Selalu terlihat dan mudah dijangkau jempol."], ["Bolehkah label bottom navigation disembunyikan agar rapi?", ["Boleh", "Tidak, ikon saja sering disalahpahami"], 1, "Label membuat tujuan jelas."]], "so": [{"q": "Aplikasi punya 7 tujuan: Beranda, Kelas, Jadwal, Peringkat, Pesan, Profil, Pengaturan. Rancang navigasi mobile-nya.", "h": "Bottom nav maksimal 5; sisanya ke Profil atau menu lain.", "a": "Bottom nav (4): Beranda, Kelas, Jadwal, Profil\nPesan: ikon di top app bar (dengan badge)\nPeringkat: tab di halaman Kelas\nPengaturan: di dalam halaman Profil", "lang": "text"}]}, {"k": "w", "t": "Layout dashboard desktop", "nodes": [], "b": ["Dashboard desktop biasanya terdiri dari: <b>sidebar</b> navigasi (lebar tetap 240 sampai 280 px, bisa diciutkan menjadi ikon), <b>header</b> (judul halaman, pencarian, profil), dan <b>area utama</b> berisi kartu KPI di atas, grafik di tengah, dan tabel detail di bawah. Urutan ini mengikuti cara orang membaca: ringkasan dulu, detail kemudian.", "Letakkan angka terpenting di <b>kiri atas</b> area utama, karena pembaca bahasa Latin memindai dengan pola F. Kartu KPI berisi: label, angka besar, perubahan (naik 12% dibanding minggu lalu) dengan ikon panah, bukan hanya warna.", "CSS Grid dengan <b>grid-template-areas</b> membuat struktur dashboard terbaca seperti peta. Di layar kecil, ubah area menjadi satu kolom dan sidebar menjadi drawer atau bottom nav.", "Dashboard di pratinjau belum punya struktur. Susun dengan grid-template-areas."], "html": "<div class=\"dash\">\n  <aside class=\"side\">Menu</aside>\n  <header class=\"head\">Ringkasan penjualan</header>\n  <main class=\"main\">\n    <div class=\"kpi\"><small>Pendapatan</small><b>Rp48,2 jt</b><span>▲ 12%</span></div>\n    <div class=\"kpi\"><small>Pesanan</small><b>1.284</b><span>▲ 4%</span></div>\n    <div class=\"kpi\"><small>Retur</small><b>23</b><span>▼ 2%</span></div>\n  </main>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; }\n.dash { display: grid; min-height: 100vh; gap: 0; }\n.side { grid-area: sidebar; background: #0F172A; color: #CBD5E1; padding: 16px; }\n.head { grid-area: header; padding: 16px 24px; border-bottom: 1px solid #E4E7EB; font-weight: 700; }\n.main { grid-area: main; padding: 24px; display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 16px; align-content: start; }\n.kpi { display: grid; gap: 4px; padding: 16px; border-radius: 12px; background: #F5F7FA; }\n.kpi b { font-size: 24px; }", "task": {"q": "Beri <code>.dash</code> struktur: <code>grid-template-columns: 200px 1fr</code> dan <code>grid-template-areas: \"sidebar header\" \"sidebar main\"</code>.", "test": "(s=>s.gridTemplateAreas.includes('sidebar')&&s.gridTemplateAreas.includes('main'))(getComputedStyle(document.querySelector('.dash')))", "hint": ".dash { grid-template-columns: 200px 1fr; grid-template-rows: auto 1fr; grid-template-areas: \"sidebar header\" \"sidebar main\" }"}, "pts": ["Sidebar, header, area utama: KPI, grafik, tabel.", "Angka terpenting di kiri atas (pola F).", "grid-template-areas sebagai peta layout."], "q": [["Di mana angka terpenting dashboard diletakkan?", ["Kanan bawah", "Kiri atas", "Di dalam sidebar"], 1, "Mata memindai dengan pola F."], ["Kartu KPI menampilkan perubahan turun hanya dengan warna merah. Perbaikannya?", ["Tambahkan ikon panah dan teks persentase", "Pakai merah lebih gelap", "Hilangkan"], 0, "Jangan mengandalkan warna saja."]], "so": [{"q": "Ubah dashboard menjadi satu kolom di bawah 840px: sidebar disembunyikan, header di atas main.", "h": "Media query yang mengubah grid-template-areas.", "a": "@media (max-width: 839px) {\n  .dash { grid-template-columns: 1fr; grid-template-areas: \"header\" \"main\"; }\n  .side { display: none; }\n}", "lang": "css"}]}, {"k": "w", "t": "Redlining dan spesifikasi", "nodes": [], "b": ["<b>Redlining</b> adalah memberi anotasi ukuran pada desain: jarak, padding, ukuran huruf, radius, warna, dan perilaku. Dulu digambar manual dengan garis merah; sekarang Figma <b>Dev Mode</b> menampilkannya otomatis saat developer mengklik elemen, lengkap dengan nilai token.", "Yang tetap harus ditulis desainer, karena tidak terlihat di gambar statis: <b>perilaku responsif</b> (apa yang melar, apa yang tetap), <b>semua state</b> (hover, focus, disabled, loading, error, empty), <b>teks terpanjang</b> (nama 40 huruf, harga Rp1.250.000.000), <b>animasi</b> (durasi, easing), dan <b>logika</b> (kapan tombol aktif, validasi apa).", "Spesifikasi yang baik memakai <b>nama token</b>, bukan angka mentah: tulis \"padding space-2 / space-3, radius-md, color-action-primary\", bukan \"16px, 24px, 10px, #1D5FA8\". Developer tinggal mencocokkan token yang sama di kode.", "Tombol di pratinjau belum sesuai spesifikasi: padding 16px atas-bawah dan 24px kiri-kanan, radius 12px."], "html": "<div class=\"spes\">\n  <button class=\"tombol\">Konfirmasi pesanan</button>\n  <ul>\n    <li>Padding: space-2 (16px) atas-bawah, space-3 (24px) kiri-kanan</li>\n    <li>Radius: radius-lg (12px)</li>\n    <li>Tinggi minimum: 48px</li>\n  </ul>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }\n.spes ul { font-size: 14px; color: #52606D; padding-left: 20px; }\n.tombol { font: inherit; font-weight: 600; background: #1D5FA8; color: #fff; border: 0; padding: 10px 14px; border-radius: 4px; }", "task": {"q": "Sesuaikan <code>.tombol</code> dengan spesifikasi: padding 16px 24px, border-radius 12px, min-height 48px.", "test": "(s=>parseFloat(s.paddingTop)===16&&parseFloat(s.paddingLeft)===24&&parseFloat(s.borderTopLeftRadius)===12&&parseFloat(s.minHeight)>=48)(getComputedStyle(document.querySelector('.tombol')))", "hint": ".tombol { padding: 16px 24px; border-radius: 12px; min-height: 48px }"}, "pts": ["Dev Mode menampilkan ukuran otomatis.", "Tulis yang tak terlihat: responsif, state, teks terpanjang, animasi, logika.", "Spesifikasi memakai nama token."], "q": [["Informasi apa yang TIDAK muncul otomatis di Dev Mode dari satu frame statis?", ["Ukuran huruf", "Perilaku saat teks sangat panjang", "Warna latar"], 1, "Perilaku harus ditulis desainer."], ["Spesifikasi yang baik menulis warna sebagai?", ["#1D5FA8", "color-action-primary", "biru"], 1, "Nama token yang sama dipakai di kode."]], "so": [{"q": "Tulis spesifikasi lengkap untuk komponen input pencarian (bukan hanya ukuran).", "h": "Ukuran, token, state, perilaku, teks panjang, aksesibilitas.", "a": "Tinggi 48, padding space-2, radius-full, ikon 20 kiri\nToken: color-bg-surface, color-border-input, color-text-muted (placeholder)\nState: default, focus (border 2px color-border-focus), filled (tampil tombol hapus), disabled\nPerilaku: cari setelah berhenti mengetik 300 ms; Enter langsung cari; Esc mengosongkan\nTeks panjang: terpotong dengan elipsis, tidak melebarkan input\nAksesibilitas: role=\"search\", label tersembunyi \"Cari kelas\", tombol hapus aria-label=\"Hapus pencarian\"", "lang": "text"}]}, {"k": "c", "t": "Sesi handoff kolaboratif", "nodes": [], "b": ["<b>Handoff</b> bukan melempar file Figma lalu pergi. Handoff yang baik adalah <b>percakapan</b> yang dimulai sejak awal: developer ikut melihat wireframe untuk memberi tahu batasan teknis, dan desainer tetap terlibat sampai fitur dirilis.", "Format sesi handoff (30 sampai 60 menit): (1) desainer menjelaskan <b>masalah pengguna</b> dan tujuan fitur, bukan hanya gambarnya; (2) <b>walkthrough alur</b> dari awal sampai akhir, termasuk jalur error dan empty state; (3) membahas <b>komponen</b>: mana yang sudah ada di design system, mana yang baru; (4) membahas <b>kasus tepi</b> dan perilaku responsif; (5) menyepakati <b>acceptance criteria</b> yang bisa diuji.", "Siapkan file Figma yang rapi sebelum sesi: halaman terpisah untuk \"Siap dikembangkan\" (Ready for dev), nama frame jelas, komponen dari library, anotasi untuk perilaku, dan prototype untuk alur. Tandai frame dengan status <b>Ready for dev</b> di Dev Mode agar developer tahu mana yang final.", "Setelah dibangun, lakukan <b>design QA</b>: desainer membandingkan hasil build di perangkat nyata dengan desain, mencatat selisih sebagai tiket dengan tangkapan layar, lalu memprioritaskannya bersama tim. Selisih 1 px tidak sama pentingnya dengan state error yang hilang."], "tb": [{"c": "Daftar periksa handoff", "h": ["Bagian", "Yang disiapkan"], "r": [["Konteks", "Masalah pengguna, tujuan, metrik keberhasilan"], ["Alur", "Prototype dari awal sampai akhir, termasuk error dan batal"], ["Layar", "Semua state: default, loading, empty, error, sukses, data panjang"], ["Responsif", "Ponsel, tablet, desktop, atau aturan melar"], ["Komponen", "Dari library; komponen baru ditandai dan didokumentasikan"], ["Token", "Warna, tipografi, spacing memakai nama token"], ["Konten", "Teks final, pesan error, teks terpanjang"], ["Aset", "Ikon SVG, gambar @1x @2x @3x, nama file konsisten"], ["Aksesibilitas", "Urutan fokus, label pembaca layar, kontras"], ["Acceptance criteria", "Kondisi yang bisa diuji untuk setiap perilaku"]]}, {"c": "Contoh acceptance criteria", "h": ["Kondisi", "Hasil yang diharapkan"], "r": [["Email kosong lalu tekan Daftar", "Pesan \"Email wajib diisi\" di bawah field, fokus pindah ke field email"], ["Email tanpa @", "Pesan \"Format email belum benar, contoh: nama@contoh.com\""], ["Tombol Daftar ditekan", "Tombol menampilkan loading dan tidak bisa ditekan dua kali"], ["Server gagal", "Banner error dengan tombol Coba lagi, isian tidak hilang"]]}], "pts": ["Handoff adalah percakapan sejak awal, bukan melempar file.", "Sesi: konteks, alur, komponen, kasus tepi, acceptance criteria.", "Design QA di perangkat nyata setelah dibangun."], "q": [["Kapan developer sebaiknya mulai dilibatkan?", ["Setelah desain final", "Sejak wireframe", "Setelah rilis"], 1, "Batasan teknis diketahui lebih awal."], ["Apa itu design QA?", ["Menguji kode dengan unit test", "Membandingkan hasil build dengan desain di perangkat nyata", "Membuat ulang desain"], 1, "Selisih dicatat dan diprioritaskan."], ["Acceptance criteria yang baik bersifat?", ["Bisa diuji", "Umum seperti \"harus bagus\"", "Hanya untuk desainer"], 0, "Setiap kondisi punya hasil yang jelas."]], "so": [{"q": "Tulis 4 acceptance criteria untuk fitur \"Lupa kata sandi\".", "h": "Format: kondisi → hasil yang diharapkan, termasuk jalur gagal.", "a": "1. Email terdaftar dikirim → muncul pesan \"Cek email untuk tautan reset\" dan tombol kirim ulang aktif setelah 60 detik.\n2. Email tidak terdaftar → pesan yang sama (tidak membocorkan apakah email terdaftar).\n3. Format email salah → pesan di bawah field, fokus kembali ke field.\n4. Tautan reset kedaluwarsa (lebih dari 30 menit) → halaman \"Tautan kedaluwarsa\" dengan tombol minta tautan baru.", "lang": "text"}]}]}];
const SLW_MODULES=[{"t": "Persiapan slicing", "lvl": "Pemula", "d": "Apa itu slicing, membaca desain di Figma Dev Mode, memindahkan token desain ke CSS variables, dan menyusun HTML semantik dari desain.", "nodes": ["Slicing", "Figma Dev Mode", "Design tokens", "Semantic HTML"], "lessons": [{"k": "c", "t": "Apa itu slicing dan alurnya", "nodes": [], "b": ["<b>Slicing</b> adalah mengubah desain statis (Figma, Adobe XD, Penpot) menjadi halaman web atau aplikasi yang benar-benar berjalan. Istilah ini berasal dari zaman dulu, saat desain Photoshop \"diiris\" menjadi potongan gambar. Sekarang yang diiris adalah <b>struktur</b>: section, komponen, dan token.", "Alur kerja slicer profesional: (1) <b>pelajari desain</b> secara utuh, termasuk versi mobile dan desktop; (2) <b>pecah halaman</b> menjadi section (navbar, hero, fitur, testimoni, harga, footer); (3) temukan <b>komponen berulang</b> (tombol, kartu, input); (4) catat <b>token</b> (warna, font, spacing, radius); (5) siapkan <b>aset</b> (ikon SVG, gambar WebP); (6) tulis <b>HTML semantik</b> dulu; (7) tulis CSS <b>mobile-first</b>; (8) bandingkan dengan desain (<b>pixel-perfect</b>); (9) uji di perangkat nyata.", "Kesalahan pemula: langsung menulis CSS dari section paling atas sampai bawah tanpa melihat pola. Hasilnya tombol yang sama ditulis lima kali dengan ukuran sedikit berbeda. Luangkan 15 menit di awal untuk mencatat komponen dan token, dan kamu akan menghemat berjam-jam."], "tb": [{"c": "Pembagian halaman landing page", "h": ["Section", "Elemen HTML", "Komponen di dalamnya"], "r": [["Navbar", "header > nav", "Logo, link, tombol masuk, tombol menu (mobile)"], ["Hero", "section", "Judul, deskripsi, 2 tombol, gambar"], ["Fitur", "section", "Kartu fitur × 3 sampai 6 (ikon, judul, teks)"], ["Testimoni", "section", "Kartu kutipan, foto, nama"], ["Harga", "section", "Kartu paket × 3, lencana \"Paling populer\""], ["Footer", "footer", "Link, form newsletter, hak cipta"]]}], "pts": ["Slicing = desain statis menjadi kode yang berjalan.", "Pecah section, temukan komponen dan token dulu.", "HTML semantik dulu, lalu CSS mobile-first."], "q": [["Langkah yang sebaiknya dilakukan sebelum menulis CSS?", ["Mencatat komponen berulang dan token", "Mengekspor semua frame jadi PNG", "Menulis JavaScript"], 0, "Pola dulu, kode kemudian."], ["Kenapa slicing dimulai dari mobile?", ["Layar kecil lebih mudah diperluas daripada sebaliknya", "Desainer selalu mulai dari mobile", "Aturan Figma"], 0, "Mobile-first: tambahkan aturan saat layar melebar."]], "so": [{"q": "Ambil satu landing page yang kamu suka. Pecah menjadi section, lalu daftar komponen berulang dan token warna yang kamu temukan.", "h": "Tulis section dari atas ke bawah, lalu cari elemen yang sama bentuknya.", "a": "Contoh:\nSection : navbar, hero, logo klien, fitur (6 kartu), testimoni, harga (3 paket), FAQ, footer\nKomponen: tombol (primary, secondary), kartu fitur, kartu harga, item FAQ\nToken   : brand #4F46E5, teks #111827, abu #6B7280, latar #F9FAFB, radius 12, spacing 8/16/24/48", "lang": "text"}]}, {"k": "c", "t": "Membaca desain di Figma Dev Mode", "nodes": [], "b": ["<b>Dev Mode</b> (ikon &lt;/&gt; atau Shift + D di Figma) adalah tampilan khusus developer. Klik elemen untuk melihat <b>ukuran</b>, <b>jarak</b> ke elemen lain (tahan Alt atau Option sambil mengarahkan kursor), <b>warna</b> dan nama variabelnya, <b>tipografi</b>, serta potongan kode CSS. Developer tidak bisa mengubah desain secara tidak sengaja di mode ini.", "Cara membaca auto layout: frame dengan auto layout ditampilkan sebagai <code>display: flex</code>, lengkap dengan <code>gap</code>, <code>padding</code>, dan arah. Hug contents berarti lebar mengikuti isi, Fill container berarti <code>flex: 1</code> atau <code>width: 100%</code>. Jangan menyalin <code>position: absolute</code> dan <code>width</code> piksel tetap dari panel kode mentah-mentah; itu hanya cocok untuk ukuran frame itu saja.", "Kebiasaan baik: periksa nama <b>variabel</b> (misalnya <code>color/brand/600</code>) dan pakai nama itu di CSS, bukan kode hex. Periksa juga apakah frame ditandai <b>Ready for dev</b>; frame lain mungkin masih eksplorasi. Jika tidak punya akses Dev Mode (berbayar), mode Inspect di akun gratis tetap menampilkan ukuran dan warna."], "tb": [{"c": "Figma ke CSS", "h": ["Di Figma", "Di CSS"], "r": [["Auto layout horizontal, gap 16", "display: flex; gap: 16px"], ["Auto layout vertical", "display: flex; flex-direction: column"], ["Padding 24 / 16", "padding: 24px 16px"], ["Hug contents", "width: auto (atau fit-content)"], ["Fill container", "flex: 1 atau width: 100%"], ["Corner radius 12", "border-radius: 12px"], ["Drop shadow 0 4 12 #0000001F", "box-shadow: 0 4px 12px rgb(0 0 0 / .12)"], ["Text Inter 16/24 Medium", "font: 500 16px/24px Inter"], ["Constraints Left & Right", "lebar melar mengikuti induk"], ["Layer opacity 60%", "opacity: .6"]]}], "pts": ["Dev Mode: ukuran, jarak, variabel, kode.", "Auto layout = flexbox; jangan salin posisi absolut mentah.", "Pakai nama variabel, cek status Ready for dev."], "q": [["Cara melihat jarak antara dua elemen di Figma?", ["Pilih satu elemen, tahan Alt/Option, arahkan ke elemen lain", "Klik kanan lalu Measure", "Tidak bisa"], 0, "Figma menampilkan jarak merah."], ["Panel kode Figma menulis position: absolute; left: 132px. Sebaiknya?", ["Salin persis", "Terjemahkan ke flex atau grid sesuai auto layout", "Abaikan elemennya"], 1, "Posisi absolut hanya pas di satu ukuran frame."]], "so": [{"q": "Dev Mode menampilkan: auto layout vertical, gap 12, padding 20/24, fill #F8FAFC, radius 16, stroke 1 #E2E8F0, shadow 0 2 8 #0F172A14. Tulis CSS-nya.", "h": "Terjemahkan satu per satu, warna alpha 14 hex ≈ 8%.", "a": ".kartu {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  padding: 20px 24px;\n  background: #F8FAFC;\n  border: 1px solid #E2E8F0;\n  border-radius: 16px;\n  box-shadow: 0 2px 8px rgb(15 23 42 / .08);\n}", "lang": "css"}]}, {"k": "w", "t": "Token desain ke CSS variables", "nodes": [], "b": ["Langkah pertama menulis CSS dari desain: pindahkan <b>token</b> ke <code>:root</code>. Buka panel Variables di Figma (atau Local styles untuk file lama) dan salin warna, font, spacing, radius, dan bayangan menjadi CSS variables.", "Setelah token ada, <b>semua</b> aturan CSS memakai <code>var(--...)</code>. Jika desainer mengubah warna merek minggu depan, kamu cukup mengubah satu baris. Jika desain punya mode gelap, tambahkan blok token kedua.", "Beri nama variabel sama seperti di Figma agar mudah dicocokkan: <code>color/brand/600</code> menjadi <code>--color-brand-600</code>, <code>spacing/4</code> menjadi <code>--spacing-4</code>.", "Desain di pratinjau memakai warna merek #0F766E dan radius 12. Pindahkan ke token."], "html": "<section class=\"promo\">\n  <h2>Kelas baru: Slicing Website</h2>\n  <p>Ubah desain Figma menjadi halaman nyata.</p>\n  <a class=\"tombol\" href=\"#\">Daftar</a>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n:root {\n  /* token dari Figma: tulis di sini */\n}\n.promo { margin: 16px; padding: 24px; border-radius: 12px; background: #CCFBF1; }\n.promo h2 { margin: 0 0 8px; color: #134E4A; }\n.tombol { display: inline-block; margin-top: 8px; padding: 12px 24px; border-radius: 12px; background: #0F766E; color: #fff; text-decoration: none; font-weight: 600; }", "task": {"q": "Buat token <code>--color-brand-600: #0F766E</code> dan <code>--radius-md: 12px</code> di <code>:root</code>, lalu pakai keduanya di <code>.tombol</code>.", "test": "getComputedStyle(document.documentElement).getPropertyValue('--color-brand-600').trim().toLowerCase()==='#0f766e'&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.tombol'&&/var\\(--color-brand-600\\)/.test(r.style.cssText)&&/var\\(--radius-md\\)/.test(r.style.cssText))", "hint": ":root { --color-brand-600: #0F766E; --radius-md: 12px } lalu .tombol { background: var(--color-brand-600); border-radius: var(--radius-md) }"}, "pts": ["Token dari Figma Variables ke :root.", "Semua aturan memakai var().", "Nama variabel sama dengan nama di Figma."], "q": [["Nama CSS yang cocok untuk variabel Figma spacing/4?", ["--spacing-4", "--s4px", "--jarak"], 0, "Sama dengan nama di Figma."]], "so": [{"q": "Ubah daftar variabel Figma berikut menjadi CSS: color/brand/500 #6366F1, color/text/primary #111827, spacing/2 8, spacing/4 16, radius/lg 16, font/body Inter.", "h": "Garis miring menjadi tanda hubung, angka spacing diberi px.", "a": ":root {\n  --color-brand-500: #6366F1;\n  --color-text-primary: #111827;\n  --spacing-2: 8px;\n  --spacing-4: 16px;\n  --radius-lg: 16px;\n  --font-body: \"Inter\", system-ui, sans-serif;\n}", "lang": "css"}]}, {"k": "w", "t": "HTML semantik dari desain", "nodes": [], "b": ["Desain hanya menunjukkan <b>rupa</b>; slicer yang menentukan <b>makna</b>. Navbar adalah <code>&lt;header&gt;</code> berisi <code>&lt;nav&gt;</code>, isi utama adalah <code>&lt;main&gt;</code>, setiap bagian adalah <code>&lt;section&gt;</code> dengan judul, kartu artikel adalah <code>&lt;article&gt;</code>, dan bagian bawah adalah <code>&lt;footer&gt;</code>.", "Judul harus berurutan: satu <code>&lt;h1&gt;</code> per halaman (biasanya judul hero), lalu <code>&lt;h2&gt;</code> untuk judul section, <code>&lt;h3&gt;</code> untuk judul kartu. Pilih tag berdasarkan <b>tingkat</b>, bukan ukuran huruf di desain; ukuran diatur oleh CSS.", "Yang terlihat seperti tombol tetapi pindah halaman adalah <code>&lt;a&gt;</code>; yang menjalankan aksi di halaman yang sama adalah <code>&lt;button&gt;</code>. HTML semantik membuat halaman terbaca pembaca layar, mudah ditemukan Google, dan lebih mudah di-styling.", "Kerangka di pratinjau hanya berisi div. Ganti dengan landmark yang tepat."], "html": "<div class=\"atas\"><div class=\"logo\">RuangKode</div><div class=\"menu\"><a href=\"#\">Kelas</a><a href=\"#\">Harga</a></div></div>\n<div class=\"isi\">\n  <div class=\"judul-besar\">Belajar slicing dari desain nyata</div>\n  <p>Latihan dengan file Figma sungguhan.</p>\n</div>\n<div class=\"bawah\">© 2026 RuangKode</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.atas, header { display: flex; justify-content: space-between; align-items: center; padding: 16px; border-bottom: 1px solid #E4E7EB; }\n.menu, nav { display: flex; gap: 16px; }\n.isi, main { padding: 24px 16px; }\n.judul-besar, h1 { font-size: 28px; font-weight: 700; margin: 0 0 8px; }\n.bawah, footer { padding: 16px; color: #52606D; font-size: 14px; }", "task": {"q": "Ganti kerangkanya: <code>header</code> berisi <code>nav</code>, <code>main</code> berisi <code>h1</code>, dan <code>footer</code>.", "test": "!!document.querySelector('header nav')&&!!document.querySelector('main h1')&&!!document.querySelector('footer')", "hint": "<header><div class=\"logo\">RuangKode</div><nav>...</nav></header><main><h1>...</h1><p>...</p></main><footer>...</footer>"}, "pts": ["header, nav, main, section, article, footer.", "Satu h1, judul berurutan.", "Pindah halaman: a. Aksi di halaman: button."], "q": [["Tombol \"Lihat kelas\" yang membuka halaman lain sebaiknya memakai?", ["button", "a", "div"], 1, "Navigasi memakai tautan."], ["Berapa h1 dalam satu halaman?", ["Satu", "Satu per section", "Bebas"], 0, "h1 adalah judul halaman."]], "so": [{"q": "Tulis kerangka HTML semantik untuk halaman blog: navbar, judul artikel, info penulis, isi, artikel terkait (3 kartu), footer.", "h": "header/nav, main/article, aside atau section, footer.", "a": "<header><nav>...</nav></header>\n<main>\n  <article>\n    <h1>Judul artikel</h1>\n    <p class=\"meta\">Oleh Rina · 5 menit baca</p>\n    <p>Isi...</p>\n  </article>\n  <section aria-labelledby=\"terkait\">\n    <h2 id=\"terkait\">Artikel terkait</h2>\n    <article><h3>...</h3></article>\n    <article><h3>...</h3></article>\n    <article><h3>...</h3></article>\n  </section>\n</main>\n<footer>...</footer>", "lang": "html"}]}]}, {"t": "Slicing komponen", "lvl": "Pemula", "d": "Navbar responsif, hero section, tombol dan kartu dari komponen Figma, serta ikon dan gambar yang dioptimalkan.", "nodes": ["Navbar", "Hero", "Components", "Images"], "lessons": [{"k": "w", "t": "Navbar responsif", "nodes": [], "b": ["Navbar di desain biasanya: logo di kiri, link di tengah atau kanan, tombol aksi di kanan. Di CSS cukup flexbox: <code>display: flex; justify-content: space-between; align-items: center</code>.", "Di mobile, link biasanya disembunyikan di balik tombol menu (hamburger). Cara tanpa JavaScript: <code>&lt;details&gt;</code> dan <code>&lt;summary&gt;</code>. Cara umum: tombol dengan <code>aria-expanded</code> yang mengubah kelas menu lewat JavaScript. Ukur tinggi navbar dari desain (biasanya 56 sampai 72 px) dan pastikan setiap link punya area klik yang cukup.", "Untuk navbar yang tetap terlihat saat menggulir, pakai <code>position: sticky; top: 0</code> dan beri latar serta <code>z-index</code> agar konten tidak tembus.", "Navbar di pratinjau masih menumpuk. Susun dengan flexbox."], "html": "<header class=\"nav\">\n  <a class=\"logo\" href=\"#\">Kopi<b>Nusa</b></a>\n  <nav class=\"link\"><a href=\"#\">Menu</a><a href=\"#\">Lokasi</a><a href=\"#\">Tentang</a></nav>\n  <a class=\"cta\" href=\"#\">Pesan</a>\n</header>\n<main style=\"padding:16px\">Konten halaman...</main>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.nav { padding: 12px 16px; border-bottom: 1px solid #E7E0D8; background: #FFFBF5; }\n.logo { font-size: 20px; color: #3E2723; text-decoration: none; }\n.link { display: flex; gap: 16px; }\n.link a { color: #5D4037; text-decoration: none; padding: 8px 0; }\n.cta { background: #6D4C41; color: #fff; padding: 8px 16px; border-radius: 999px; text-decoration: none; }", "task": {"q": "Jadikan <code>.nav</code> flex: <code>display: flex; justify-content: space-between; align-items: center</code>, dan buat navbar menempel saat menggulir (<code>position: sticky; top: 0</code>).", "test": "(s=>s.display==='flex'&&s.justifyContent==='space-between'&&s.position==='sticky')(getComputedStyle(document.querySelector('.nav')))", "hint": ".nav { display: flex; justify-content: space-between; align-items: center; gap: 16px; position: sticky; top: 0 }"}, "pts": ["Navbar: flex + space-between + align-items center.", "Mobile: menu tersembunyi dengan aria-expanded.", "Sticky: position sticky, top 0, latar, z-index."], "q": [["Properti yang mendorong logo ke kiri dan tombol ke kanan?", ["justify-content: space-between", "text-align: justify", "float: right"], 0, "Ruang dibagi di antara item."]], "so": [{"q": "Buat navbar dengan tombol menu mobile tanpa JavaScript memakai details dan summary.", "h": "summary menjadi tombol, isi details adalah daftar link.", "a": "<header class=\"nav\">\n  <a class=\"logo\" href=\"/\">KopiNusa</a>\n  <details class=\"menu-m\">\n    <summary aria-label=\"Buka menu\">☰</summary>\n    <nav><a href=\"#menu\">Menu</a><a href=\"#lokasi\">Lokasi</a><a href=\"#tentang\">Tentang</a></nav>\n  </details>\n</header>", "lang": "html"}]}, {"k": "w", "t": "Hero section", "nodes": [], "b": ["<b>Hero</b> adalah section pertama yang dilihat pengunjung: judul (h1), satu sampai dua kalimat penjelas, satu sampai dua tombol, dan gambar. Di desktop biasanya dua kolom (teks kiri, gambar kanan); di mobile menjadi satu kolom dengan gambar di bawah atau di atas teks.", "Ukur dari desain: lebar maksimum teks, jarak judul ke deskripsi, jarak ke tombol. Judul hero memakai ukuran fluid (<code>clamp()</code>) agar tidak terlalu besar di ponsel.", "Dua tombol berdampingan bisa terlalu lebar di ponsel kecil. Pakai <code>display: flex; flex-wrap: wrap; gap: 12px</code> agar tombol kedua turun ke baris baru jika tidak muat, bukan memaksa halaman melebar.", "Grup tombol di pratinjau belum bisa turun baris."], "html": "<section class=\"hero\">\n  <div class=\"teks\">\n    <h1>Kopi lokal, diseduh hari ini</h1>\n    <p>Biji kopi dari Gayo, Toraja, dan Kintamani. Diantar hangat dalam 30 menit.</p>\n    <div class=\"aksi\"><a class=\"btn utama\" href=\"#\">Pesan sekarang</a><a class=\"btn kedua\" href=\"#\">Lihat menu lengkap</a></div>\n  </div>\n  <div class=\"gambar\" role=\"img\" aria-label=\"Secangkir kopi\"></div>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.hero { display: grid; gap: 24px; padding: 32px 16px; background: #FFF8EE; }\n@media (min-width: 768px) { .hero { grid-template-columns: 1fr 1fr; align-items: center; padding: 64px 48px; } }\nh1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); line-height: 1.15; margin: 0 0 12px; color: #3E2723; }\n.teks p { margin: 0 0 24px; color: #5D4037; max-width: 45ch; }\n.aksi { display: flex; gap: 12px; }\n.btn { padding: 12px 20px; border-radius: 12px; text-decoration: none; font-weight: 600; white-space: nowrap; }\n.utama { background: #6D4C41; color: #fff; }\n.kedua { border: 1px solid #6D4C41; color: #6D4C41; }\n.gambar { aspect-ratio: 4 / 3; border-radius: 24px; background: radial-gradient(circle at 40% 40%, #D7B899, #6D4C41); }", "task": {"q": "Beri <code>.aksi</code> <code>flex-wrap: wrap</code> agar tombol turun baris di layar sempit.", "test": "getComputedStyle(document.querySelector('.aksi')).flexWrap==='wrap'", "hint": ".aksi { flex-wrap: wrap }"}, "pts": ["Hero: h1, penjelas singkat, 1–2 tombol, gambar.", "Dua kolom di desktop, satu kolom di mobile.", "flex-wrap agar tombol tidak memaksa halaman melebar."], "q": [["Kenapa grup tombol hero diberi flex-wrap?", ["Agar tombol turun baris di layar sempit", "Agar tombol berwarna", "Agar animasi jalan"], 0, "Tidak ada scroll horizontal."]], "so": [{"q": "Tulis CSS hero dua kolom mulai 900px, dengan gambar di atas teks pada mobile.", "h": "Mobile: order gambar -1. Desktop: grid 2 kolom dan order normal.", "a": ".hero { display: grid; gap: 24px; }\n.hero .gambar { order: -1; }\n@media (min-width: 900px) {\n  .hero { grid-template-columns: 1.1fr 1fr; align-items: center; }\n  .hero .gambar { order: 0; }\n}", "lang": "css"}]}, {"k": "w", "t": "Tombol dan kartu dari komponen Figma", "nodes": [], "b": ["Komponen di Figma (tombol, kartu, badge) ditulis <b>sekali</b> sebagai kelas CSS, lalu dipakai ulang. Ambil semua <b>variant</b>-nya dari component set: ukuran, warna, state. Jangan lupa state yang tidak terlihat di frame utama: <b>hover</b>, <b>focus-visible</b>, <b>active</b>, <b>disabled</b>.", "Efek hover kartu di desain sering berupa bayangan yang lebih tebal dan kartu sedikit naik. Tulis dengan <code>transition</code> agar halus (150 sampai 250 ms), dan hormati pengguna yang mematikan animasi dengan <code>@media (prefers-reduced-motion: reduce)</code>.", "Nilai bayangan Figma <code>X 0, Y 8, Blur 24, Spread 0, #000 12%</code> menjadi <code>box-shadow: 0 8px 24px rgb(0 0 0 / .12)</code>.", "Kartu menu di pratinjau belum punya efek hover."], "html": "<div class=\"grid\">\n  <article class=\"kartu\"><div class=\"foto\"></div><h3>Kopi Susu Aren</h3><p>Rp22.000</p></article>\n  <article class=\"kartu\"><div class=\"foto\"></div><h3>Americano</h3><p>Rp18.000</p></article>\n</div>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; padding: 16px; }\n.kartu { background: #fff; border-radius: 16px; padding: 12px; box-shadow: 0 1px 3px rgb(0 0 0 / .12); transition: box-shadow .2s, transform .2s; }\n.kartu h3 { margin: 12px 0 4px; font-size: 16px; }\n.kartu p { margin: 0; color: #6D4C41; font-weight: 600; }\n.foto { aspect-ratio: 1; border-radius: 12px; background: #D7B899; }\n@media (prefers-reduced-motion: reduce) { .kartu { transition: none; } }", "task": {"q": "Tambahkan aturan <code>.kartu:hover</code> dengan <code>box-shadow: 0 8px 24px rgb(0 0 0 / .12)</code> dan <code>transform: translateY(-2px)</code>.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText&&r.selectorText.includes('.kartu:hover')&&r.style.boxShadow&&r.style.transform.includes('translateY'))", "hint": ".kartu:hover { box-shadow: 0 8px 24px rgb(0 0 0 / .12); transform: translateY(-2px) }"}, "pts": ["Satu komponen Figma = satu kelas CSS dengan semua variant dan state.", "Transisi 150–250 ms dan prefers-reduced-motion.", "Bayangan Figma X Y Blur Spread → box-shadow."], "q": [["Drop shadow Figma Y 4, Blur 12, hitam 10% menjadi?", ["box-shadow: 0 4px 12px rgb(0 0 0 / .1)", "shadow: 4 12", "text-shadow: 4px"], 0, "Urutan: x y blur warna."]], "so": [{"q": "Tulis tombol primary dengan state hover, focus-visible, active, dan disabled.", "h": "Lima aturan untuk satu komponen.", "a": ".btn-primary { background: #4F46E5; color: #fff; padding: 12px 20px; border: 0; border-radius: 12px; font-weight: 600; transition: background .15s; }\n.btn-primary:hover { background: #4338CA; }\n.btn-primary:focus-visible { outline: 3px solid #A5B4FC; outline-offset: 2px; }\n.btn-primary:active { transform: translateY(1px); }\n.btn-primary:disabled { background: #C7D2FE; cursor: not-allowed; }", "lang": "css"}]}, {"k": "w", "t": "Ikon dan gambar yang dioptimalkan", "nodes": [], "b": ["Ekspor dari Figma: <b>ikon</b> sebagai SVG (pilih ikon, Export, SVG), lalu sisipkan inline atau sebagai <code>&lt;img&gt;</code>. <b>Foto</b> sebagai WebP atau AVIF, dengan lebar 1× dan 2× ukuran tampilannya. Foto 4000 px untuk kartu 300 px membuat halaman lambat terutama di koneksi seluler.", "Setiap <code>&lt;img&gt;</code> wajib: <code>alt</code> (deskripsi singkat, atau <code>alt=\"\"</code> jika dekoratif), <code>width</code> dan <code>height</code> (agar browser menyiapkan ruang dan halaman tidak \"melompat\" saat gambar dimuat, yang diukur sebagai CLS), serta <code>loading=\"lazy\"</code> untuk gambar di bawah layar pertama.", "Gambar hero di layar pertama justru <b>jangan</b> diberi lazy; beri <code>fetchpriority=\"high\"</code> agar dimuat paling awal.", "Gambar di pratinjau belum punya atribut penting."], "html": "<section class=\"galeri\">\n  <img src=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 4 3'%3E%3Crect width='4' height='3' fill='%23D7B899'/%3E%3C/svg%3E\">\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.galeri { padding: 16px; }\n.galeri img { max-width: 100%; height: auto; border-radius: 12px; display: block; }", "task": {"q": "Beri gambar <code>alt=\"Biji kopi Gayo\"</code>, <code>width=\"400\"</code>, <code>height=\"300\"</code>, dan <code>loading=\"lazy\"</code>.", "test": "(i=>i.alt.length>0&&i.getAttribute('width')&&i.getAttribute('height')&&i.loading==='lazy')(document.querySelector('.galeri img'))", "hint": "<img src=\"...\" alt=\"Biji kopi Gayo\" width=\"400\" height=\"300\" loading=\"lazy\">"}, "pts": ["Ikon SVG, foto WebP/AVIF 1× dan 2×.", "alt, width, height, loading=\"lazy\".", "Gambar hero: tanpa lazy, fetchpriority=\"high\"."], "q": [["Kenapa img diberi width dan height?", ["Agar halaman tidak melompat saat gambar dimuat", "Agar gambar lebih tajam", "Wajib untuk SEO"], 0, "Browser menyiapkan ruang lebih dulu (mengurangi CLS)."], ["Gambar hero di bagian paling atas sebaiknya?", ["loading=\"lazy\"", "Tanpa lazy, fetchpriority=\"high\""], 1, "Harus dimuat paling awal."]], "so": [{"q": "Tulis tag gambar hero yang dimuat paling awal, dan gambar galeri yang dimuat lambat.", "h": "Hero: fetchpriority high tanpa lazy. Galeri: loading lazy.", "a": "<img src=\"hero.webp\" alt=\"Barista menuang susu\" width=\"1200\" height=\"800\" fetchpriority=\"high\">\n<img src=\"galeri-1.webp\" alt=\"Interior kedai\" width=\"600\" height=\"400\" loading=\"lazy\">", "lang": "html"}]}]}, {"t": "Slicing section halaman", "lvl": "Menengah", "d": "Section fitur dengan grid, testimoni dengan scroll-snap, tabel harga dengan paket unggulan, serta footer dan form newsletter.", "nodes": ["Features", "Testimonials", "Pricing", "Footer"], "lessons": [{"k": "w", "t": "Section fitur dengan grid", "nodes": [], "b": ["Section fitur biasanya: judul section, subjudul, lalu 3 sampai 6 kartu berisi ikon, judul, dan teks singkat. Di desain desktop 3 kolom, tablet 2 kolom, ponsel 1 kolom. Dengan <code>repeat(auto-fit, minmax(240px, 1fr))</code>, kamu tidak perlu menulis media query sama sekali.", "Ukur <b>gap</b> antar kartu dan <b>jarak</b> judul section ke grid dari desain. Biasanya judul section rata tengah dengan lebar teks terbatas, sedangkan isi kartu rata kiri.", "Ikon di kartu fitur sering diletakkan di dalam lingkaran atau kotak berwarna lembut. Buat dengan <code>display: grid; place-items: center</code> dan ukuran tetap (48 × 48).", "Grid fitur di pratinjau belum dibuat."], "html": "<section class=\"fitur\">\n  <h2>Kenapa belajar di sini?</h2>\n  <div class=\"grid\">\n    <article><span class=\"ikon\">⚡</span><h3>Langsung praktik</h3><p>Editor jalan di browser, tanpa instalasi.</p></article>\n    <article><span class=\"ikon\">🇮🇩</span><h3>Bahasa Indonesia</h3><p>Penjelasan runtut dengan contoh lokal.</p></article>\n    <article><span class=\"ikon\">📱</span><h3>Bisa offline</h3><p>Pasang sebagai aplikasi di ponsel.</p></article>\n  </div>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.fitur { padding: 48px 16px; max-width: 1080px; margin: 0 auto; }\n.fitur h2 { text-align: center; margin: 0 0 32px; }\n.grid article { padding: 24px; border-radius: 16px; background: #F5F7FA; }\n.grid h3 { margin: 16px 0 8px; font-size: 18px; }\n.grid p { margin: 0; color: #52606D; }\n.ikon { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 12px; background: #E0F2F1; font-size: 22px; }", "task": {"q": "Jadikan <code>.grid</code> grid fluid: <code>display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px</code>.", "test": "getComputedStyle(document.querySelector('.grid')).display==='grid'&&parseFloat(getComputedStyle(document.querySelector('.grid')).rowGap)===24&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.grid'&&/auto-(fit|fill)/.test(r.style.gridTemplateColumns))", "hint": ".grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px }"}, "pts": ["auto-fit + minmax: 1–3 kolom tanpa media query.", "Judul section rata tengah, isi kartu rata kiri.", "Ikon dalam kotak 48 × 48 dengan place-items: center."], "q": [["Keuntungan auto-fit minmax untuk section fitur?", ["Jumlah kolom menyesuaikan lebar tanpa media query", "Kartu berwarna otomatis", "Mengurutkan kartu"], 0, "Grid menghitung sendiri."]], "so": [{"q": "Buat grid fitur yang tepat 3 kolom di desktop (≥ 1024px), 2 kolom di tablet, 1 kolom di ponsel, memakai media query.", "h": "Mobile-first dengan min-width.", "a": ".grid { display: grid; gap: 24px; }\n@media (min-width: 640px) { .grid { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 1024px) { .grid { grid-template-columns: repeat(3, 1fr); } }", "lang": "css"}]}, {"k": "w", "t": "Testimoni dengan scroll-snap", "nodes": [], "b": ["Desain mobile sering menampilkan testimoni sebagai <b>carousel</b> yang digeser horizontal. Kamu tidak perlu library JavaScript: CSS <b>scroll-snap</b> sudah cukup. Wadahnya <code>display: flex; overflow-x: auto; scroll-snap-type: x mandatory</code>, setiap kartu <code>scroll-snap-align: start</code> dan lebar tetap (misalnya 85% layar).", "Sisakan sebagian kartu berikutnya terlihat (peek) agar pengguna tahu bisa digeser. Pastikan carousel juga bisa digeser dengan keyboard (beri <code>tabindex=\"0\"</code> dan label pada wadah), dan jangan memutar otomatis tanpa tombol jeda.", "Di desktop, carousel yang sama bisa berubah menjadi grid tiga kolom dengan media query.", "Wadah testimoni di pratinjau sudah menggulir, tetapi belum \"mengunci\" ke kartu."], "html": "<section class=\"testi\" aria-label=\"Testimoni siswa\" tabindex=\"0\">\n  <blockquote class=\"k\">\"Akhirnya paham flexbox setelah 3 hari.\"<cite>Rina, Medan</cite></blockquote>\n  <blockquote class=\"k\">\"Proyek slicing pertamaku diterima klien.\"<cite>Andi, Makassar</cite></blockquote>\n  <blockquote class=\"k\">\"Materinya runtut dan ada soal latihannya.\"<cite>Sari, Bandung</cite></blockquote>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.testi { display: flex; gap: 12px; overflow-x: auto; padding: 16px; }\n.k { flex: 0 0 85%; margin: 0; padding: 24px; border-radius: 16px; background: #EEF2FF; font-size: 17px; }\n.k cite { display: block; margin-top: 12px; font-size: 14px; font-style: normal; color: #4338CA; }", "task": {"q": "Tambahkan <code>scroll-snap-type: x mandatory</code> pada <code>.testi</code> dan <code>scroll-snap-align: start</code> pada <code>.k</code>.", "test": "getComputedStyle(document.querySelector('.testi')).scrollSnapType.includes('x')&&getComputedStyle(document.querySelector('.k')).scrollSnapAlign.includes('start')", "hint": ".testi { scroll-snap-type: x mandatory } .k { scroll-snap-align: start }"}, "pts": ["Carousel tanpa JS: overflow-x + scroll-snap.", "Sisakan peek kartu berikutnya.", "Bisa digeser keyboard, jangan autoplay tanpa jeda."], "q": [["Kenapa kartu carousel dibuat 85% lebar, bukan 100%?", ["Agar kartu berikutnya terlihat sedikit sebagai petunjuk bisa digeser", "Agar hemat memori", "Aturan CSS"], 0, "Peek memberi isyarat."]], "so": [{"q": "Ubah carousel testimoni menjadi grid 3 kolom tanpa scroll di layar ≥ 1024px.", "h": "Di media query, ganti display dan matikan overflow.", "a": "@media (min-width: 1024px) {\n  .testi { display: grid; grid-template-columns: repeat(3, 1fr); overflow: visible; }\n  .k { flex: none; }\n}", "lang": "css"}]}, {"k": "w", "t": "Tabel harga dengan paket unggulan", "nodes": [], "b": ["Section harga berisi 2 sampai 4 kartu paket: nama, harga, periode, daftar fitur, dan tombol. Satu paket biasanya <b>ditonjolkan</b> (paling populer) dengan border tebal warna merek, lencana, dan tombol primary, sementara paket lain memakai tombol secondary.", "Tulis harga dengan format lokal yang benar: <b>Rp49.000</b> per bulan (titik sebagai pemisah ribuan, tanpa spasi setelah Rp). Fitur ditulis sebagai daftar <code>&lt;ul&gt;</code> dengan tanda centang; fitur yang tidak termasuk jangan hanya diberi warna abu-abu, beri juga teks atau ikon silang.", "Agar tombol semua kartu sejajar di bawah walau daftar fiturnya beda panjang, jadikan kartu <code>display: flex; flex-direction: column</code> dan beri tombol <code>margin-top: auto</code>.", "Kartu Pro di pratinjau harus menjadi paket unggulan."], "html": "<section class=\"harga\">\n  <article class=\"paket\"><h3>Gratis</h3><p class=\"h\">Rp0</p><ul><li>✓ 50 pelajaran</li></ul><a href=\"#\" class=\"b\">Mulai</a></article>\n  <article class=\"paket pro\"><h3>Pro</h3><p class=\"h\">Rp49.000<small>/bulan</small></p><ul><li>✓ Semua pelajaran</li><li>✓ Sertifikat</li><li>✓ Proyek dinilai mentor</li></ul><a href=\"#\" class=\"b\">Pilih Pro</a></article>\n</section>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.harga { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; padding: 16px; }\n.paket { display: flex; flex-direction: column; padding: 24px; border: 1px solid #D5D9E0; border-radius: 16px; }\n.paket h3 { margin: 0; }\n.h { font-size: 28px; font-weight: 700; margin: 8px 0 16px; }\n.h small { font-size: 14px; font-weight: 400; color: #52606D; }\n.paket ul { list-style: none; padding: 0; margin: 0 0 24px; display: grid; gap: 8px; }\n.b { margin-top: auto; text-align: center; padding: 12px; border-radius: 12px; border: 1px solid #1D5FA8; color: #1D5FA8; text-decoration: none; font-weight: 600; }", "task": {"q": "Tonjolkan paket Pro: <code>.pro</code> diberi <code>border: 2px solid #1D5FA8</code>, dan tombolnya (<code>.pro .b</code>) berlatar <code>#1D5FA8</code> dengan teks putih.", "test": "parseFloat(getComputedStyle(document.querySelector('.pro')).borderTopWidth)>=2&&getComputedStyle(document.querySelector('.pro .b')).backgroundColor==='rgb(29, 95, 168)'", "hint": ".pro { border: 2px solid #1D5FA8 } .pro .b { background: #1D5FA8; color: #fff }"}, "pts": ["Satu paket unggulan: border, lencana, tombol primary.", "Format harga Rp49.000.", "Tombol sejajar bawah: flex column + margin-top: auto."], "q": [["Cara membuat tombol semua kartu sejajar di bawah?", ["Kartu flex column, tombol margin-top: auto", "Tinggi kartu tetap 500px", "position: absolute"], 0, "Ruang kosong dipakai margin auto."]], "so": [{"q": "Tambahkan lencana \"Paling populer\" di kartu Pro dan fitur yang tidak termasuk di kartu Gratis dengan ikon dan teks.", "h": "Jangan hanya abu-abu; tulis \"Tidak termasuk\".", "a": "<article class=\"paket pro\">\n  <span class=\"lencana\">Paling populer</span>\n  ...\n</article>\n<article class=\"paket\">\n  <ul>\n    <li>✓ 50 pelajaran</li>\n    <li class=\"tidak\">✕ Sertifikat <span class=\"sr-only\">(tidak termasuk)</span></li>\n  </ul>\n</article>", "lang": "html"}]}, {"k": "w", "t": "Footer dan form newsletter", "nodes": [], "b": ["Footer berisi kelompok link (Produk, Perusahaan, Bantuan), media sosial, form newsletter, dan hak cipta. Di desktop kelompok link berdampingan; di mobile bertumpuk atau dilipat.", "Form newsletter di desain sering hanya menampilkan input dengan placeholder \"Email kamu\" dan tombol. Input tetap butuh <b>label</b>; jika desain tidak menampilkannya, sembunyikan secara visual dengan kelas <code>.sr-only</code> tetapi tetap terbaca pembaca layar. Pakai <code>type=\"email\"</code> dan <code>autocomplete=\"email\"</code> agar keyboard ponsel menampilkan tombol @.", "Ikon media sosial yang hanya berupa ikon wajib punya <code>aria-label</code> (\"Instagram Ruang Kode\").", "Form newsletter di pratinjau belum punya label dan tipe input yang tepat."], "html": "<footer class=\"kaki\">\n  <form class=\"news\">\n    <input id=\"surel\" placeholder=\"Email kamu\">\n    <button>Langganan</button>\n  </form>\n  <p>© 2026 RuangKode</p>\n</footer>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.kaki { padding: 32px 16px; background: #0F172A; color: #CBD5E1; }\n.news { display: flex; gap: 8px; flex-wrap: wrap; max-width: 420px; }\n.news input { flex: 1; min-width: 200px; padding: 12px; border-radius: 10px; border: 1px solid #475569; background: #1E293B; color: #fff; font-size: 16px; }\n.news button { padding: 12px 20px; border: 0; border-radius: 10px; background: #F59E0B; color: #1F2933; font-weight: 600; }\n.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }", "task": {"q": "Tambahkan <code>&lt;label class=\"sr-only\" for=\"surel\"&gt;Email&lt;/label&gt;</code>, lalu beri input <code>type=\"email\"</code> dan <code>autocomplete=\"email\"</code>.", "test": "!!document.querySelector('label[for=\"surel\"]')&&document.getElementById('surel').type==='email'&&document.getElementById('surel').autocomplete==='email'", "hint": "<label class=\"sr-only\" for=\"surel\">Email</label><input id=\"surel\" type=\"email\" autocomplete=\"email\" placeholder=\"Email kamu\">"}, "pts": ["Label tetap ada; sembunyikan secara visual dengan .sr-only.", "type=\"email\" dan autocomplete=\"email\".", "Ikon sosial butuh aria-label."], "q": [["Desain tidak menampilkan label input. Solusi yang benar?", ["Hapus label", "Label dengan kelas sr-only", "Pakai placeholder saja"], 1, "Tetap terbaca pembaca layar."]], "so": [{"q": "Tulis tautan ikon Instagram dan YouTube yang aksesibel.", "h": "aria-label pada tautan, aria-hidden pada ikon.", "a": "<a href=\"https://instagram.com/ruangkode\" aria-label=\"Instagram Ruang Kode\"><svg aria-hidden=\"true\" width=\"24\" height=\"24\">...</svg></a>\n<a href=\"https://youtube.com/@ruangkode\" aria-label=\"YouTube Ruang Kode\"><svg aria-hidden=\"true\" width=\"24\" height=\"24\">...</svg></a>", "lang": "html"}]}]}, {"t": "Responsif dan pixel-perfect", "lvl": "Menengah", "d": "Mobile-first dengan breakpoint dari desain, gambar responsif dengan srcset, membandingkan hasil dengan desain, dan aksesibilitas hasil slicing.", "nodes": ["Mobile-first", "srcset", "Pixel-perfect", "Accessibility"], "lessons": [{"k": "w", "t": "Mobile-first dan breakpoint dari desain", "nodes": [], "b": ["Desainer biasanya memberi dua atau tiga frame: mobile (360 atau 390), tablet (768), dan desktop (1440). <b>Mobile-first</b> berarti CSS dasar ditulis untuk mobile, lalu ditambah dengan <code>@media (min-width: ...)</code> untuk layar yang lebih lebar. Kodenya lebih ringkas daripada sebaliknya.", "Breakpoint diambil dari titik desain <b>berubah</b>, bukan dari nama perangkat. Jika frame tablet menunjukkan kartu menjadi 2 kolom, tulis <code>@media (min-width: 768px)</code>. Di antara dua frame, bayangkan sendiri perilakunya: apa yang melar, apa yang dibatasi lebar maksimumnya.", "Uji di DevTools (Ctrl + Shift + M) dengan menyeret lebar layar pelan-pelan dari 320 sampai 1600 px. Bagian yang rusak di lebar \"tanggung\" seperti 900 px sering terlewat jika hanya mengecek tiga ukuran frame.", "Daftar kelas di pratinjau satu kolom. Buat 2 kolom mulai lebar 600px."], "html": "<ul class=\"daftar\">\n  <li>HTML</li><li>CSS</li><li>JavaScript</li><li>Figma</li>\n</ul>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.daftar { list-style: none; margin: 0; padding: 16px; display: grid; gap: 12px; }\n.daftar li { padding: 16px; border-radius: 12px; background: #F0FDFA; font-weight: 600; }\n/* tulis media query di bawah */", "task": {"q": "Tambahkan <code>@media (min-width: 600px) { .daftar { grid-template-columns: 1fr 1fr; } }</code>.", "test": "[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.media&&/min-width/.test(r.media.mediaText)&&[...r.cssRules].some(x=>x.selectorText==='.daftar'&&x.style.gridTemplateColumns))", "hint": "@media (min-width: 600px) { .daftar { grid-template-columns: 1fr 1fr } }"}, "pts": ["CSS dasar untuk mobile, tambah dengan min-width.", "Breakpoint dari titik desain berubah.", "Seret lebar layar pelan-pelan, jangan hanya 3 ukuran."], "q": [["Mobile-first memakai media query?", ["min-width", "max-width"], 0, "Aturan ditambahkan saat layar melebar."]], "so": [{"q": "Desain punya frame 390 (1 kolom kartu), 834 (2 kolom), 1440 (4 kolom, lebar konten maks 1200). Tulis rencana breakpoint dan CSS-nya.", "h": "Breakpoint dari titik perubahan; container maks 1200.", "a": ".wrap { max-width: 1200px; margin: 0 auto; padding: 0 16px; }\n.grid { display: grid; gap: 16px; }\n@media (min-width: 768px)  { .grid { grid-template-columns: repeat(2, 1fr); } }\n@media (min-width: 1200px) { .grid { grid-template-columns: repeat(4, 1fr); } }", "lang": "text"}]}, {"k": "w", "t": "Gambar responsif dengan srcset", "nodes": [], "b": ["Satu gambar besar untuk semua layar membuang kuota pengguna ponsel. Atribut <code>srcset</code> memberi browser beberapa pilihan file, dan <code>sizes</code> memberi tahu lebar tampil gambar. Browser lalu memilih file terkecil yang tetap tajam untuk layar itu.", "Contoh: <code>srcset=\"kopi-480.webp 480w, kopi-960.webp 960w, kopi-1440.webp 1440w\"</code> dan <code>sizes=\"(min-width: 768px) 50vw, 100vw\"</code>. Artinya: di layar lebar gambar tampil selebar setengah layar, di ponsel selebar penuh.", "Jika desain meminta <b>potongan berbeda</b> (art direction), misalnya foto lebar di desktop tetapi potongan persegi di mobile, pakai <code>&lt;picture&gt;</code> dengan beberapa <code>&lt;source media=\"...\"&gt;</code>.", "Gambar di pratinjau hanya punya satu file."], "html": "<img class=\"foto\" src=\"kopi-960.webp\" alt=\"Barista menyeduh kopi\" width=\"960\" height=\"640\">", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.foto { display: block; max-width: 100%; height: auto; background: #D7B899; }", "task": {"q": "Tambahkan <code>srcset</code> dengan tiga ukuran (480w, 960w, 1440w) dan <code>sizes=\"(min-width: 768px) 50vw, 100vw\"</code>.", "test": "(i=>(i.getAttribute('srcset')||'').split(',').length>=3&&/\\d+w/.test(i.getAttribute('srcset'))&&!!i.getAttribute('sizes'))(document.querySelector('.foto'))", "hint": "srcset=\"kopi-480.webp 480w, kopi-960.webp 960w, kopi-1440.webp 1440w\" sizes=\"(min-width: 768px) 50vw, 100vw\""}, "pts": ["srcset: daftar file dengan lebar aslinya (w).", "sizes: lebar tampil gambar di setiap kondisi.", "picture + source untuk potongan berbeda."], "q": [["Apa arti 960w di srcset?", ["Lebar asli file 960 piksel", "Tampilkan 960 piksel", "Lebar layar 960"], 0, "Browser memakai info ini untuk memilih."]], "so": [{"q": "Tulis elemen picture: desktop memakai foto lebar 16:9, ponsel memakai potongan persegi.", "h": "source dengan media min-width untuk desktop, img sebagai cadangan.", "a": "<picture>\n  <source media=\"(min-width: 768px)\" srcset=\"hero-lebar-1280.webp 1280w, hero-lebar-1920.webp 1920w\" sizes=\"100vw\">\n  <img src=\"hero-persegi-720.webp\" srcset=\"hero-persegi-480.webp 480w, hero-persegi-720.webp 720w\" sizes=\"100vw\" alt=\"Kedai KopiNusa\" width=\"720\" height=\"720\">\n</picture>", "lang": "html"}]}, {"k": "c", "t": "Pixel-perfect: membandingkan dengan desain", "nodes": [], "b": ["<b>Pixel-perfect</b> berarti hasil slicing sesuai desain sampai detail: jarak, ukuran huruf, warna, radius, bayangan. Ini bukan soal obsesi 1 piksel, melainkan menghormati keputusan desainer dan menjaga konsistensi produk.", "Cara membandingkan: (1) ekspor frame desain sebagai PNG pada lebar yang sama; (2) buka hasilmu di DevTools device mode dengan lebar yang sama; (3) pakai ekstensi overlay seperti <b>PerfectPixel</b> untuk menumpuk gambar desain semi-transparan di atas halaman; (4) atau letakkan tangkapan layar berdampingan dan periksa per section.", "Prioritaskan perbedaan berdasarkan dampak: <b>tinggi</b> (warna salah, font salah, elemen hilang, layout rusak di ukuran tertentu), <b>sedang</b> (jarak antar section, ukuran ikon), <b>rendah</b> (selisih 1 sampai 2 px yang disebabkan perbedaan render font antar sistem operasi). Diskusikan dengan desainer perbedaan yang memang tidak bisa dihindari."], "tb": [{"c": "Daftar periksa visual per section", "h": ["Periksa", "Cara"], "r": [["Font dan ketebalan", "DevTools → Computed → font-family, font-weight"], ["Ukuran dan line-height", "Bandingkan dengan panel Figma"], ["Warna", "Eyedropper DevTools vs nilai variabel Figma"], ["Jarak antar elemen", "Hover di DevTools menampilkan margin dan padding"], ["Radius dan bayangan", "Bandingkan dengan overlay"], ["Lebar maksimum konten", "Cek di 1440 dan 1920 px"], ["Teks panjang", "Ganti teks dengan kalimat 2× lebih panjang"], ["State", "Hover, focus, disabled sesuai desain"]]}], "pts": ["Pixel-perfect: jarak, huruf, warna, radius, bayangan sesuai desain.", "Bandingkan di lebar yang sama dengan overlay.", "Prioritaskan berdasarkan dampak."], "q": [["Perbedaan mana yang paling penting diperbaiki dulu?", ["Selisih 1 px karena render font", "Warna tombol utama salah", "Bayangan sedikit lebih tipis"], 1, "Dampaknya paling terlihat dan merusak konsistensi merek."]], "so": [{"q": "Kamu menemukan 5 perbedaan: (a) tombol radius 8 seharusnya 12, (b) font fallback tampil karena salah nama, (c) jarak section 64 seharusnya 80, (d) teks 1 px lebih tinggi di Windows, (e) menu mobile tidak muncul. Urutkan prioritasnya.", "h": "Dampak terbesar dulu.", "a": "1. (e) menu mobile tidak muncul (fungsi rusak)\n2. (b) font salah (merusak tampilan seluruh halaman)\n3. (c) jarak section\n4. (a) radius tombol\n5. (d) selisih render font antar OS: catat, umumnya diterima", "lang": "text"}]}, {"k": "w", "t": "Aksesibilitas hasil slicing", "nodes": [], "b": ["Desain jarang menunjukkan hal yang tidak terlihat, padahal itu tanggung jawab slicer: <b>urutan fokus</b> keyboard yang logis, <b>indikator fokus</b> yang jelas, <b>alt</b> gambar, <b>label</b> form, <b>bahasa</b> halaman (<code>&lt;html lang=\"id\"&gt;</code>), dan <b>skip link</b>.", "<b>Skip link</b> adalah tautan pertama di halaman, tersembunyi sampai difokuskan dengan Tab, yang langsung melompat ke konten utama. Pengguna keyboard tidak perlu melewati 15 link navbar di setiap halaman.", "Uji cepat setelah slicing: tekan Tab dari atas sampai bawah tanpa mouse; jalankan Lighthouse (tab Lighthouse di DevTools, kategori Accessibility); zoom browser 200% dan pastikan tidak ada teks terpotong atau scroll horizontal.", "Halaman di pratinjau belum punya skip link."], "html": "<header class=\"nav\"><a href=\"#\">Beranda</a><a href=\"#\">Kelas</a><a href=\"#\">Harga</a><a href=\"#\">Blog</a><a href=\"#\">Masuk</a></header>\n<main><h1>Kelas Slicing Website</h1><p>Konten utama halaman.</p></main>", "css": "body { font-family: system-ui, sans-serif; margin: 0; color: #1F2933; }\n.nav { display: flex; gap: 12px; flex-wrap: wrap; padding: 12px 16px; border-bottom: 1px solid #E4E7EB; }\nmain { padding: 24px 16px; }\n.skip { position: absolute; left: 8px; top: -48px; background: #1F2933; color: #fff; padding: 8px 12px; border-radius: 8px; }\n.skip:focus { top: 8px; }", "task": {"q": "Tambahkan <code>&lt;a class=\"skip\" href=\"#isi\"&gt;Lewati ke konten&lt;/a&gt;</code> sebagai elemen pertama, dan beri <code>main</code> <code>id=\"isi\"</code>.", "test": "(a=>!!a&&a.classList.contains('skip')&&a.getAttribute('href')==='#isi')(document.body.querySelector('a'))&&!!document.querySelector('main#isi')", "hint": "<a class=\"skip\" href=\"#isi\">Lewati ke konten</a> di paling atas, lalu <main id=\"isi\">"}, "pts": ["Slicer bertanggung jawab atas fokus, alt, label, lang, skip link.", "Skip link melompati navigasi.", "Uji: Tab, Lighthouse, zoom 200%."], "q": [["Siapa yang paling diuntungkan skip link?", ["Pengguna keyboard dan pembaca layar", "Mesin pencari", "Desainer"], 0, "Tidak perlu melewati navigasi berulang."]], "so": [{"q": "Tulis 5 langkah uji aksesibilitas cepat yang bisa kamu lakukan dalam 10 menit setelah slicing.", "h": "Keyboard, Lighthouse, zoom, alt, kontras.", "a": "1. Tekan Tab dari atas ke bawah: urutan logis dan fokus terlihat.\n2. Lighthouse → Accessibility, perbaiki semua temuan merah.\n3. Zoom 200%: tidak ada teks terpotong atau scroll horizontal.\n4. Matikan gambar atau baca alt di DevTools: alt bermakna.\n5. Cek kontras teks abu-abu dengan DevTools color picker.", "lang": "text"}]}]}, {"t": "Proyek dan serah terima", "lvl": "Menengah", "d": "Proyek landing page lengkap, deploy hasil slicing, dan daftar periksa QA sebelum diserahkan ke klien.", "nodes": ["Project", "Deploy", "QA"], "lessons": [{"k": "w", "t": "Proyek: landing page kedai kopi", "nodes": [], "b": ["Saatnya menggabungkan semua: navbar sticky, hero, fitur, harga, dan footer dalam satu halaman. Kerangka di pratinjau sudah memakai token, HTML semantik, dan grid fluid. Lengkapi bagian yang belum sesuai desain.", "Spesifikasi desain: navbar menempel di atas saat menggulir, hero dua kolom mulai 768 px, kartu menu memakai grid auto-fill minimal 180 px, dan semua warna dari token.", "Setelah tantangan selesai, salin kode ke VS Code, buka dengan Live Server, lalu uji di ponselmu lewat jaringan Wi-Fi yang sama. Langkah berikutnya: deploy, dibahas di pelajaran selanjutnya."], "html": "<header class=\"nav\"><a class=\"logo\" href=\"#\">Kopi<b>Nusa</b></a><a class=\"btn\" href=\"#menu\">Pesan</a></header>\n<main>\n  <section class=\"hero\"><div><h1>Kopi lokal, diseduh hari ini</h1><p>Gayo, Toraja, Kintamani. Diantar 30 menit.</p><a class=\"btn\" href=\"#menu\">Lihat menu</a></div><div class=\"foto\" role=\"img\" aria-label=\"Kopi\"></div></section>\n  <section id=\"menu\" class=\"menu\"><h2>Menu favorit</h2>\n    <div class=\"grid\"><article class=\"kartu\"><h3>Kopi Susu Aren</h3><p>Rp22.000</p></article><article class=\"kartu\"><h3>Americano</h3><p>Rp18.000</p></article><article class=\"kartu\"><h3>Kopi Tubruk</h3><p>Rp15.000</p></article></div>\n  </section>\n</main>\n<footer class=\"kaki\">© 2026 KopiNusa</footer>", "css": ":root { --brand: #6D4C41; --brand-soft: #FFF8EE; --ink: #3E2723; --radius: 16px; --space: 16px; }\nbody { font-family: system-ui, sans-serif; margin: 0; color: var(--ink); }\n.nav { display: flex; justify-content: space-between; align-items: center; padding: 12px var(--space); background: #fff; border-bottom: 1px solid #E7E0D8; }\n.logo { color: var(--ink); text-decoration: none; font-size: 20px; }\n.btn { display: inline-block; background: var(--brand); color: #fff; padding: 10px 18px; border-radius: 999px; text-decoration: none; font-weight: 600; }\n.hero { display: grid; gap: 24px; padding: 32px var(--space); background: var(--brand-soft); }\n@media (min-width: 768px) { .hero { grid-template-columns: 1fr 1fr; align-items: center; } }\n.hero h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); margin: 0 0 12px; }\n.foto { aspect-ratio: 4 / 3; border-radius: 24px; background: radial-gradient(circle at 40% 40%, #D7B899, var(--brand)); }\n.menu { padding: 32px var(--space); }\n.kartu { padding: var(--space); border-radius: var(--radius); background: #F5F0EB; }\n.kartu h3 { margin: 0 0 4px; font-size: 16px; }\n.kartu p { margin: 0; font-weight: 600; color: var(--brand); }\n.kaki { padding: 24px var(--space); background: var(--ink); color: #EFE6DD; }", "task": {"q": "Selesaikan dua hal: navbar <code>.nav</code> menempel (<code>position: sticky; top: 0; z-index: 10</code>), dan <code>.grid</code> menjadi grid fluid <code>repeat(auto-fill, minmax(180px, 1fr))</code> dengan gap 16px.", "test": "getComputedStyle(document.querySelector('.nav')).position==='sticky'&&getComputedStyle(document.querySelector('.grid')).display==='grid'&&[...document.styleSheets].flatMap(s=>[...s.cssRules]).some(r=>r.selectorText==='.grid'&&/auto-(fill|fit)/.test(r.style.gridTemplateColumns))", "hint": ".nav { position: sticky; top: 0; z-index: 10 } .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px }"}, "pts": ["Gabungkan token, HTML semantik, flex, dan grid.", "Uji di ponsel lewat Live Server.", "Selesaikan spesifikasi sebelum menambah hiasan."], "q": [["Kenapa navbar sticky butuh z-index?", ["Agar konten yang digulir tidak tampil di atasnya", "Agar lebih cepat", "Agar berwarna"], 0, "Navbar tetap di lapisan atas."]], "so": [{"q": "Tambahkan section FAQ ke proyek memakai details/summary, dengan gaya yang memakai token proyek.", "h": "details untuk setiap pertanyaan, summary sebagai pertanyaan.", "a": ".faq details { border-bottom: 1px solid #E7E0D8; padding: var(--space) 0; }\n.faq summary { cursor: pointer; font-weight: 600; color: var(--ink); }\n.faq summary::marker { color: var(--brand); }\n.faq p { margin: 8px 0 0; }", "lang": "css"}]}, {"k": "c", "t": "Deploy hasil slicing", "nodes": [], "b": ["Klien ingin melihat hasilnya di internet, bukan file zip. Tiga cara gratis yang paling umum: <b>GitHub Pages</b> (push ke repositori, aktifkan Pages di Settings), <b>Netlify</b> (seret folder ke app.netlify.com/drop), dan <b>Vercel</b> (hubungkan repositori GitHub, setiap push otomatis di-deploy dan setiap branch dapat URL pratinjau).", "Sebelum deploy: pastikan file utama bernama <code>index.html</code>, semua path relatif (<code>./css/style.css</code>, bukan <code>C:\\Users\\...</code>), nama file huruf kecil tanpa spasi (server Linux membedakan <code>Logo.png</code> dan <code>logo.png</code>), dan gambar sudah dikompres.", "Setelah deploy, kirim link ke klien dan uji sendiri di ponsel dengan data seluler (bukan Wi-Fi kantor) untuk merasakan kecepatan aslinya. Jalankan PageSpeed Insights (pagespeed.web.dev) dan catat skornya."], "lang": "bash", "code": "# GitHub Pages lewat terminal\ngit init\ngit add .\ngit commit -m \"Slicing landing page KopiNusa\"\ngit branch -M main\ngit remote add origin https://github.com/namakamu/kopinusa.git\ngit push -u origin main\n# Lalu: Settings → Pages → Branch: main → Save\n# Situs tersedia di https://namakamu.github.io/kopinusa/", "tb": [{"c": "Pilihan hosting gratis", "h": ["Layanan", "Cara", "Kelebihan"], "r": [["GitHub Pages", "Push ke repo, aktifkan Pages", "Sekalian portofolio di GitHub"], ["Netlify Drop", "Seret folder ke browser", "Paling cepat, tanpa Git"], ["Vercel", "Hubungkan repo GitHub", "URL pratinjau setiap branch"]]}], "pts": ["GitHub Pages, Netlify, Vercel.", "index.html, path relatif, nama file huruf kecil.", "Uji dengan data seluler dan PageSpeed Insights."], "q": [["Gambar tampil di laptop tapi rusak setelah deploy. Penyebab paling umum?", ["Beda huruf besar-kecil nama file atau path absolut", "Internet lambat", "Browser lama"], 0, "Server Linux peka huruf besar-kecil."]], "so": [{"q": "Hasil deploy GitHub Pages tampil tanpa CSS. Path di HTML: <code>/css/style.css</code>, situs di <code>namakamu.github.io/kopinusa/</code>. Apa penyebab dan perbaikannya?", "h": "Garis miring di awal merujuk ke akar domain, bukan folder proyek.", "a": "Penyebab: /css/style.css dicari di namakamu.github.io/css/style.css (akar domain),\nbukan di /kopinusa/css/style.css.\nPerbaikan: pakai path relatif css/style.css atau ./css/style.css.", "lang": "text"}]}, {"k": "c", "t": "Daftar periksa QA sebelum serah terima", "nodes": [], "b": ["Sebelum menyerahkan hasil slicing, jalankan daftar periksa ini. Klien dan desainer akan menemukan masalah yang sama jika kamu melewatkannya, dan kesan pertama sulit diulang.", "Kelompokkan pemeriksaan menjadi: <b>visual</b> (sesuai desain di 360, 768, 1440 px), <b>fungsi</b> (semua link dan tombol bekerja, form tervalidasi), <b>aksesibilitas</b> (Tab, alt, label, kontras), <b>performa</b> (gambar terkompres, skor Lighthouse), <b>kompatibilitas</b> (Chrome, Safari iOS, Firefox, Samsung Internet), dan <b>SEO dasar</b> (title, meta description, Open Graph).", "Tulis laporan singkat saat serah terima: link deploy, browser yang sudah diuji, skor Lighthouse, dan daftar perbedaan dengan desain yang disengaja beserta alasannya. Laporan ini membuatmu terlihat profesional dan mencegah perdebatan di kemudian hari."], "tb": [{"c": "Daftar periksa serah terima", "h": ["Kelompok", "Periksa"], "r": [["Visual", "Sesuai desain di 360, 768, 1440 px; tidak ada scroll horizontal"], ["Fungsi", "Semua link, tombol, menu mobile, dan form bekerja"], ["Aksesibilitas", "Tab berurutan, fokus terlihat, alt, label, kontras 4,5:1"], ["Performa", "Gambar WebP terkompres, Lighthouse Performance ≥ 90"], ["Kompatibilitas", "Chrome, Safari iOS, Firefox, Samsung Internet"], ["SEO", "title, meta description, Open Graph, favicon, lang=\"id\""], ["Konten", "Tidak ada lorem ipsum, ejaan benar, format Rp dan tanggal benar"], ["Serah terima", "Link deploy, repositori, laporan pengujian"]]}], "pts": ["Visual, fungsi, aksesibilitas, performa, kompatibilitas, SEO.", "Uji di Safari iOS dan Samsung Internet juga.", "Serahkan laporan pengujian."], "q": [["Browser mana yang sering terlupa diuji padahal banyak dipakai di Indonesia?", ["Samsung Internet", "Internet Explorer 6", "Netscape"], 0, "Bawaan banyak ponsel Samsung."]], "so": [{"q": "Tulis laporan serah terima singkat untuk proyek KopiNusa.", "h": "Link, browser yang diuji, skor, perbedaan yang disengaja.", "a": "Proyek  : Landing page KopiNusa\nLink    : https://kopinusa.vercel.app\nRepo    : github.com/namakamu/kopinusa\nDiuji di: Chrome 131, Safari iOS 18, Firefox 133, Samsung Internet 27; lebar 360, 768, 1440\nLighthouse: Performance 96, Accessibility 100, Best Practices 100, SEO 100\nPerbedaan disengaja: bayangan kartu dibuat lebih tipis di dark mode agar kontras tetap 4,5:1 (disetujui desainer 12/11).", "lang": "text"}]}]}];
const SLM_MODULES=[{"t": "Persiapan slicing mobile", "lvl": "Pemula", "d": "Membaca desain mobile (frame, dp dan pt, safe area), mengekspor aset dan ikon untuk Flutter dan Android, serta memindahkan token ke ThemeData dan MaterialTheme.", "nodes": ["Mobile frames", "Assets", "Theme"], "lessons": [{"k": "c", "t": "Membaca desain mobile", "nodes": [], "b": ["Desain mobile di Figma biasanya memakai frame <b>360 × 800</b> (Android) atau <b>390 × 844</b> / <b>393 × 852</b> (iPhone). Satuan di Figma adalah piksel logis, yang sama dengan <b>dp</b> di Android (dan Flutter) dan <b>pt</b> di iOS. Jadi padding 16 di Figma menjadi <code>16.dp</code> di Compose dan <code>16</code> di Flutter, tanpa konversi.", "Perhatikan area yang tidak boleh diisi konten penting: <b>status bar</b> di atas, <b>notch</b> atau kamera, dan <b>gesture bar</b> di bawah. Di Flutter, bungkus layar dengan <code>SafeArea</code>; di Compose, pakai <code>Scaffold</code> dan parameter <code>innerPadding</code> atau <code>Modifier.windowInsetsPadding</code>. Sejak Android 15, aplikasi tampil <b>edge-to-edge</b> secara bawaan, jadi inset wajib ditangani.", "Ukuran target sentuh minimal <b>48 × 48 dp</b> di Android dan <b>44 × 44 pt</b> di iOS, walau ikonnya hanya 24. Jika desain menunjukkan ikon tanpa area sentuh, tanyakan ke desainer atau perbesar area sentuhnya tanpa mengubah tampilan."], "tb": [{"c": "Figma ke Flutter dan Compose", "h": ["Figma", "Flutter", "Jetpack Compose"], "r": [["16 (px logis)", "16 (logical pixel)", "16.dp"], ["Text 16", "fontSize: 16", "16.sp"], ["Frame 360 × 800", "MediaQuery.sizeOf(context)", "LocalConfiguration / WindowSizeClass"], ["Safe area", "SafeArea(child: ...)", "Scaffold innerPadding, WindowInsets"], ["Target sentuh 48", "minimumSize: Size(48, 48)", "Modifier.minimumInteractiveComponentSize()"]]}], "pts": ["Piksel Figma = dp (Android, Flutter) = pt (iOS).", "Hormati status bar, notch, gesture bar: SafeArea dan insets.", "Target sentuh 48 dp / 44 pt."], "q": [["Padding 24 di Figma menjadi apa di Compose?", ["24.dp", "48.dp", "24.px"], 0, "Satu banding satu."], ["Ukuran huruf di Compose memakai satuan?", ["dp", "sp", "pt"], 1, "sp mengikuti pengaturan ukuran huruf pengguna."]], "so": [{"q": "Frame Figma 390 × 844 berisi: padding layar 20, judul 28/34, kartu tinggi 120 radius 16, tombol tinggi 52. Tulis nilai Flutter dan Compose-nya.", "h": "Satu banding satu; huruf memakai sp di Compose.", "a": "Flutter : EdgeInsets.all(20), TextStyle(fontSize: 28, height: 34 / 28), SizedBox(height: 120), BorderRadius.circular(16), Size.fromHeight(52)\nCompose : Modifier.padding(20.dp), fontSize = 28.sp, lineHeight = 34.sp, Modifier.height(120.dp), RoundedCornerShape(16.dp), Modifier.height(52.dp)", "lang": "text"}]}, {"k": "c", "t": "Ekspor aset dan ikon", "nodes": [], "b": ["<b>Ikon</b>: ekspor sebagai SVG. Di Flutter, pakai paket <code>flutter_svg</code>, atau ubah ikon menjadi font ikon. Di Android, impor SVG lewat <b>Resource Manager → Vector Asset</b> sehingga menjadi file XML di <code>res/drawable</code>. Jika ikon ada di Material Symbols, langsung pakai <code>Icons.Outlined.ShoppingCart</code> tanpa ekspor.", "<b>Gambar bitmap</b>: Flutter memakai folder resolusi <code>assets/images/</code>, <code>assets/images/2.0x/</code>, <code>assets/images/3.0x/</code> dengan nama file yang sama; Flutter memilih otomatis. Android memakai <code>drawable-mdpi</code>, <code>-hdpi</code>, <code>-xhdpi</code>, <code>-xxhdpi</code>, <code>-xxxhdpi</code> (1×, 1,5×, 2×, 3×, 4×), atau cukup WebP satu ukuran besar di <code>drawable-nodpi</code> untuk ilustrasi.", "Nama aset: huruf kecil, garis bawah, tanpa spasi (<code>ic_cart.xml</code>, <code>img_onboarding_1.webp</code>). Android menolak nama dengan huruf besar atau tanda hubung."], "lang": "yaml", "code": "# pubspec.yaml (Flutter)\ndependencies:\n  flutter_svg: ^2.0.10\n\nflutter:\n  assets:\n    - assets/icons/\n    - assets/images/\n\n# Struktur folder\nassets/\n  icons/ic_cart.svg\n  images/img_hero.png\n  images/2.0x/img_hero.png\n  images/3.0x/img_hero.png", "pts": ["Ikon SVG: flutter_svg atau Vector Asset Android.", "Bitmap: folder 2.0x 3.0x (Flutter) atau drawable-xxhdpi (Android).", "Nama aset huruf kecil dan garis bawah."], "q": [["Nama file mana yang ditolak Android?", ["ic_cart.xml", "Ic-Cart.xml", "img_hero.webp"], 1, "Huruf besar dan tanda hubung tidak boleh."], ["Di Flutter, gambar 3× disimpan di?", ["assets/images/3.0x/", "assets/images@3x/", "res/drawable-xxhdpi/"], 0, "Folder resolusi dengan nama file yang sama."]], "so": [{"q": "Tampilkan ikon SVG keranjang 24×24 berwarna primary tema di Flutter.", "h": "SvgPicture.asset dengan colorFilter.", "a": "SvgPicture.asset(\n  'assets/icons/ic_cart.svg',\n  width: 24,\n  height: 24,\n  colorFilter: ColorFilter.mode(Theme.of(context).colorScheme.primary, BlendMode.srcIn),\n  semanticsLabel: 'Keranjang',\n)", "lang": "dart"}]}, {"k": "c", "t": "Token desain ke ThemeData dan MaterialTheme", "nodes": [], "b": ["Sama seperti di web, langkah pertama slicing mobile adalah memindahkan token. Di Flutter, warna masuk ke <code>ColorScheme</code> dan gaya teks ke <code>TextTheme</code> di dalam <code>ThemeData</code>. Di Compose, warna masuk ke <code>lightColorScheme()</code> atau <code>darkColorScheme()</code> dan teks ke <code>Typography</code> di dalam <code>MaterialTheme</code>.", "Setelah itu, widget mengambil warna dari tema, bukan kode hex: <code>Theme.of(context).colorScheme.primary</code> di Flutter, <code>MaterialTheme.colorScheme.primary</code> di Compose. Dark mode cukup menyediakan skema kedua.", "Jika desainer memakai Material Theme Builder di Figma, kamu bisa langsung mengekspor kode tema untuk Flutter dan Compose dari plugin itu."], "lang": "dart", "code": "// Flutter\nfinal tema = ThemeData(\n  useMaterial3: true,\n  colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF6D4C41)),\n  textTheme: const TextTheme(\n    headlineSmall: TextStyle(fontSize: 24, fontWeight: FontWeight.w600, height: 32 / 24),\n    bodyLarge: TextStyle(fontSize: 16, height: 24 / 16),\n    labelLarge: TextStyle(fontSize: 14, fontWeight: FontWeight.w500, letterSpacing: 0.1),\n  ),\n);\n\n// Pemakaian\nText('Menu favorit', style: Theme.of(context).textTheme.headlineSmall);\nContainer(color: Theme.of(context).colorScheme.primaryContainer);", "tb": [{"c": "Token ke tema", "h": ["Token", "Flutter", "Compose"], "r": [["color/primary", "colorScheme.primary", "MaterialTheme.colorScheme.primary"], ["color/surface", "colorScheme.surface", "MaterialTheme.colorScheme.surface"], ["Title/Medium", "textTheme.titleMedium", "MaterialTheme.typography.titleMedium"], ["radius/md 12", "BorderRadius.circular(12)", "RoundedCornerShape(12.dp)"], ["spacing/4 16", "EdgeInsets.all(16)", "Modifier.padding(16.dp)"]]}], "pts": ["Warna ke ColorScheme, teks ke TextTheme / Typography.", "Widget mengambil dari tema, bukan hex.", "Material Theme Builder bisa mengekspor kode tema."], "q": [["Di Compose, warna utama tema diambil dengan?", ["MaterialTheme.colorScheme.primary", "Color.Primary", "R.color.primary"], 0, "Dari tema yang aktif."]], "so": [{"q": "Buat skema warna terang Compose dari token: primary #6D4C41, onPrimary #FFFFFF, primaryContainer #FFDBCF, surface #FFF8F5.", "h": "lightColorScheme dengan parameter bernama.", "a": "val KopiLight = lightColorScheme(\n    primary = Color(0xFF6D4C41),\n    onPrimary = Color(0xFFFFFFFF),\n    primaryContainer = Color(0xFFFFDBCF),\n    surface = Color(0xFFFFF8F5)\n)\n\n@Composable\nfun KopiTheme(content: @Composable () -> Unit) {\n    MaterialTheme(colorScheme = KopiLight, content = content)\n}", "lang": "kotlin"}]}]}, {"t": "Slicing layar login", "lvl": "Pemula", "d": "Memetakan auto layout ke Row, Column, dan padding, lalu men-slicing layar login di Flutter dan Jetpack Compose.", "nodes": ["Layout mapping", "Flutter", "Compose"], "lessons": [{"k": "c", "t": "Memetakan auto layout ke Row dan Column", "nodes": [], "b": ["Auto layout Figma diterjemahkan hampir satu banding satu. <b>Vertical</b> menjadi <code>Column</code>, <b>horizontal</b> menjadi <code>Row</code>, <b>gap</b> menjadi <code>SizedBox</code> atau <code>spacing</code> (Flutter 3.27+) dan <code>Arrangement.spacedBy()</code> di Compose, <b>padding</b> menjadi <code>Padding</code> atau <code>Modifier.padding</code>.", "<b>Fill container</b> menjadi <code>Expanded</code> (Flutter) atau <code>Modifier.weight(1f)</code> / <code>fillMaxWidth()</code> (Compose). <b>Hug contents</b> adalah perilaku bawaan. Elemen bertumpuk (gambar dengan lencana di pojok) menjadi <code>Stack</code> di Flutter dan <code>Box</code> di Compose.", "Daftar panjang yang bisa digulir jangan memakai Column biasa: pakai <code>ListView.builder</code> (Flutter) atau <code>LazyColumn</code> (Compose) agar hanya item yang terlihat yang dibuat."], "tb": [{"c": "Auto layout ke widget", "h": ["Figma", "Flutter", "Compose"], "r": [["Vertical, gap 16", "Column(spacing: 16)", "Column(verticalArrangement = Arrangement.spacedBy(16.dp))"], ["Horizontal, gap 8", "Row(spacing: 8)", "Row(horizontalArrangement = Arrangement.spacedBy(8.dp))"], ["Padding 24", "Padding(padding: EdgeInsets.all(24))", "Modifier.padding(24.dp)"], ["Fill container (sumbu utama)", "Expanded(child: ...)", "Modifier.weight(1f)"], ["Fill container (lebar)", "SizedBox(width: double.infinity)", "Modifier.fillMaxWidth()"], ["Align center", "crossAxisAlignment: center", "horizontalAlignment = Alignment.CenterHorizontally"], ["Elemen bertumpuk", "Stack + Positioned", "Box + Modifier.align()"], ["Daftar panjang", "ListView.builder", "LazyColumn"]]}], "pts": ["Vertical = Column, horizontal = Row.", "Fill = Expanded / weight; bertumpuk = Stack / Box.", "Daftar panjang = ListView.builder / LazyColumn."], "q": [["Fill container di dalam Row Compose menjadi?", ["Modifier.weight(1f)", "Modifier.wrapContentWidth()", "Arrangement.End"], 0, "Mengisi sisa ruang."], ["Lencana di pojok kanan atas foto produk di Flutter memakai?", ["Row", "Stack + Positioned", "ListView"], 1, "Elemen bertumpuk."]], "so": [{"q": "Terjemahkan ke Flutter: frame horizontal, padding 16, gap 12, align center; anak: avatar 40×40, kolom teks (Fill), ikon chevron (Hug).", "h": "Row + Expanded untuk Fill.", "a": "Padding(\n  padding: const EdgeInsets.all(16),\n  child: Row(\n    spacing: 12,\n    children: [\n      const CircleAvatar(radius: 20),\n      Expanded(\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: const [Text('Rina Siregar'), Text('Flutter Developer')],\n        ),\n      ),\n      const Icon(Icons.chevron_right),\n    ],\n  ),\n)", "lang": "dart"}]}, {"k": "c", "t": "Layar login di Flutter", "nodes": [], "b": ["Desain login: logo, judul \"Masuk\", subjudul, field email, field kata sandi dengan tombol tampilkan, link \"Lupa kata sandi\" rata kanan, tombol Masuk lebar penuh, dan teks \"Belum punya akun? Daftar\" di bawah. Padding layar 24, gap antar field 16, tombol tinggi 52.", "Strukturnya: <code>Scaffold</code> → <code>SafeArea</code> → <code>SingleChildScrollView</code> (agar tidak tertutup keyboard) → <code>Padding</code> → <code>Column</code>. Warna dan teks diambil dari tema. Field memakai <code>TextFormField</code> dengan <code>InputDecoration</code> berlabel, bukan hanya hint.", "Perhatikan detail dari desain yang sering terlewat: <code>keyboardType: TextInputType.emailAddress</code>, <code>textInputAction: TextInputAction.next</code> agar tombol keyboard pindah ke field berikutnya, dan <code>autofillHints</code> agar pengelola sandi bisa mengisi otomatis."], "lang": "dart", "code": "class LoginPage extends StatefulWidget {\n  const LoginPage({super.key});\n  @override\n  State<LoginPage> createState() => _LoginPageState();\n}\n\nclass _LoginPageState extends State<LoginPage> {\n  bool _sembunyi = true;\n\n  @override\n  Widget build(BuildContext context) {\n    final t = Theme.of(context);\n    return Scaffold(\n      body: SafeArea(\n        child: SingleChildScrollView(\n          padding: const EdgeInsets.all(24),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            spacing: 16,\n            children: [\n              const SizedBox(height: 32),\n              Text('Masuk', style: t.textTheme.headlineMedium),\n              Text('Lanjutkan belajarmu hari ini.', style: t.textTheme.bodyLarge),\n              const TextField(\n                keyboardType: TextInputType.emailAddress,\n                textInputAction: TextInputAction.next,\n                autofillHints: [AutofillHints.email],\n                decoration: InputDecoration(labelText: 'Email', border: OutlineInputBorder()),\n              ),\n              TextField(\n                obscureText: _sembunyi,\n                autofillHints: const [AutofillHints.password],\n                decoration: InputDecoration(\n                  labelText: 'Kata sandi',\n                  border: const OutlineInputBorder(),\n                  suffixIcon: IconButton(\n                    tooltip: _sembunyi ? 'Tampilkan sandi' : 'Sembunyikan sandi',\n                    icon: Icon(_sembunyi ? Icons.visibility : Icons.visibility_off),\n                    onPressed: () => setState(() => _sembunyi = !_sembunyi),\n                  ),\n                ),\n              ),\n              Align(\n                alignment: Alignment.centerRight,\n                child: TextButton(onPressed: () {}, child: const Text('Lupa kata sandi?')),\n              ),\n              FilledButton(\n                style: FilledButton.styleFrom(minimumSize: const Size.fromHeight(52)),\n                onPressed: () {},\n                child: const Text('Masuk'),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}", "pts": ["Scaffold → SafeArea → SingleChildScrollView → Column.", "labelText, keyboardType, textInputAction, autofillHints.", "Tombol lebar penuh: minimumSize Size.fromHeight(52)."], "q": [["Kenapa layar login dibungkus SingleChildScrollView?", ["Agar tidak tertutup keyboard dan bisa digulir", "Agar lebih cepat", "Wajib di Flutter"], 0, "Keyboard memakan separuh layar."], ["Properti yang membuat tombol keyboard pindah ke field berikutnya?", ["textInputAction: TextInputAction.next", "autofocus: true", "maxLines: 2"], 0, "Keyboard menampilkan tombol Next."]], "so": [{"q": "Tambahkan validasi pada field email login: wajib diisi dan harus mengandung @, dengan pesan error berbahasa Indonesia.", "h": "TextFormField + validator di dalam Form.", "a": "TextFormField(\n  decoration: const InputDecoration(labelText: 'Email', border: OutlineInputBorder()),\n  keyboardType: TextInputType.emailAddress,\n  validator: (v) {\n    if (v == null || v.trim().isEmpty) return 'Email wajib diisi';\n    if (!v.contains('@')) return 'Format email belum benar, contoh: nama@contoh.com';\n    return null;\n  },\n)", "lang": "dart"}]}, {"k": "c", "t": "Layar login di Jetpack Compose", "nodes": [], "b": ["Desain yang sama di Compose: <code>Scaffold</code> memberi <code>innerPadding</code> untuk inset sistem, lalu <code>Column</code> dengan <code>verticalScroll</code>, <code>imePadding()</code> agar naik di atas keyboard, dan <code>Arrangement.spacedBy(16.dp)</code> untuk gap.", "State field disimpan dengan <code>rememberSaveable</code> agar tidak hilang saat layar diputar. <code>OutlinedTextField</code> sudah punya label mengambang sesuai Material 3. Opsi keyboard diatur lewat <code>KeyboardOptions</code>.", "Nilai ukuran diambil langsung dari Figma: padding 24.dp, tinggi tombol 52.dp, radius 12.dp. Warna dan gaya teks dari <code>MaterialTheme</code>."], "lang": "kotlin", "code": "@Composable\nfun LoginScreen(onMasuk: (String, String) -> Unit) {\n    var email by rememberSaveable { mutableStateOf(\"\") }\n    var sandi by rememberSaveable { mutableStateOf(\"\") }\n    var sembunyi by rememberSaveable { mutableStateOf(true) }\n\n    Scaffold { innerPadding ->\n        Column(\n            modifier = Modifier\n                .padding(innerPadding)\n                .imePadding()\n                .verticalScroll(rememberScrollState())\n                .padding(24.dp),\n            verticalArrangement = Arrangement.spacedBy(16.dp)\n        ) {\n            Spacer(Modifier.height(32.dp))\n            Text(\"Masuk\", style = MaterialTheme.typography.headlineMedium)\n            Text(\"Lanjutkan belajarmu hari ini.\", style = MaterialTheme.typography.bodyLarge)\n            OutlinedTextField(\n                value = email, onValueChange = { email = it },\n                label = { Text(\"Email\") }, singleLine = true,\n                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email, imeAction = ImeAction.Next),\n                modifier = Modifier.fillMaxWidth()\n            )\n            OutlinedTextField(\n                value = sandi, onValueChange = { sandi = it },\n                label = { Text(\"Kata sandi\") }, singleLine = true,\n                visualTransformation = if (sembunyi) PasswordVisualTransformation() else VisualTransformation.None,\n                trailingIcon = {\n                    IconButton(onClick = { sembunyi = !sembunyi }) {\n                        Icon(\n                            if (sembunyi) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,\n                            contentDescription = if (sembunyi) \"Tampilkan sandi\" else \"Sembunyikan sandi\"\n                        )\n                    }\n                },\n                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password, imeAction = ImeAction.Done),\n                modifier = Modifier.fillMaxWidth()\n            )\n            TextButton(onClick = {}, modifier = Modifier.align(Alignment.End)) { Text(\"Lupa kata sandi?\") }\n            Button(\n                onClick = { onMasuk(email, sandi) },\n                shape = RoundedCornerShape(12.dp),\n                modifier = Modifier.fillMaxWidth().height(52.dp)\n            ) { Text(\"Masuk\") }\n        }\n    }\n}", "pts": ["Scaffold innerPadding + imePadding + verticalScroll.", "rememberSaveable untuk state field.", "contentDescription untuk ikon yang bisa ditekan."], "q": [["Modifier yang membuat konten naik di atas keyboard?", ["imePadding()", "fillMaxSize()", "clip()"], 0, "IME = keyboard di layar."], ["Kenapa memakai rememberSaveable, bukan remember?", ["Isi field tidak hilang saat layar diputar", "Lebih cepat", "Wajib untuk TextField"], 0, "Bertahan saat konfigurasi berubah."]], "so": [{"q": "Tampilkan pesan error di bawah OutlinedTextField email jika tidak mengandung @.", "h": "Parameter isError dan supportingText.", "a": "val salah = email.isNotEmpty() && !email.contains(\"@\")\nOutlinedTextField(\n    value = email, onValueChange = { email = it },\n    label = { Text(\"Email\") },\n    isError = salah,\n    supportingText = { if (salah) Text(\"Format email belum benar, contoh: nama@contoh.com\") },\n    modifier = Modifier.fillMaxWidth()\n)", "lang": "kotlin"}]}]}, {"t": "Slicing daftar, kartu, dan navigasi", "lvl": "Menengah", "d": "Grid kartu produk di Flutter dan Compose, serta bottom navigation dan top app bar sesuai desain.", "nodes": ["Grid", "Cards", "Navigation bar"], "lessons": [{"k": "c", "t": "Kartu produk dan grid di Flutter", "nodes": [], "b": ["Desain katalog: grid 2 kolom, gap 12, padding layar 16. Kartu berisi foto rasio 1:1 dengan radius 12, nama produk (maksimal 2 baris), harga tebal berwarna primary, dan tombol tambah kecil.", "Pakai <code>GridView.builder</code> dengan <code>SliverGridDelegateWithFixedCrossAxisCount</code> (jumlah kolom tetap) atau <code>SliverGridDelegateWithMaxCrossAxisExtent</code> (lebar maksimum kartu, jumlah kolom menyesuaikan layar, mirip auto-fill di CSS). Atur <code>childAspectRatio</code> agar tinggi kartu cukup untuk foto dan teks, atau pakai <code>mainAxisExtent</code> untuk tinggi tetap.", "Teks panjang dibatasi dengan <code>maxLines: 2</code> dan <code>overflow: TextOverflow.ellipsis</code>. Format harga Rupiah dengan paket <code>intl</code>: <code>NumberFormat.currency(locale: 'id', symbol: 'Rp', decimalDigits: 0)</code>."], "lang": "dart", "code": "final rupiah = NumberFormat.currency(locale: 'id', symbol: 'Rp', decimalDigits: 0);\n\nGridView.builder(\n  padding: const EdgeInsets.all(16),\n  gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(\n    maxCrossAxisExtent: 200,\n    mainAxisSpacing: 12,\n    crossAxisSpacing: 12,\n    mainAxisExtent: 260,\n  ),\n  itemCount: produk.length,\n  itemBuilder: (context, i) {\n    final p = produk[i];\n    final t = Theme.of(context);\n    return Card(\n      clipBehavior: Clip.antiAlias,\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          AspectRatio(aspectRatio: 1, child: Image.asset(p.foto, fit: BoxFit.cover)),\n          Padding(\n            padding: const EdgeInsets.all(12),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              spacing: 4,\n              children: [\n                Text(p.nama, maxLines: 2, overflow: TextOverflow.ellipsis, style: t.textTheme.titleSmall),\n                Text(rupiah.format(p.harga),\n                    style: t.textTheme.titleMedium?.copyWith(color: t.colorScheme.primary, fontWeight: FontWeight.w700)),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  },\n)", "out": "Kopi Susu Aren\nRp22.000", "run": false, "pts": ["GridView.builder dengan MaxCrossAxisExtent mirip auto-fill.", "AspectRatio 1 + BoxFit.cover untuk foto.", "maxLines + ellipsis, format Rupiah dengan intl."], "q": [["Delegate yang menyesuaikan jumlah kolom dengan lebar layar?", ["SliverGridDelegateWithMaxCrossAxisExtent", "SliverGridDelegateWithFixedCrossAxisCount"], 0, "Menentukan lebar maksimum, bukan jumlah kolom."]], "so": [{"q": "Tambahkan lencana \"Baru\" di pojok kiri atas foto kartu produk.", "h": "Stack dengan Positioned.", "a": "Stack(\n  children: [\n    AspectRatio(aspectRatio: 1, child: Image.asset(p.foto, fit: BoxFit.cover)),\n    Positioned(\n      top: 8, left: 8,\n      child: Container(\n        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),\n        decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(99)),\n        child: const Text('Baru', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),\n      ),\n    ),\n  ],\n)", "lang": "dart"}]}, {"k": "c", "t": "Kartu produk dan LazyVerticalGrid di Compose", "nodes": [], "b": ["Di Compose, grid yang bisa digulir adalah <code>LazyVerticalGrid</code>. <code>GridCells.Fixed(2)</code> untuk dua kolom tetap, atau <code>GridCells.Adaptive(minSize = 160.dp)</code> untuk jumlah kolom yang menyesuaikan layar, persis seperti <code>auto-fill minmax(160px, 1fr)</code> di CSS.", "Kartu memakai <code>Card</code> Material 3. Foto dimuat dari internet dengan pustaka <b>Coil</b> (<code>AsyncImage</code>) dan dipotong dengan <code>ContentScale.Crop</code> serta <code>Modifier.aspectRatio(1f)</code>.", "Beri setiap item <code>key</code> yang stabil (misalnya id produk) agar Compose tidak menggambar ulang semua kartu saat daftar berubah."], "lang": "kotlin", "code": "@Composable\nfun KatalogGrid(produk: List<Produk>, onTambah: (Produk) -> Unit) {\n    val rupiah = remember { NumberFormat.getCurrencyInstance(Locale(\"id\", \"ID\")).apply { maximumFractionDigits = 0 } }\n    LazyVerticalGrid(\n        columns = GridCells.Adaptive(minSize = 160.dp),\n        contentPadding = PaddingValues(16.dp),\n        horizontalArrangement = Arrangement.spacedBy(12.dp),\n        verticalArrangement = Arrangement.spacedBy(12.dp)\n    ) {\n        items(produk, key = { it.id }) { p ->\n            Card(shape = RoundedCornerShape(12.dp)) {\n                AsyncImage(\n                    model = p.fotoUrl, contentDescription = p.nama,\n                    contentScale = ContentScale.Crop,\n                    modifier = Modifier.fillMaxWidth().aspectRatio(1f)\n                )\n                Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {\n                    Text(p.nama, maxLines = 2, overflow = TextOverflow.Ellipsis, style = MaterialTheme.typography.titleSmall)\n                    Text(\n                        rupiah.format(p.harga),\n                        style = MaterialTheme.typography.titleMedium,\n                        fontWeight = FontWeight.Bold,\n                        color = MaterialTheme.colorScheme.primary\n                    )\n                }\n            }\n        }\n    }\n}", "pts": ["LazyVerticalGrid + GridCells.Adaptive mirip auto-fill.", "AsyncImage (Coil) + ContentScale.Crop + aspectRatio.", "key yang stabil untuk setiap item."], "q": [["GridCells.Adaptive(160.dp) di layar 400dp (abaikan padding) menghasilkan berapa kolom?", ["1", "2", "3"], 1, "400 / 160 = 2 kolom muat."]], "so": [{"q": "Tambahkan lencana \"Baru\" di pojok kiri atas foto kartu Compose.", "h": "Box dengan Modifier.align(Alignment.TopStart).", "a": "Box {\n    AsyncImage(model = p.fotoUrl, contentDescription = p.nama, contentScale = ContentScale.Crop,\n        modifier = Modifier.fillMaxWidth().aspectRatio(1f))\n    Surface(\n        shape = CircleShape, color = Color.White,\n        modifier = Modifier.align(Alignment.TopStart).padding(8.dp)\n    ) {\n        Text(\"Baru\", style = MaterialTheme.typography.labelMedium, modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp))\n    }\n}", "lang": "kotlin"}]}, {"k": "c", "t": "Bottom navigation dan top app bar", "nodes": [], "b": ["Material 3 menyebut bottom navigation sebagai <b>NavigationBar</b>: 3 sampai 5 tujuan, ikon dan label, indikator pill di item aktif. Di Flutter: <code>NavigationBar</code> dengan <code>NavigationDestination</code>. Di Compose: <code>NavigationBar</code> dengan <code>NavigationBarItem</code>.", "Gunakan ikon <b>outlined</b> untuk item tidak aktif dan <b>filled</b> untuk item aktif jika desain memintanya (Flutter: <code>icon</code> dan <code>selectedIcon</code>). Badge jumlah notifikasi memakai widget <code>Badge</code> di keduanya.", "<b>Top app bar</b>: <code>AppBar</code> (Flutter) atau <code>TopAppBar</code> / <code>CenterAlignedTopAppBar</code> (Compose). Desain dengan judul besar yang mengecil saat menggulir menjadi <code>SliverAppBar.large</code> di Flutter dan <code>LargeTopAppBar</code> dengan <code>scrollBehavior</code> di Compose."], "lang": "dart", "code": "// Flutter\nNavigationBar(\n  selectedIndex: indeks,\n  onDestinationSelected: (i) => setState(() => indeks = i),\n  destinations: const [\n    NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Beranda'),\n    NavigationDestination(icon: Icon(Icons.menu_book_outlined), selectedIcon: Icon(Icons.menu_book), label: 'Menu'),\n    NavigationDestination(\n      icon: Badge(label: Text('2'), child: Icon(Icons.shopping_bag_outlined)),\n      selectedIcon: Icon(Icons.shopping_bag), label: 'Pesanan'),\n    NavigationDestination(icon: Icon(Icons.person_outline), selectedIcon: Icon(Icons.person), label: 'Profil'),\n  ],\n)\n\n// Jetpack Compose\nNavigationBar {\n    tujuan.forEachIndexed { i, t ->\n        NavigationBarItem(\n            selected = indeks == i,\n            onClick = { indeks = i },\n            icon = { Icon(if (indeks == i) t.ikonAktif else t.ikon, contentDescription = null) },\n            label = { Text(t.label) }\n        )\n    }\n}", "pts": ["NavigationBar: 3–5 tujuan, ikon + label, indikator.", "icon dan selectedIcon untuk outlined dan filled.", "SliverAppBar.large / LargeTopAppBar untuk judul besar yang mengecil."], "q": [["Kenapa contentDescription ikon NavigationBarItem boleh null?", ["Karena label teks sudah menjelaskan tujuannya", "Karena ikon tidak penting", "Aturan Kotlin"], 0, "Menghindari dibacakan dua kali."]], "so": [{"q": "Buat CenterAlignedTopAppBar dengan judul \"KopiNusa\" dan tombol ikon keranjang di kanan.", "h": "actions berisi IconButton dengan contentDescription.", "a": "CenterAlignedTopAppBar(\n    title = { Text(\"KopiNusa\") },\n    actions = {\n        IconButton(onClick = onKeranjang) {\n            Icon(Icons.Outlined.ShoppingCart, contentDescription = \"Keranjang\")\n        }\n    }\n)", "lang": "kotlin"}]}]}, {"t": "Responsif dan pixel-perfect mobile", "lvl": "Menengah", "d": "Layar berbagai ukuran dengan LayoutBuilder dan WindowSizeClass, pengujian pixel-perfect dengan golden dan screenshot test, serta proyek slicing aplikasi kedai kopi.", "nodes": ["Adaptive layout", "Golden tests", "Project"], "lessons": [{"k": "c", "t": "Layar berbagai ukuran", "nodes": [], "b": ["Desain biasanya hanya untuk ponsel 360 sampai 393 dp, tetapi aplikasi juga berjalan di ponsel kecil (320 dp), ponsel lipat, dan tablet. Uji desain di ukuran <b>terkecil</b> (teks tidak terpotong, tombol tidak bertumpuk) dan <b>terbesar</b> (konten tidak melar terlalu lebar).", "Flutter: <code>LayoutBuilder</code> memberi lebar induk, <code>MediaQuery.sizeOf(context)</code> memberi ukuran layar. Compose: <code>currentWindowAdaptiveInfo().windowSizeClass</code> memberi kelas <b>compact</b> (&lt; 600 dp), <b>medium</b> (600 sampai 839), dan <b>expanded</b> (≥ 840). Pustaka <b>adaptive navigation suite</b> otomatis mengganti NavigationBar menjadi NavigationRail di layar lebar.", "Jangan lupa pengguna dengan <b>ukuran huruf besar</b> di pengaturan sistem. Uji dengan skala huruf 1,3× dan 2×: tinggi tetap pada kontainer teks adalah penyebab utama teks terpotong. Pakai tinggi minimum, bukan tinggi tetap."], "lang": "dart", "code": "// Flutter: 2 kolom di ponsel, 4 kolom mulai 600 dp\nLayoutBuilder(\n  builder: (context, c) {\n    final kolom = c.maxWidth >= 840 ? 4 : c.maxWidth >= 600 ? 3 : 2;\n    return GridView.count(crossAxisCount: kolom, children: kartu);\n  },\n)\n\n// Compose: NavigationBar di ponsel, NavigationRail di layar lebar\nval kelas = currentWindowAdaptiveInfo().windowSizeClass\nif (kelas.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_MEDIUM_LOWER_BOUND)) {\n    Row { NavigationRail { /* ... */ }; Konten() }\n} else {\n    Scaffold(bottomBar = { NavigationBar { /* ... */ } }) { Konten() }\n}", "tb": [{"c": "Kelas ukuran jendela", "h": ["Kelas", "Lebar", "Contoh perangkat", "Navigasi"], "r": [["Compact", "< 600 dp", "Ponsel tegak", "NavigationBar"], ["Medium", "600–839 dp", "Tablet tegak, lipat terbuka", "NavigationRail"], ["Expanded", "≥ 840 dp", "Tablet mendatar, desktop", "NavigationRail atau drawer"]]}], "pts": ["Uji di ukuran terkecil dan terbesar.", "LayoutBuilder / WindowSizeClass: compact, medium, expanded.", "Uji skala huruf 1,3× dan 2×; hindari tinggi tetap."], "q": [["Teks terpotong saat pengguna memperbesar huruf. Penyebab paling umum?", ["Kontainer dengan tinggi tetap", "Warna teks", "Font tidak terpasang"], 0, "Pakai tinggi minimum."]], "so": [{"q": "Batasi lebar konten maksimal 600 dan letakkan di tengah agar tidak melar di tablet.", "h": "Center + ConstrainedBox.", "a": "Center(\n  child: ConstrainedBox(\n    constraints: const BoxConstraints(maxWidth: 600),\n    child: konten,\n  ),\n)", "lang": "dart"}]}, {"k": "c", "t": "Pixel-perfect dan golden test", "nodes": [], "b": ["Di mobile, membandingkan dengan desain dilakukan dengan menjalankan aplikasi di emulator berukuran sama dengan frame Figma (misalnya Pixel 7, 412 × 915 dp), mengambil tangkapan layar, lalu menumpuknya dengan ekspor frame di Figma (opacity 50%). Flutter juga punya <b>Flutter Inspector</b> dengan \"Show guidelines\" untuk melihat padding dan batas widget.", "Agar tampilan yang sudah benar tidak rusak diam-diam di kemudian hari, buat <b>golden test</b> (Flutter) atau <b>screenshot test</b> (Compose, dengan Roborazzi atau Paparazzi). Tes merender widget, menyimpan gambar acuan, dan gagal jika tampilan berubah walau satu piksel.", "Simpan gambar acuan di repositori, dan perbarui hanya jika perubahan tampilan memang disengaja (<code>flutter test --update-goldens</code>)."], "lang": "dart", "code": "// test/kartu_produk_golden_test.dart\nvoid main() {\n  testWidgets('KartuProduk sesuai desain', (tester) async {\n    tester.view.physicalSize = const Size(360, 300);\n    tester.view.devicePixelRatio = 1.0;\n    await tester.pumpWidget(MaterialApp(\n      theme: temaKopiNusa,\n      home: const Scaffold(body: KartuProduk(nama: 'Kopi Susu Aren', harga: 22000)),\n    ));\n    await expectLater(find.byType(KartuProduk), matchesGoldenFile('goldens/kartu_produk.png'));\n  });\n}\n\n// Jalankan pertama kali (membuat gambar acuan):\n//   flutter test --update-goldens\n// Jalankan berikutnya (membandingkan):\n//   flutter test", "pts": ["Bandingkan di emulator berukuran sama dengan frame Figma.", "Golden test (Flutter) dan screenshot test (Roborazzi, Paparazzi).", "Perbarui acuan hanya untuk perubahan yang disengaja."], "q": [["Apa fungsi golden test?", ["Mendeteksi perubahan tampilan yang tidak disengaja", "Menguji kecepatan jaringan", "Mengompres gambar"], 0, "Gambar acuan dibandingkan setiap kali tes jalan."]], "so": [{"q": "Tulis langkah membandingkan layar Beranda di emulator dengan frame Figma.", "h": "Ukuran sama, tangkapan layar, tumpuk dengan opacity.", "a": "1. Buat emulator dengan lebar sama dengan frame (misal 412 dp).\n2. Jalankan aplikasi, ambil tangkapan layar Beranda.\n3. Ekspor frame Figma pada skala yang sama dengan densitas emulator.\n4. Tumpuk di Figma: tangkapan layar di atas, opacity 50%.\n5. Catat selisih jarak, ukuran huruf, warna; perbaiki yang berdampak besar dulu.", "lang": "text"}]}, {"k": "c", "t": "Proyek: slicing aplikasi kedai kopi", "nodes": [], "b": ["Proyek akhir: slicing empat layar aplikasi KopiNusa dari desain (atau buat desain sederhana sendiri di Figma terlebih dahulu): <b>Login</b>, <b>Beranda</b> (sapaan, banner promo, kategori chip, grid produk), <b>Detail produk</b> (foto besar, pilihan ukuran dan gula dengan SegmentedButton atau ChoiceChip, jumlah, tombol Tambah), dan <b>Keranjang</b> (daftar item, total, tombol Bayar).", "Pilih salah satu: Flutter atau Jetpack Compose. Kerjakan berurutan: tema dan token dulu, lalu komponen (KartuProduk, ChipKategori, BarisKeranjang), baru susun layar. Pakai data dummy dari list lokal.", "Kriteria selesai di tabel bawah. Unggah ke GitHub dengan README berisi tangkapan layar setiap layar dan perbandingan dengan desain."], "tb": [{"c": "Kriteria selesai", "h": ["Aspek", "Kriteria"], "r": [["Tema", "Warna dan teks dari ColorScheme dan TextTheme/Typography, tidak ada hex di widget"], ["Komponen", "Minimal 3 komponen dipakai ulang dengan parameter"], ["Layout", "Tidak ada overflow di 320 dp dan di skala huruf 1,3×"], ["Navigasi", "NavigationBar 4 tujuan, kembali dari detail ke beranda"], ["Aksesibilitas", "Target sentuh 48 dp, contentDescription / semanticLabel untuk ikon"], ["Format", "Harga Rupiah Rp22.000"], ["Uji", "Minimal 1 golden atau screenshot test untuk KartuProduk"], ["Dokumentasi", "README dengan tangkapan layar dan cara menjalankan"]]}], "pts": ["Tema dulu, komponen, lalu layar.", "Uji 320 dp dan skala huruf besar.", "README dengan perbandingan desain."], "q": [["Urutan kerja slicing aplikasi yang disarankan?", ["Layar dulu, tema terakhir", "Tema dan token, komponen, lalu layar", "Acak"], 1, "Fondasi dulu agar tidak menulis ulang."]], "so": [{"q": "Tulis daftar komponen yang akan kamu buat untuk proyek KopiNusa beserta parameternya.", "h": "Komponen yang muncul lebih dari sekali.", "a": "KartuProduk(nama, harga, foto, onTambah)\nChipKategori(label, terpilih, onTap)\nBannerPromo(judul, subjudul, gambar)\nPemilihJumlah(nilai, onKurang, onTambah)\nBarisKeranjang(produk, jumlah, onUbah, onHapus)\nTombolUtama(label, onPressed, memuat)", "lang": "text"}]}]}];
